using System.Collections.Generic;

namespace SBR.Engine;

public static class SlateGenerator
{
    private static readonly string[] Cities =
    {
        "Atlanta", "San Francisco", "Tuscaloosa", "Moose Jaw", "Denver", "Sheboygan",
        "Fresno", "Waterloo", "Pawtucket", "Duluth", "Reno", "Scranton",
        "Boise", "Tulsa", "Omaha", "Yonkers",
    };

    private static readonly string[] Nouns =
    {
        "Yams", "Startups", "Bricklayers", "Longhaulers", "Mallards", "Spreadsheets",
        "Turnips", "Middlemen", "Regulators", "Plumbers", "Meatballs", "Auditors",
        "Ferrets", "Overheads", "Gravediggers", "Notaries", "Muskrats", "Zambonis",
        "Loopholes", "Refunds",
    };

    public static Slate Generate(int round, Pcg32 rng, RunConfig config)
    {
        // Unique noun per team keeps names distinct within a slate; cities may repeat.
        int[] nounOrder = ShuffledIndices(Nouns.Length, rng);

        var matchups = new List<Matchup>(config.MatchupsPerSlate);
        for (int i = 0; i < config.MatchupsPerSlate; i++)
        {
            double p = config.MinTrueProb + (config.MaxTrueProb - config.MinTrueProb) * rng.NextDouble();

            // Records are the round's only free information: a noisy binomial signal of true strength.
            Team home = MakeTeam(nounOrder[i * 2], rng, config, p);
            Team away = MakeTeam(nounOrder[i * 2 + 1], rng, config, 1.0 - p);

            (double homeOdds, double awayOdds) = OddsMath.OverroundOdds(p, config.Overround);
            matchups.Add(new Matchup(i, home, away, p, homeOdds, awayOdds));
        }

        return new Slate(round, matchups);
    }

    private static Team MakeTeam(int nounIndex, Pcg32 rng, RunConfig config, double strength)
    {
        string name = $"{Cities[rng.NextInt(0, Cities.Length)]} {Nouns[nounIndex]}";
        int wins = Binomial(rng, config.PriorGames, strength);
        return new Team(name, wins, config.PriorGames - wins);
    }

    private static int Binomial(Pcg32 rng, int n, double p)
    {
        int k = 0;
        for (int i = 0; i < n; i++)
            if (rng.NextDouble() < p) k++;
        return k;
    }

    private static int[] ShuffledIndices(int length, Pcg32 rng)
    {
        var indices = new int[length];
        for (int i = 0; i < length; i++) indices[i] = i;
        for (int i = length - 1; i > 0; i--)
        {
            int j = rng.NextInt(0, i + 1);
            (indices[i], indices[j]) = (indices[j], indices[i]);
        }
        return indices;
    }
}

using System;
using System.Collections.Generic;

namespace SBR.Engine;

/// <summary>
/// Pure betting math per design/02. Everything is decimal odds internally;
/// American odds exist only at the display boundary.
/// </summary>
public static class OddsMath
{
    public static double ImpliedProb(double decimalOdds)
    {
        RequireOdds(decimalOdds);
        return 1.0 / decimalOdds;
    }

    public static double FairDecimal(double p)
    {
        RequireProb(p);
        return 1.0 / p;
    }

    public static int AmericanFromDecimal(double decimalOdds)
    {
        RequireOdds(decimalOdds);
        return decimalOdds >= 2.0
            ? (int)Math.Round(100.0 * (decimalOdds - 1.0))
            : -(int)Math.Round(100.0 / (decimalOdds - 1.0));
    }

    public static double DecimalFromAmerican(int american)
    {
        if (american >= 100) return 1.0 + american / 100.0;
        if (american <= -100) return 1.0 + 100.0 / -american;
        throw new ArgumentException($"American odds must be >= +100 or <= -100, got {american}");
    }

    /// <summary>
    /// Prices a two-way market at true probability plus a proportional overround,
    /// so implied probabilities sum to 1 + overround (design/02 vig definition).
    /// </summary>
    public static (double home, double away) OverroundOdds(double trueHomeProb, double overround)
    {
        RequireProb(trueHomeProb);
        if (overround < 0) throw new ArgumentException("overround must be >= 0");
        double qHome = trueHomeProb * (1.0 + overround);
        double qAway = (1.0 - trueHomeProb) * (1.0 + overround);
        return (1.0 / qHome, 1.0 / qAway);
    }

    public static double Ev(double p, double stake, double decimalOdds)
    {
        RequireProb(p);
        RequireOdds(decimalOdds);
        return stake * (p * decimalOdds - 1.0);
    }

    public static double ParlayDecimal(IReadOnlyList<double> legOdds)
    {
        double product = 1.0;
        for (int i = 0; i < legOdds.Count; i++)
        {
            RequireOdds(legOdds[i]);
            product *= legOdds[i];
        }
        return product;
    }

    public static double ParlayProb(IReadOnlyList<double> legProbs)
    {
        double product = 1.0;
        for (int i = 0; i < legProbs.Count; i++)
        {
            RequireProb(legProbs[i]);
            product *= legProbs[i];
        }
        return product;
    }

    /// <summary>The EV haircut the book took at ticket lock: s × (1 − o_offered / o_fair).</summary>
    public static double VigPaid(double stake, double offeredDecimal, double fairDecimal)
    {
        RequireOdds(offeredDecimal);
        RequireOdds(fairDecimal);
        return stake * (1.0 - offeredDecimal / fairDecimal);
    }

    /// <summary>
    /// Fair value of a partially resolved parlay: s × Π(o_resolved) × Π(p_j × o_j remaining).
    /// Anchors: nothing resolved → P(win) × payout; everything resolved → full payout.
    /// </summary>
    public static double CashOutFair(double stake, double resolvedOddsProduct, IReadOnlyList<(double p, double o)> remainingLegs)
    {
        double value = stake * resolvedOddsProduct;
        for (int i = 0; i < remainingLegs.Count; i++)
        {
            RequireProb(remainingLegs[i].p);
            RequireOdds(remainingLegs[i].o);
            value *= remainingLegs[i].p * remainingLegs[i].o;
        }
        return value;
    }

    public static double CashOutOffer(double fairValue, double margin) => fairValue * (1.0 - margin);

    private static void RequireOdds(double o)
    {
        if (o <= 1.0 || double.IsNaN(o) || double.IsInfinity(o))
            throw new ArgumentException($"Decimal odds must be > 1, got {o}");
    }

    private static void RequireProb(double p)
    {
        if (p <= 0.0 || p >= 1.0 || double.IsNaN(p))
            throw new ArgumentException($"Probability must be in (0, 1), got {p}");
    }
}

using System;
using System.Collections.Generic;
using SBR.Engine;

namespace SBR.Sim;

/// <summary>
/// NAIVE — the PRD S3 baseline: "bet favorites, never cash out, no relics" (target: median death round 3–4).
///
/// Policy, every round:
///   • One 2-leg parlay on the two biggest favorites. The bot cannot see true probs, so it reads the
///     ODDS: the two shortest-priced sides on the slate (each matchup's favorite is its shorter side, so
///     the two globally shortest sides always land on distinct matchups — a legal ticket).
///   • Stake = 25% of the current bank, floored to whole dollars, never below MinStake; skip the round's
///     bet entirely if the bank is under MinStake (per the OPEN-QUESTIONS playtest note — a bank fraction,
///     NOT the old flat $50 cap that made a naive bettor mathematically unable to clear round 1).
///   • Never cashes out (ControlsSweat = false → the harness fast-forwards the sweat).
///   • Buys nothing.
///
/// HONESTY: reads only Matchup.Odds/HomeOdds/AwayOdds (public book prices). Never touches true probs.
/// </summary>
public sealed class NaiveStrategy : IStrategy
{
    public string Name => "naive";
    public bool ControlsSweat => false;

    private const double StakeFraction = 0.25;
    private const int Legs = 2;

    public void Bet(Run run, BotState state, Pcg32 rng)
    {
        if (run.Bank < run.Config.MinStake) return;

        double stake = Math.Max(run.Config.MinStake, Math.Floor(StakeFraction * run.Bank));
        if (stake > run.Bank) return; // defensive; StakeFraction < 1 keeps this from tripping

        IReadOnlyList<Matchup> slate = run.CurrentSlate.Matchups;
        if (slate.Count < Legs) return;

        // Each matchup's favorite (shorter-priced side) and its odds.
        var favs = new List<(int matchup, Side side, double odds)>(slate.Count);
        foreach (Matchup m in slate)
        {
            Side fav = m.HomeOdds <= m.AwayOdds ? Side.Home : Side.Away;
            favs.Add((m.Index, fav, m.Odds(fav)));
        }
        favs.Sort((a, b) => a.odds.CompareTo(b.odds)); // shortest-priced first

        var picks = new List<Pick>(Legs);
        for (int i = 0; i < Legs; i++)
            picks.Add(new Pick(favs[i].matchup, favs[i].side));

        run.PlaceTicket(picks, stake);
    }

    // Never called (ControlsSweat is false), but the interface requires it.
    public bool ShouldCashOut(Run run, Ticket ticket, SweatSession session, DramaEvent evt,
        double offer, double bankNow, double target, BotState state, Pcg32 rng) => false;

    public void Shop(Run run, BotState state, Pcg32 rng) { /* buys nothing */ }
}

namespace SBR.Engine;

/// <summary>Tuning defaults. The /sim harness exists to move these numbers — the economy rework's
/// gate campaign (PLAN.md 2026-07-13, gates G1–G6) owns the payment curve.</summary>
public sealed class RunConfig
{
    public double StartingBank { get; set; } = 350;

    /// <summary>The debt-payment schedule (economy rework, design/10): DEDUCTED from the bank at
    /// each settle — miss a payment and the run is over (unless the Totem fires). Two-phase convex
    /// (the campaign's discovered shape): gentle build window, then the cliff. Under the COMPS
    /// currency (design/10 F) the cash bank starts at only ~2–3 payments, so BETTING IS MANDATORY
    /// from round 1 — idling is death (Allen's round-1 ruling). The grid re-tunes these.</summary>
    public double[] Payments { get; set; } = { 60, 70, 85, 105, 155, 375, 710, 1350 };

    /// <summary>COMPS (design/10 F): the second currency, earned per dollar STAKED — the book's
    /// loyalty program, and items are bought with it. Chasing comps is −EV cash, exactly like a
    /// real VIP program; the shop no longer competes with payments for bankroll.</summary>
    public double CompsPerDollarStaked { get; set; } = 0.12;

    public double Overround { get; set; } = 0.05;
    public double CashOutMargin { get; set; } = 0.08;
    public double MinStake { get; set; } = 10;

    /// <summary>Cap on a single ticket's stake as a fraction of the current bank. 1.0 = uncapped (all-in
    /// allowed) — lifted 2026-07-08 after playtest #1. Kept as a dial for /sim experiments. Boundary
    /// inclusive: a stake exactly at the cap is allowed.</summary>
    public double MaxStakeFraction { get; set; } = 1.0;

    public int MaxTicketsPerRound { get; set; } = 3;
    public int MatchupsPerSlate { get; set; } = 6;
    public int MaxLegs { get; set; } = 6;
    public int PriorGames { get; set; } = 9;
    public double MinTrueProb { get; set; } = 0.25;
    public double MaxTrueProb { get; set; } = 0.75;

    /// <summary>Max passive relics owned at once. The rework catalog has 3 passives; slots stay
    /// roomier for the committed item-growth direction (design/10 B2).</summary>
    public int RelicSlots { get; set; } = 5;

    /// <summary>Max consumables held at once (separate pool from relics — playtest #1 split).
    /// 3 since playtest #8: with one shop offer per visit, a third slot lets a player bank saves
    /// for the cliff — the G3 band's buy-back for the tighter offer draw.</summary>
    public int ConsumableSlots { get; set; } = 3;

    /// <summary>Passive offers dealt per shop visit (charm expansion: the DEALT HAND — a random
    /// draw from the unowned pool replaces show-everything at catalog size 15). Tuned to 4:
    /// at 3 the engine-finding variance starved too many builds; at 5 the win rate rode the
    /// band ceiling. A specific item shows ~27%/visit at 4-of-15 — scarcity stays real.</summary>
    public int PassiveOfferCount { get; set; } = 4;

    /// <summary>Consumable offers dealt per shop visit. History: 2 → 1 at playtest #8 (a 2-item
    /// pool with 2 slots guaranteed the strongest item every shop) → 3 for the charm expansion:
    /// the 7-item pool does the dilution (a specific tool shows ~43% of visits), and the wider
    /// hand is where the toolbox decisions live.</summary>
    public int ConsumableOfferCount { get; set; } = 3;

    /// <summary>Sell-back fraction of list price, both pools (design/10, Allen 2026-07-12).</summary>
    public double SellBackFraction { get; set; } = 0.5;

    /// <summary>Consecutive net-losing rounds before the bookie texts a free consumable
    /// (the gift/pity channel, design/10 D), and the minimum rounds between gifts.</summary>
    public int GiftAfterLosingRounds { get; set; } = 2;
    public int GiftCooldownRounds { get; set; } = 2;

    /// <summary>Totem of Undying: the DEFERRED payment is added to the NEXT payment at
    /// payment × (1 + this rate). Playtest #8 made the totem leave the bank untouched; the G3
    /// campaign showed the juice barely moves win rate (the offer draw is the binding knob), so
    /// the ratified 0.5 stands.</summary>
    public double TotemJuiceRate { get; set; } = 0.5;

    /// <summary>Pacing dials for the drama generator (design/04); flows through Run into every SweatSession.</summary>
    public DramaConfig Drama { get; set; } = new DramaConfig();

    public int Rounds => Payments.Length;
}

using System;
using System.Collections.Generic;
using SBR.Engine;

namespace SBR.Sim;

/// <summary>
/// MARTYR — the G6 adversary, upgraded for the charm expansion (rev 5 §14): farms EVERY
/// loss-feeder — Scar Tissue stacks, Bad Beat Jar rounds, and Free Bet refunded busts — then
/// cashes on one safe carrier. If this beats organic skilled play by more than the gate's
/// margin, the farming guards have failed. The WORST-CASE variant (G6's actual gate) gets Scar
/// + Jar granted and a Free Bet refilled every round by the harness.
///
/// Policy:
///   • Shop: buys scar_tissue, bad_beat_jar, and free_bet tokens — nothing else.
///   • Farming rounds (stacks below the cash-in bar): two 2-leg LONGSHOT parlays (the lowest-p̂
///     sides) staked at the full-scar fraction — deliberately likely busts; a held Free Bet
///     rides the first farm ticket (refunded martyrdom — the loss still feeds Scar AND Jar).
///   • Cash-in rounds (stacks ≥ the bar): ONE ticket placed first (the carrier) — the single
///     highest-p̂ side, staked with everything above the payment reserve.
///   • Cash-out: survival-take only. Saves: never — busts are the harvest.
///
/// HONESTY: de-vig estimates only, like every bot.
/// </summary>
public sealed class MartyrStrategy : IStrategy
{
    private const double CashInStacks = 30.0;   // pp of scar before the martyr cashes in
    private const double FarmStakeFraction = 0.25; // the full-scar threshold — max pp per bust
    private const double PaymentReserve = 1.0;  // keep 100% of the payment out of farm stakes

    public string Name => "martyr";
    public bool ControlsSweat => true;

    /// <summary>The martyr NEVER saves a dying leg — busts are the harvest.</summary>
    public PendingLossAction ChoosePendingLossAction(Run run, Ticket ticket, SweatSession session,
        BotState state, Pcg32 rng) => PendingLossAction.Decline;

    public void Bet(Run run, BotState state, Pcg32 rng)
    {
        IReadOnlyList<Matchup> slate = run.CurrentSlate.Matchups;
        var sides = new List<(int m, Side s, double pHat, double odds)>(slate.Count);
        foreach (Matchup m in slate)
        {
            double implHome = 1.0 / m.HomeOdds;
            double pHome = implHome / (implHome + 1.0 / m.AwayOdds);
            // Track BOTH sides; the farmer wants longshots, the carrier wants the favorite.
            sides.Add((m.Index, Side.Home, pHome, m.HomeOdds));
            sides.Add((m.Index, Side.Away, 1.0 - pHome, m.AwayOdds));
        }

        double reserve = PaymentReserve * run.CurrentPayment;
        double budget = run.Bank - reserve;
        if (budget < run.Config.MinStake) return;

        if (run.ScarStacks >= CashInStacks)
        {
            // Cash-in: the carrier is the FIRST ticket placed — one safe single, everything spare.
            var best = sides[0];
            foreach (var c in sides) if (c.pHat > best.pHat) best = c;
            double stake = Math.Clamp(Math.Floor(budget), run.Config.MinStake, run.Bank);
            run.PlaceTicket(new List<Pick> { new Pick(best.m, best.s) }, stake);
            return;
        }

        // Farming: two 2-leg longshot parlays at the full-scar stake, distinct matchups.
        sides.Sort((a, b) => a.pHat.CompareTo(b.pHat)); // longest shots first
        var used = new HashSet<int>();
        var legsPool = new List<(int m, Side s)>();
        foreach (var c in sides)
            if (used.Add(c.m)) legsPool.Add((c.m, c.s));

        for (int t = 0; t < 2 && legsPool.Count >= (t + 1) * 2; t++)
        {
            double stake = Math.Floor(Math.Min(FarmStakeFraction * run.Bank, budget));
            if (stake < run.Config.MinStake) break;
            var picks = new List<Pick>
            {
                new Pick(legsPool[t * 2].m, legsPool[t * 2].s),
                new Pick(legsPool[t * 2 + 1].m, legsPool[t * 2 + 1].s),
            };
            // Refunded martyrdom: a held Free Bet rides the first farm ticket — the bust still
            // feeds Scar and the Jar, but the stake comes home.
            TicketModifier mod = t == 0 && run.OwnsConsumable("free_bet")
                ? TicketModifier.FreeBet : TicketModifier.None;
            run.PlaceTicket(picks, stake, -1, mod);
            budget -= stake;
        }
    }

    public bool ShouldCashOut(Run run, Ticket ticket, SweatSession session, DramaEvent evt,
        double offer, double bankNow, double target, BotState state, Pcg32 rng)
    {
        if (evt.Type == DramaEventType.LegFinal) return false;
        double remainingNeeded = target - bankNow;
        return remainingNeeded > 0 && offer >= remainingNeeded; // survival only — scars want busts
    }

    public void Shop(Run run, BotState state, Pcg32 rng)
    {
        // Loss-feeders only: Scar, Jar, and Free Bet tokens (rev 5 §14).
        bool bought = true;
        while (bought)
        {
            bought = false;
            if (run.OwnedRelics.Count < run.Config.RelicSlots)
            {
                for (int i = 0; i < run.ShopOffers.Count; i++)
                {
                    string id = run.ShopOffers[i].Id;
                    if (id != RelicCatalog.ScarTissueId && id != "bad_beat_jar") continue;
                    if (run.ShopOffers[i].Price > run.Comps) continue;
                    run.BuyRelic(i);
                    bought = true;
                    break;
                }
                if (bought) continue;
            }

            if (run.OwnedConsumables.Count < run.Config.ConsumableSlots)
            {
                for (int i = 0; i < run.ConsumableOffers.Count; i++)
                {
                    if (run.ConsumableOffers[i].Id != "free_bet") continue;
                    if (run.ConsumableOffers[i].Price > run.Comps) continue;
                    run.BuyConsumable(i);
                    bought = true;
                    break;
                }
            }
        }
    }
}

using System;
using System.Globalization;
using System.Threading;
using SBR.Engine;

namespace SBR.ConsoleGame;

/// <summary>
/// Thin console primitives: ConsoleColor writes that always restore the prior colour, money/odds
/// formatting, the win-prob bar, and the handful of input helpers. No raw ANSI (Windows-safe).
/// Every method that could throw on a redirected stream (Clear, sleeps) degrades quietly so the
/// --auto smoke harness and piped runs never blow up.
/// </summary>
internal static class Ui
{
    private static readonly CultureInfo Inv = CultureInfo.InvariantCulture;

    public static void Write(ConsoleColor c, string s)
    {
        ConsoleColor prev = Console.ForegroundColor;
        Console.ForegroundColor = c;
        Console.Write(s);
        Console.ForegroundColor = prev;
    }

    public static void WriteLine(ConsoleColor c, string s)
    {
        Write(c, s);
        Console.WriteLine();
    }

    public static void Line() => Console.WriteLine();

    public static void Rule() => WriteLine(ConsoleColor.DarkGray, new string('─', 62));

    /// <summary>Whole-dollar money, thousands-separated. Negatives render as "-$X".</summary>
    public static string Money(double v)
    {
        double r = Math.Round(v);
        string body = Math.Abs(r).ToString("#,##0", Inv);
        return (r < 0 ? "-$" : "$") + body;
    }

    /// <summary>Signed whole-dollar delta, e.g. "+$412" / "-$200".</summary>
    public static string Signed(double v)
    {
        double r = Math.Round(v);
        return (r < 0 ? "-$" : "+$") + Math.Abs(r).ToString("#,##0", Inv);
    }

    /// <summary>American odds string with an explicit leading sign (+150 / -145).</summary>
    public static string American(double decimalOdds)
    {
        int a = OddsMath.AmericanFromDecimal(decimalOdds);
        return a >= 0 ? "+" + a.ToString(Inv) : a.ToString(Inv);
    }

    public static int Pct(double p) => (int)Math.Round(p * 100.0);

    /// <summary>A [####----]-style win-prob bar of the given width.</summary>
    public static string Bar(double prob, int width)
    {
        int filled = (int)Math.Round(Math.Clamp(prob, 0.0, 1.0) * width);
        filled = Math.Clamp(filled, 0, width);
        return "[" + new string('#', filled) + new string('-', width - filled) + "]";
    }

    public static void Clear()
    {
        try { Console.Clear(); } catch { /* redirected stream: nothing to clear */ }
    }

    /// <summary>Sleep, unless input is redirected (piped/auto) — then return instantly so nothing blocks.</summary>
    public static void Beat(int ms)
    {
        if (Console.IsInputRedirected) return;
        Thread.Sleep(ms);
    }

    /// <summary>True once stdin hit end-of-file (a piped script ran out of lines). Callers treat it
    /// as "quit" — otherwise a premature-EOF piped session would spin on the command loop forever.</summary>
    public static bool Eof { get; private set; }

    public static string Prompt(string label)
    {
        Write(ConsoleColor.White, label);
        string? s = Console.ReadLine();
        if (s == null)
        {
            Eof = true;
            return "";
        }
        return s.Trim();
    }

    public static void Pause()
    {
        Write(ConsoleColor.DarkGray, "  (enter to continue) ");
        Console.ReadLine();
    }

    public static bool Confirm(string label)
    {
        string s = Prompt(label).ToUpperInvariant();
        return s.StartsWith("Y", StringComparison.Ordinal);
    }

    public static void Title()
    {
        Clear();
        WriteLine(ConsoleColor.Cyan, "╔══════════════════════════════════════════════════════════╗");
        WriteLine(ConsoleColor.Cyan, "║   S B R   —   build it · lock it · sweat it              ║");
        WriteLine(ConsoleColor.Cyan, "╚══════════════════════════════════════════════════════════╝");
        WriteLine(ConsoleColor.DarkGray, "  a sports-betting roguelite prototype · the text era");
        Line();
    }
}

using System;
using System.Collections.Generic;
using SBR.Engine;

namespace SBR.Sim;

/// <summary>
/// RANDOM — a noise floor between naive and skilled: legal but thoughtless play.
///
/// Policy:
///   • Betting: 1–3 tickets, each 1–4 legs on random distinct matchups and random sides, each staked a
///     random 10–50% of the (shrinking) bank, floored to whole dollars and never below MinStake.
///   • Sweat: steps the sessions and cashes out with 5% probability per event whenever an offer exists.
///   • Shop: half the time, buys one random affordable offer.
///
/// HONESTY: picks sides and matchups at random — it never consults probabilities at all, true or implied.
/// </summary>
public sealed class RandomStrategy : IStrategy
{
    public string Name => "random";
    public bool ControlsSweat => true;

    private const double CashOutChancePerEvent = 0.05;
    private const double ShopBuyChance = 0.5;

    public void Bet(Run run, BotState state, Pcg32 rng)
    {
        int slateCount = run.CurrentSlate.Matchups.Count;
        int tickets = rng.NextInt(1, Math.Min(run.Config.MaxTicketsPerRound, 3) + 1); // 1..3

        for (int t = 0; t < tickets; t++)
        {
            if (run.Bank < run.Config.MinStake) break;

            int maxLegs = Math.Min(4, Math.Min(run.Config.MaxLegs, slateCount));
            int legs = rng.NextInt(1, maxLegs + 1); // 1..4

            var picks = new List<Pick>(legs);
            foreach (int m in DistinctMatchups(rng, slateCount, legs))
                picks.Add(new Pick(m, rng.NextDouble() < 0.5 ? Side.Home : Side.Away));

            double frac = 0.1 + 0.4 * rng.NextDouble(); // 10..50%
            double stake = Math.Max(run.Config.MinStake, Math.Floor(frac * run.Bank));
            if (stake > run.Bank) break;

            run.PlaceTicket(picks, stake);
        }
    }

    public bool ShouldCashOut(Run run, Ticket ticket, SweatSession session, DramaEvent evt,
        double offer, double bankNow, double target, BotState state, Pcg32 rng)
        => rng.NextDouble() < CashOutChancePerEvent;

    public void Shop(Run run, BotState state, Pcg32 rng)
    {
        // Codex r2 #13 fix: affordability is COMPS (the shop currency), never cash — and the
        // random shopper picks legally across BOTH dealt rows within their separate slot limits.
        if (rng.NextDouble() >= ShopBuyChance) return;

        var passives = new List<int>();
        if (run.OwnedRelics.Count < run.Config.RelicSlots)
            for (int i = 0; i < run.ShopOffers.Count; i++)
                if (run.ShopOffers[i].Price <= run.Comps) passives.Add(i);

        var consumables = new List<int>();
        if (run.OwnedConsumables.Count < run.Config.ConsumableSlots)
            for (int i = 0; i < run.ConsumableOffers.Count; i++)
                if (run.ConsumableOffers[i].Price <= run.Comps) consumables.Add(i);

        int total = passives.Count + consumables.Count;
        if (total == 0) return;

        int pick = rng.NextInt(0, total);
        if (pick < passives.Count) run.BuyRelic(passives[pick]);
        else run.BuyConsumable(consumables[pick - passives.Count]);
    }

    // Partial Fisher-Yates: `count` distinct indices from [0, n).
    private static IEnumerable<int> DistinctMatchups(Pcg32 rng, int n, int count)
    {
        var pool = new int[n];
        for (int i = 0; i < n; i++) pool[i] = i;
        for (int i = 0; i < count; i++)
        {
            int j = rng.NextInt(i, n);
            (pool[i], pool[j]) = (pool[j], pool[i]);
            yield return pool[i];
        }
    }
}

using System.Collections.Generic;
using SBR.Engine;

namespace SBR.Sim;

/// <summary>
/// Per-run scratch for a bot. Strategy objects are stateless singletons shared across parallel runs,
/// so anything a bot must remember within one run lives here (created fresh per run by the harness).
/// </summary>
public sealed class BotState
{
    /// <summary>The bot's estimate of P(home wins) per matchup index for the current round. Populated by
    /// the bot at bet time from the info a player could have (de-vigged odds).</summary>
    public readonly Dictionary<int, double> HomeProbEst = new();

    public void NewRound() => HomeProbEst.Clear();
}

/// <summary>The pending-loss window verbs a bot can choose between (charm expansion, PLAN.md
/// rev 5 §13). RunPlayer validates legality (holdings, mulligan's ≥2-active-legs rule) and
/// falls back to Decline when the choice is illegal.</summary>
public enum PendingLossAction { Decline, Mulligan, Whistle }

/// <summary>
/// A pluggable strategy bot (PRD F9). Hooks: <see cref="Bet"/> (betting window), <see cref="ShouldCashOut"/>
/// (per sweat event, only when <see cref="ControlsSweat"/>), <see cref="ChoosePendingLossAction"/>
/// (the save window), and <see cref="Shop"/> (between rounds).
///
/// HONESTY RULE (enforced by convention across all bots): a bot may read only what a player could know —
/// odds, records, the bank/debt/requirement, and revealed drama events (evt.WinProbAfter). A bot must
/// NEVER read Matchup.TrueHomeProb, Leg.TrueProb, or Matchup.Result. Only the harness (Metrics) reads truth.
/// </summary>
public interface IStrategy
{
    string Name { get; }

    /// <summary>When false the harness fast-forwards the sweat (never cashing out) and never calls
    /// <see cref="ShouldCashOut"/>. Naive is the only bot that opts out.</summary>
    bool ControlsSweat { get; }

    /// <summary>Betting window: place 0..MaxTickets tickets via run.PlaceTicket.</summary>
    void Bet(Run run, BotState state, Pcg32 rng);

    /// <summary>
    /// Called once per sweat event on an open, cash-out-eligible ticket when an offer exists.
    /// Return true to take <paramref name="offer"/>. <paramref name="bankNow"/> is the live bank and
    /// <paramref name="target"/> the round's settle requirement (target + any bookie debt);
    /// <paramref name="evt"/>.WinProbAfter is the on-screen live win% of the current leg
    /// (legitimate player information).
    /// </summary>
    bool ShouldCashOut(Run run, Ticket ticket, SweatSession session, DramaEvent evt,
        double offer, double bankNow, double target, BotState state, Pcg32 rng);

    /// <summary>
    /// The pending-loss window (rev 5 §13). Default policy (the documented bot greed): a legal
    /// Mulligan is the certain save — take it; else a held Whistle fires when the captured
    /// pre-kill prob gives at least a coin-flip's worth of rescue; else decline.
    /// </summary>
    PendingLossAction ChoosePendingLossAction(Run run, Ticket ticket, SweatSession session,
        BotState state, Pcg32 rng)
    {
        if (run.OwnsConsumable("mulligan_slip") && session.CanMulliganPendingLoss)
            return PendingLossAction.Mulligan;
        if (run.OwnsConsumable("refs_whistle") && session.PendingLossProbBefore >= 0.35)
            return PendingLossAction.Whistle;
        return PendingLossAction.Decline;
    }

    /// <summary>Shop window: buy relics via run.BuyRelic.</summary>
    void Shop(Run run, BotState state, Pcg32 rng);
}

using System;
using System.Collections.Generic;
using System.Globalization;
using SBR.Engine;

namespace SBR.ConsoleGame;

internal enum BetAction { Locked, Quit }

/// <summary>
/// The Phase.Betting screen and its single-letter command loop. Renders the header (bank, target,
/// any bookie debt), relics, the slate, and tickets placed so far, then dispatches B / L / Q. Every
/// engine call is wrapped so a bad input prints the message and returns to the loop — the shell
/// never crashes.
/// </summary>
internal static class BettingScreen
{
    public static BetAction Run(Run run)
    {
        while (true)
        {
            Render(run);
            string cmd = Ui.Prompt(CommandBar()).ToUpperInvariant();
            if (Ui.Eof) return BetAction.Quit;
            switch (cmd)
            {
                case "B":
                    Build(run);
                    break;

                case "K":
                    try
                    {
                        run.PlayBookiesMarker();
                        Ui.WriteLine(ConsoleColor.Cyan,
                            $"MARKER PLAYED — this round's payment drops to {Ui.Money(run.CurrentPayment)}.");
                    }
                    catch (Exception ex) { Ui.WriteLine(ConsoleColor.Red, ex.Message); }
                    Ui.Pause();
                    break;

                case "L":
                    if (run.Tickets.Count == 0 && !Ui.Confirm("no bets this round? the payment still comes due — y/n: ")) break;
                    run.LockRound();
                    return BetAction.Locked;

                case "Q":
                    if (Ui.Confirm("quit the run? y/n: ")) return BetAction.Quit;
                    break;

                default:
                    Unknown();
                    break;
            }
        }
    }

    private static void Unknown()
    {
        Ui.WriteLine(ConsoleColor.Red, "Unknown command.");
        Ui.Pause();
    }

    private static string CommandBar()
        => "commands: [B]uild ticket  [K] marker  [L]ock round  [Q]uit  > ";

    // ---- rendering ----

    private static void Render(Run run)
    {
        Ui.Clear();
        Ui.WriteLine(ConsoleColor.Cyan,
            $"ROUND {run.Round}/{run.Config.Rounds}  ·  BANK {Ui.Money(run.Bank)}  ·  PAYMENT DUE {Ui.Money(run.CurrentPayment)}"
            + $"  ·  COMPS {run.Comps:0.#}  ·  SEED {run.Rng.RunSeed}");
        Ui.WriteLine(ConsoleColor.DarkGray,
            $"tickets {run.Tickets.Count}/{run.Config.MaxTicketsPerRound}  ·  relics {run.OwnedRelics.Count}/{run.Config.RelicSlots}"
            + $"  ·  consumables {run.OwnedConsumables.Count}/{run.Config.ConsumableSlots}"
            + $"  ·  staking earns comps ({run.Config.CompsPerDollarStaked:0.##}/$)");

        // The whole ledger is public information (design/10) — show what is coming.
        var schedule = new List<string>();
        for (int r = run.Round - 1; r < run.PaymentSchedule.Count; r++)
            schedule.Add(Ui.Money(run.PaymentSchedule[r]));
        Ui.WriteLine(ConsoleColor.DarkGray, "SCHEDULE: " + string.Join(" → ", schedule));

        if (run.ScarStacks > 0)
            Ui.WriteLine(ConsoleColor.Magenta,
                $"SCAR {run.ScarStacks:0.#}pp — your FIRST ticket this round carries it (burns on a hit)");
        GameLoop.WriteEffectStates(run); // chalk/iron/jar/system stacks (rev 5 §20)

        if (run.OwnedRelics.Count > 0)
        {
            var names = new List<string>();
            foreach (RelicDefinition r in run.OwnedRelics) names.Add(r.Name);
            Ui.WriteLine(ConsoleColor.Cyan, "RELICS: " + string.Join(", ", names));
        }

        if (run.OwnedConsumables.Count > 0)
        {
            var names = new List<string>();
            foreach (ConsumableDefinition c in run.OwnedConsumables) names.Add(c.Name);
            Ui.WriteLine(ConsoleColor.Cyan, "CONSUMABLES: " + string.Join(", ", names));
        }

        Ui.Rule();
        RenderSlate(run);

        if (run.Tickets.Count > 0)
        {
            Ui.Line();
            Ui.WriteLine(ConsoleColor.White, "TICKETS");
            for (int i = 0; i < run.Tickets.Count; i++)
                Ui.WriteLine(ConsoleColor.Gray, $" {i + 1}. {DescribeLegs(run.Tickets[i])}  |  {Ui.Money(run.Tickets[i].Stake)} → {Ui.Money(run.Tickets[i].PotentialPayout)}");
        }

        Ui.Line();
    }

    private static void RenderSlate(Run run)
    {
        Ui.WriteLine(ConsoleColor.White, "SLATE  (away @ home · moneyline)");

        foreach (Matchup m in run.CurrentSlate.Matchups)
        {
            string away = $"{m.Away.Name} ({m.Away.Record})";
            string home = $"{m.Home.Name} ({m.Home.Record})";
            string line = $" {m.Index + 1}. {away.PadRight(28)} {Ui.American(m.AwayOdds),5}   @   {home.PadRight(28)} {Ui.American(m.HomeOdds),5}";
            Ui.WriteLine(ConsoleColor.Gray, line);
        }
    }

    private static string DescribeLegs(Ticket t)
    {
        var parts = new List<string>();
        foreach (Leg leg in t.Legs)
        {
            string team = Short(leg.Side == Side.Home ? leg.Matchup.Home.Name : leg.Matchup.Away.Name);
            string mark = Math.Abs(leg.OfferedOdds - leg.BaseOdds) > 1e-9 ? " ^boosted" : "";
            parts.Add($"{team} {Ui.American(leg.OfferedOdds)}{mark}");
        }
        return string.Join(", ", parts);
    }

    // ---- B: build a ticket ----

    private static void Build(Run run)
    {
        string picksLine = Ui.Prompt("picks> (e.g. 1H 3A 5H)  ");
        List<Pick> picks;
        try
        {
            picks = ParsePicks(picksLine, run.CurrentSlate.Matchups.Count);
        }
        catch (Exception ex)
        {
            Ui.WriteLine(ConsoleColor.Red, ex.Message);
            Ui.Pause();
            return;
        }

        if (picks.Count == 0)
        {
            Ui.WriteLine(ConsoleColor.Red, "No picks entered.");
            Ui.Pause();
            return;
        }

        string stakeLine = Ui.Prompt("stake> ");
        if (!double.TryParse(stakeLine, NumberStyles.Any, CultureInfo.InvariantCulture, out double stake))
        {
            Ui.WriteLine(ConsoleColor.Red, "Stake must be a number.");
            Ui.Pause();
            return;
        }

        // A held Profit Boost is played at the betslip (design/10 D): pick the leg it lands on.
        int boostLeg = -1;
        if (run.OwnsConsumable("profit_boost") && picks.Count > 0)
        {
            string b = Ui.Prompt($"PROFIT BOOST held — boost which leg? (1-{picks.Count}, enter to skip) ");
            if (int.TryParse(b, NumberStyles.Integer, CultureInfo.InvariantCulture, out int bl)
                && bl >= 1 && bl <= picks.Count)
            {
                boostLeg = bl - 1;
            }
        }

        // Locked contract modifiers (one per ticket — the one-modifier law).
        TicketModifier modifier = TicketModifier.None;
        bool hasFree = run.OwnsConsumable("free_bet");
        bool hasDon = run.OwnsConsumable("double_or_nothing");
        if (hasFree || hasDon)
        {
            string opts = hasFree && hasDon ? "[F]ree bet / [D]ouble-or-nothing"
                : hasFree ? "[F]ree bet" : "[D]ouble-or-nothing";
            string m = Ui.Prompt($"modifier? {opts} (enter to skip) ").ToUpperInvariant();
            if (m == "F" && hasFree) modifier = TicketModifier.FreeBet;
            else if (m == "D" && hasDon) modifier = TicketModifier.DoubleOrNothing;
        }

        try
        {
            Ticket t = run.PlaceTicket(picks, stake, boostLeg, modifier);
            string tag = t.Modifier == TicketModifier.FreeBet ? "  [FREE BET]"
                : t.Modifier == TicketModifier.DoubleOrNothing ? "  [DOUBLE OR NOTHING — no cash-out]" : "";
            Ui.WriteLine(ConsoleColor.Green,
                $"TICKET PLACED: {DescribeLegs(t)}  |  {Ui.Money(t.Stake)} → {Ui.Money(t.PotentialPayout)}{tag}");
        }
        catch (Exception ex)
        {
            Ui.WriteLine(ConsoleColor.Red, ex.Message); // engine validation, verbatim
        }

        Ui.Pause();
    }

    // ---- parsing ----

    private static List<Pick> ParsePicks(string line, int matchupCount)
    {
        var picks = new List<Pick>();
        foreach (string tok in line.Split(new[] { ' ', ',' }, StringSplitOptions.RemoveEmptyEntries))
        {
            (int idx, Side side) = ParseOne(tok, matchupCount);
            picks.Add(new Pick(idx, side));
        }
        return picks;
    }

    private static (int idx, Side side) ParseOne(string token, int matchupCount)
    {
        token = token.Trim();
        if (token.Length < 2)
            throw new ArgumentException($"Bad pick '{token}' — use a number then H or A, e.g. 1H.");

        char sc = char.ToUpperInvariant(token[token.Length - 1]);
        Side side = sc == 'H' ? Side.Home
                  : sc == 'A' ? Side.Away
                  : throw new ArgumentException($"Bad side in '{token}' — end with H (home) or A (away).");

        string num = token.Substring(0, token.Length - 1);
        if (!int.TryParse(num, NumberStyles.Integer, CultureInfo.InvariantCulture, out int n))
            throw new ArgumentException($"Bad matchup number in '{token}'.");

        int idx = n - 1;
        if (idx < 0 || idx >= matchupCount)
            throw new ArgumentException($"Matchup {n} is off the slate (pick 1–{matchupCount}).");

        return (idx, side);
    }

    // ---- helpers ----

    private static string Short(string teamName)
    {
        int i = teamName.LastIndexOf(' ');
        return i >= 0 ? teamName.Substring(i + 1) : teamName;
    }
}

using SBR.Engine;

namespace SBR.Engine.Tests;

public class RunTests
{
    private static Run NewRun(string seed = "RUN-TEST", RunConfig? cfg = null) => new(seed, cfg);

    [Fact]
    public void New_run_starts_in_betting_with_rework_defaults()
    {
        // Campaign-chosen defaults (sim-report-2.md 2026-07-13): bank 350 (comps era - betting is mandatory), convex payments from 60.
        var run = NewRun();
        Assert.Equal(Phase.Betting, run.Phase);
        Assert.Equal(1, run.Round);
        Assert.Equal(350, run.Bank);
        Assert.Equal(60, run.CurrentPayment);
        Assert.Null(run.LastSettlement);
        Assert.Equal(0.0, run.ScarStacks);
        Assert.Empty(run.OwnedConsumables);
        Assert.Equal(6, run.CurrentSlate.Matchups.Count);
    }

    [Fact]
    public void Placing_a_ticket_deducts_stake_and_locks_offered_odds()
    {
        var run = NewRun();
        Matchup m = run.CurrentSlate.Matchups[0];
        Ticket t = run.PlaceTicket(new[] { new Pick(0, Side.Home) }, 100);

        Assert.Equal(250, run.Bank);
        Assert.Equal(TicketState.Open, t.State);
        Assert.Equal(m.HomeOdds, t.Legs[0].OfferedOdds, 12);
        Assert.Equal(100 * m.HomeOdds, t.PotentialPayout, 10);
    }

    [Fact]
    public void Ticket_vig_matches_the_design02_formula()
    {
        var run = NewRun();
        Matchup m = run.CurrentSlate.Matchups[0];
        Ticket t = run.PlaceTicket(new[] { new Pick(0, Side.Home) }, 100);

        double expected = OddsMath.VigPaid(100, m.HomeOdds, m.FairOdds(Side.Home));
        Assert.Equal(expected, t.VigPaid, 10);
        Assert.True(t.VigPaid > 0);
    }

    [Fact]
    public void Ticket_validation_rejects_bad_input()
    {
        var run = NewRun();
        Assert.Throws<ArgumentException>(() => run.PlaceTicket(new[] { new Pick(0, Side.Home) }, 5));
        Assert.Throws<ArgumentException>(() => run.PlaceTicket(new[] { new Pick(0, Side.Home) }, 351));
        Assert.Throws<ArgumentException>(() => run.PlaceTicket(Array.Empty<Pick>(), 100));
        Assert.Throws<ArgumentException>(
            () => run.PlaceTicket(new[] { new Pick(0, Side.Home), new Pick(0, Side.Away) }, 100));
        Assert.Throws<ArgumentException>(
            () => run.PlaceTicket(new[] { new Pick(1, Side.Home), new Pick(2, Side.Away), new Pick(1, Side.Away) }, 100));
    }

    [Fact]
    public void Fourth_ticket_is_rejected()
    {
        var run = NewRun();
        for (int i = 0; i < 3; i++)
            run.PlaceTicket(new[] { new Pick(i, Side.Home) }, 10);
        Assert.Throws<InvalidOperationException>(() => run.PlaceTicket(new[] { new Pick(3, Side.Home) }, 10));
    }

    [Fact]
    public void Seven_leg_parlay_is_rejected_by_config()
    {
        var cfg = new RunConfig { MatchupsPerSlate = 8 };
        var run = NewRun(cfg: cfg);
        var picks = Enumerable.Range(0, 7).Select(i => new Pick(i, Side.Home)).ToArray();
        Assert.Throws<ArgumentException>(() => run.PlaceTicket(picks, 100));
    }

    [Fact]
    public void Locking_resolves_every_matchup_and_settles_tickets()
    {
        var run = NewRun();
        run.PlaceTicket(new[] { new Pick(0, Side.Home), new Pick(1, Side.Away) }, 50);
        run.LockRound();
        run.FastForwardRound();

        Assert.Equal(Phase.Settlement, run.Phase);
        Assert.All(run.CurrentSlate.Matchups, m => Assert.NotNull(m.Result));
        Assert.All(run.Tickets, t => Assert.NotEqual(TicketState.Open, t.State));
    }

    [Fact]
    public void Bank_accounting_is_consistent_with_ticket_results()
    {
        var run = NewRun("ACCOUNTING");
        run.PlaceTicket(new[] { new Pick(0, Side.Home) }, 100);
        run.PlaceTicket(new[] { new Pick(1, Side.Away), new Pick(2, Side.Home) }, 50);
        double bankBeforeLock = run.Bank;

        run.LockRound();
        run.FastForwardRound();

        double expectedWinnings = run.Tickets
            .Where(t => t.State == TicketState.Won)
            .Sum(t => t.PotentialPayout);
        Assert.Equal(bankBeforeLock + expectedWinnings, run.Bank, 8);
    }

    [Fact]
    public void Tickets_sharing_a_matchup_share_its_outcome()
    {
        var run = NewRun("SHARED-OUTCOME");
        Ticket a = run.PlaceTicket(new[] { new Pick(0, Side.Home) }, 10);
        Ticket b = run.PlaceTicket(new[] { new Pick(0, Side.Home) }, 10);
        run.LockRound();
        run.FastForwardRound();

        Assert.Equal(a.State, b.State);
        Assert.Equal(a.Legs[0].State, b.Legs[0].State);
    }

    [Fact]
    public void Outcomes_for_a_seed_do_not_depend_on_what_was_bet()
    {
        var bettor = NewRun("FIXED-UNIVERSE");
        bettor.PlaceTicket(new[] { new Pick(3, Side.Away) }, 250);
        bettor.LockRound();

        var abstainer = NewRun("FIXED-UNIVERSE");
        abstainer.LockRound();

        for (int i = 0; i < 6; i++)
            Assert.Equal(abstainer.CurrentSlate.Matchups[i].Result, bettor.CurrentSlate.Matchups[i].Result);
    }

    [Fact]
    public void Missing_a_payment_without_the_totem_loses_the_run()
    {
        // Payment model (design/10): the settle DEDUCTS; a shortfall with no Totem is death.
        var cfg = new RunConfig { StartingBank = 500, Payments = new double[] { 800, 1200 } };
        var run = NewRun(cfg: cfg);
        run.LockRound();
        run.FastForwardRound();
        run.Settle();

        Assert.Equal(Phase.RunLost, run.Phase);
        Assert.True(run.LastSettlement.HasValue);
        Assert.Equal(300, run.LastSettlement!.Value.Shortfall, 10);
        Assert.False(run.LastSettlement!.Value.TotemFired);
    }

    [Fact]
    public void Meeting_a_payment_deducts_it_and_advances_through_the_shop()
    {
        var cfg = new RunConfig { Payments = new double[] { 100, 100 } };
        var run = NewRun(cfg: cfg);
        run.LockRound();
        run.FastForwardRound();
        run.Settle();
        Assert.Equal(Phase.Shop, run.Phase);
        Assert.Equal(250, run.Bank, 10); // 350 − the 100 payment: the settle takes its cut
        Assert.True(run.LastSettlement!.Value.Paid);

        run.ExitShop();
        Assert.Equal(2, run.Round);
        Assert.Equal(Phase.Betting, run.Phase);
        Assert.Empty(run.Tickets);
        Assert.Equal(100, run.CurrentPayment);
    }

    [Fact]
    public void Clearing_the_final_payment_wins_the_run()
    {
        var cfg = new RunConfig { Payments = new double[] { 100, 100 } };
        var run = NewRun(cfg: cfg);

        run.LockRound();
        run.FastForwardRound();
        run.Settle();
        run.ExitShop();
        run.LockRound();
        run.FastForwardRound();
        run.Settle();

        Assert.Equal(Phase.RunWon, run.Phase);
        Assert.Equal(150, run.Bank, 10); // both payments taken from the untouched 350
    }

    [Fact]
    public void Fresh_slate_each_round_differs()
    {
        var cfg = new RunConfig { Payments = new double[] { 100, 100 } };
        var run = NewRun(cfg: cfg);
        double round1Prob = run.CurrentSlate.Matchups[0].TrueHomeProb;

        run.LockRound();
        run.FastForwardRound();
        run.Settle();
        run.ExitShop();

        Assert.Equal(2, run.CurrentSlate.Round);
        Assert.NotEqual(round1Prob, run.CurrentSlate.Matchups[0].TrueHomeProb);
    }

    [Fact]
    public void Phase_guards_reject_out_of_order_calls()
    {
        var run = NewRun();
        Assert.Throws<InvalidOperationException>(() => run.Settle());
        Assert.Throws<InvalidOperationException>(() => run.ExitShop());

        run.LockRound();
        Assert.Throws<InvalidOperationException>(() => run.LockRound());
        Assert.Throws<InvalidOperationException>(() => run.PlaceTicket(new[] { new Pick(0, Side.Home) }, 100));
    }

    [Fact]
    public void Entire_run_is_reproducible_from_its_seed()
    {
        static (Phase, double) PlayScriptedRun(string seed)
        {
            var run = new Run(seed);
            run.PlaceTicket(new[] { new Pick(0, Side.Home), new Pick(2, Side.Away) }, 120);
            run.PlaceTicket(new[] { new Pick(4, Side.Home) }, 60);
            run.LockRound();
            run.FastForwardRound();
            run.Settle();
            return (run.Phase, run.Bank);
        }

        (Phase phaseA, double bankA) = PlayScriptedRun("GOLDEN-1");
        (Phase phaseB, double bankB) = PlayScriptedRun("GOLDEN-1");
        Assert.Equal(phaseA, phaseB);
        Assert.Equal(bankA, bankB, 12);
    }
}

using System.Collections.Generic;
using NUnit.Framework;
using SBR.Engine;
using SBR.Probe;

namespace SBR.Tests.EditMode
{
    /// <summary>
    /// M1, Phase 2 — proves SBR.Engine.dll reproduces the Week 2 determinism pins inside Unity's
    /// (Mono) editor runtime. Ported from engine.tests/GoldenSeedTests.cs (the golden event stream,
    /// first-ten win probabilities, and settled bank) plus one engine.tests/DebtTests.cs case so the
    /// newest engine surface (debt-as-HP) is exercised through the DLL in Unity too. The pin data lives
    /// once in <see cref="GoldenReplay"/>; these tests assert the DLL's actual values against it.
    /// </summary>
    public class DeterminismEditModeTests
    {
        [Test]
        public void Golden_seed_event_stream_is_pinned()
        {
            Run run = GoldenReplay.ScriptedRound();
            List<DramaEvent> events = GoldenReplay.DrainAll(run);

            Assert.AreEqual(18, events.Count, "expected exactly 18 events (re-pinned F_0.2.0 M-T1)");
            Assert.AreEqual(GoldenReplay.ExpectedEvents.Length, events.Count);

            for (int i = 0; i < events.Count; i++)
            {
                DramaEvent e = events[i];
                var x = GoldenReplay.ExpectedEvents[i];
                Assert.AreEqual(x.leg, e.LegIndex, $"LegIndex @ event {i}");
                Assert.AreEqual(x.step, e.Step, $"Step @ event {i}");
                Assert.AreEqual(x.type, e.Type, $"Type @ event {i}");
                Assert.AreEqual(x.tag, e.Tag, $"Tag @ event {i}");
            }

            // 6 dp, matching engine.tests' Assert.Equal(expected, actual, 6).
            for (int i = 0; i < GoldenReplay.ExpectedFirstTenWinProb.Length; i++)
                Assert.AreEqual(GoldenReplay.ExpectedFirstTenWinProb[i], events[i].WinProbAfter, 1e-6,
                    $"WinProbAfter @ event {i}");
        }

        [Test]
        public void Golden_seed_settles_to_pinned_bank_and_phase()
        {
            Run run = GoldenReplay.ScriptedRound();
            GoldenReplay.DrainAll(run);
            run.FinishSweat();

            Assert.AreEqual(Phase.Settlement, run.Phase);
            Assert.AreEqual(TicketState.Lost, run.Tickets[0].State); // parlay died on its final leg
            Assert.AreEqual(TicketState.Won, run.Tickets[1].State);  // single hit
            Assert.AreEqual(GoldenReplay.ExpectedBank, run.Bank, 1e-5); // 5 dp
        }

        [Test]
        public void Golden_seed_replays_identically()
        {
            List<DramaEvent> a = GoldenReplay.DrainAll(GoldenReplay.ScriptedRound());
            List<DramaEvent> b = GoldenReplay.DrainAll(GoldenReplay.ScriptedRound());

            Assert.AreEqual(a.Count, b.Count);
            for (int i = 0; i < a.Count; i++)
            {
                Assert.AreEqual(a[i].LegIndex, b[i].LegIndex);
                Assert.AreEqual(a[i].Step, b[i].Step);
                Assert.AreEqual(a[i].Type, b[i].Type);
                Assert.AreEqual(a[i].Tag, b[i].Tag);
                Assert.AreEqual(a[i].WinProbAfter, b[i].WinProbAfter, 1e-15);
            }
        }

        [Test]
        public void Probe_verify_passes_and_reports_event_stream_hash()
        {
            GoldenReplay.Result r = GoldenReplay.Verify();
            Assert.IsTrue(r.Pass, r.Detail);
            Assert.IsNotNull(r.Hash);
            // Surfaces the golden fingerprint in the test log for cross-platform comparison.
            TestContext.WriteLine($"[EditMode/Mono] event-stream FNV-1a hash = {r.Hash}");
        }

        [Test]
        public void Payment_shortfall_with_the_totem_defers_and_surcharges_the_next_payment()
        {
            // The economy rework's mercy path (design/10, playtest #8): the Totem DEFERS a
            // non-final payment — the bank is untouched (working capital survives) and the
            // NEXT payment grows by payment × (1 + juice).
            var run = new Run("PAY-TOTEM", new RunConfig
            {
                StartingBank = 500,
                Payments = new double[] { 800, 400 },
                TotemJuiceRate = 0.5,
            });
            foreach (RelicDefinition def in RelicCatalog.All)
                if (def.Id == RelicCatalog.TotemId) run.GrantRelic(def);
            run.LockRound();
            run.FastForwardRound();
            run.Settle();

            Assert.AreEqual(Phase.Shop, run.Phase);                       // the run continues
            Assert.AreEqual(500.0, run.Bank, 1e-9);                       // the bank stands
            Assert.IsTrue(run.LastSettlement!.Value.TotemFired);
            run.ExitShop();
            Assert.AreEqual(400.0 + 800.0 * 1.5, run.CurrentPayment, 1e-9); // payment × 1.5 lands on P2
        }
    }
