namespace SBR.Engine.Tests;

/// <summary>
/// The Week 2 determinism pin. Seed GOLDEN-W2, a scripted 2-ticket round (a 3-leg parlay that
/// wins two legs then loses on its decisive final leg, plus a winning single). The full event
/// stream, the total count, and settlement are hard-coded below. An UNINTENTIONAL change here is
/// a determinism regression — investigate before re-pinning.
/// </summary>
public class GoldenSeedTests
{
    private const string Seed = "GOLDEN-W2";

    private static Run ScriptedRound()
    {
        // The Week-2 pin was taken at bank 500; the pin stays valid by pinning the config too
        // (outcomes/drama are bank-independent, but the settled-bank assertion is not).
        var run = new Run(Seed, new RunConfig { StartingBank = 500 });
        // Parlay: (0,Away) win, (2,Away) win, (3,Home) lose-on-final.  Single: (1,Home) win.
        run.PlaceTicket(new[] { new Pick(0, Side.Away), new Pick(2, Side.Away), new Pick(3, Side.Home) }, 100);
        run.PlaceTicket(new[] { new Pick(1, Side.Home) }, 50);
        run.LockRound();
        return run;
    }

    private static List<DramaEvent> DrainAll(Run run)
    {
        var all = new List<DramaEvent>();
        foreach (SweatSession s in run.Sweats)
            while (s.MoveNext(out var e))
                all.Add(e);
        return all;
    }

    // (LegIndex, Step, Type, Tag) for every one of the 18 events, in fast-forward order.
    // Re-pinned 2026-07-18 (F_0.2.0 M-T1): drama budgets cut to 3–5/leg with the round-1
    // progressive-density ramp at 2–4 — an INTENDED drama-stream re-pin. The settlement pin
    // below was deliberately NOT touched: outcomes ride the Outcomes stream and must not move.
    private static readonly (int leg, int step, DramaEventType type, TensionTag tag)[] Expected =
    {
        (0, 1, DramaEventType.BigPlay,  TensionTag.Swing),
        (0, 2, DramaEventType.LegFinal, TensionTag.Decisive),
        (1, 1, DramaEventType.Momentum, TensionTag.Calm),
        (1, 2, DramaEventType.Momentum, TensionTag.Calm),
        (1, 3, DramaEventType.Momentum, TensionTag.Calm),
        (1, 4, DramaEventType.LegFinal, TensionTag.Decisive),
        (2, 1, DramaEventType.Momentum, TensionTag.Calm),
        (2, 2, DramaEventType.Momentum, TensionTag.Calm),
        (2, 3, DramaEventType.BigPlay,  TensionTag.NearMiss),
        (2, 4, DramaEventType.LegFinal, TensionTag.Decisive),
        (0, 1, DramaEventType.Momentum, TensionTag.Calm),
        (0, 2, DramaEventType.Momentum, TensionTag.Calm),
        (0, 3, DramaEventType.Momentum, TensionTag.Calm),
        (0, 4, DramaEventType.Score,    TensionTag.Swing),
        (0, 5, DramaEventType.Momentum, TensionTag.Calm),
        (0, 6, DramaEventType.Score,    TensionTag.Swing),
        (0, 7, DramaEventType.Score,    TensionTag.Swing),
        (0, 8, DramaEventType.LegFinal, TensionTag.Decisive),
    };

    // WinProbAfter (6 dp) for the first ten events.
    private static readonly double[] ExpectedFirstTenWinProb =
    {
        0.803542, 1.000000, 0.774708, 0.751859, 0.767951,
        1.000000, 0.432400, 0.404952, 0.750000, 0.000000,
    };

    [Fact]
    public void Golden_seed_event_stream_is_pinned()
    {
        Run run = ScriptedRound();
        List<DramaEvent> events = DrainAll(run);

        Assert.Equal(18, events.Count);
        Assert.Equal(Expected.Length, events.Count);

        for (int i = 0; i < events.Count; i++)
        {
            DramaEvent e = events[i];
            Assert.Equal(Expected[i].leg, e.LegIndex);
            Assert.Equal(Expected[i].step, e.Step);
            Assert.Equal(Expected[i].type, e.Type);
            Assert.Equal(Expected[i].tag, e.Tag);
        }

        for (int i = 0; i < ExpectedFirstTenWinProb.Length; i++)
            Assert.Equal(ExpectedFirstTenWinProb[i], events[i].WinProbAfter, 6);
    }

    [Fact]
    public void Golden_seed_settles_to_pinned_bank_and_phase()
    {
        Run run = ScriptedRound();
        DrainAll(run);
        run.FinishSweat();

        Assert.Equal(Phase.Settlement, run.Phase);
        Assert.Equal(TicketState.Lost, run.Tickets[0].State); // parlay died on its final leg
        Assert.Equal(TicketState.Won, run.Tickets[1].State);  // single hit
        Assert.Equal(428.631019, run.Bank, 5);
    }

    [Fact]
    public void Golden_seed_replays_identically()
    {
        List<DramaEvent> a = DrainAll(ScriptedRound());
        List<DramaEvent> b = DrainAll(ScriptedRound());

        Assert.Equal(a.Count, b.Count);
        for (int i = 0; i < a.Count; i++)
        {
            Assert.Equal(a[i].LegIndex, b[i].LegIndex);
            Assert.Equal(a[i].Step, b[i].Step);
            Assert.Equal(a[i].Type, b[i].Type);
            Assert.Equal(a[i].Tag, b[i].Tag);
            Assert.Equal(a[i].WinProbAfter, b[i].WinProbAfter, 15);
        }
    }
}

namespace SBR.Engine;

/// <summary>
/// Named RNG streams per design/05: outcomes, drama, slate, and shop draw from
/// independent generators so that, e.g., which relics the shop offers can never
/// perturb match results for the same run seed.
/// </summary>
public sealed class RngHub
{
    public string RunSeed { get; }

    /// <summary>Match results.</summary>
    public Pcg32 Outcomes { get; }

    /// <summary>Drama-generator event sequences (Week 2).</summary>
    public Pcg32 Drama { get; }

    /// <summary>Slate, team, and odds generation.</summary>
    public Pcg32 Slate { get; }

    /// <summary>Shop offers (Week 3).</summary>
    public Pcg32 Shop { get; }

    /// <summary>Relic effects: tout-sheet intel and lucky-charm second-chance rolls (Week 3).</summary>
    public Pcg32 Relics { get; }

    public RngHub(string runSeed)
    {
        RunSeed = runSeed;
        ulong seed = Fnv1a64(runSeed);
        Outcomes = new Pcg32(seed, Fnv1a64("outcomes"));
        Drama = new Pcg32(seed, Fnv1a64("drama"));
        Slate = new Pcg32(seed, Fnv1a64("slate"));
        Shop = new Pcg32(seed, Fnv1a64("shop"));
        Relics = new Pcg32(seed, Fnv1a64("relics"));
    }

    public static ulong Fnv1a64(string s)
    {
        ulong hash = 14695981039346656037UL;
        foreach (char c in s)
        {
            hash ^= c;
            hash *= 1099511628211UL;
        }
        return hash;
    }

    /// <summary>
    /// Derived one-shot stream (charm expansion, PLAN.md rev 5 §6): fully keyed by run seed,
    /// round, ticket, leg, action, and use ordinal, so no two derivations collide and NONE of
    /// the named streams above is ever consumed — consumable timing can never perturb the run.
    /// Whistle rolls key (round, ticketId, legIndex, "whistle", 0); Manager redeals key
    /// (round, "", -1, "redeal", useOrdinal).
    /// </summary>
    public Pcg32 Derive(int round, string ticketId, int legIndex, string action, int ordinal)
        => new Pcg32(Fnv1a64(RunSeed), Fnv1a64($"{round}#{ticketId}#{legIndex}#{action}#{ordinal}"));
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace SBR.Engine;

public enum Side { Home, Away }

public enum LegState { Pending, Won, Lost }

public enum TicketState { Open, Won, Lost, CashedOut }

/// <summary>A ticket's final, ticket-local grading of one leg — what OnLegResolved carries
/// after any pending-loss window has closed (charm expansion, PLAN.md rev 5).</summary>
public enum LegGrade { Won, Lost, Voided }

/// <summary>Locked contract modifiers (charm expansion): at most ONE per ticket — the
/// one-modifier law, mirror of the one-product-slot law. Locked at placement, part of the
/// ticket's outcome→cash-flow contract (they price into cash-outs and G4).</summary>
public enum TicketModifier { None, FreeBet, DoubleOrNothing }

public sealed class Team
{
    public string Name { get; }
    public int Wins { get; }
    public int Losses { get; }
    public string Record => $"{Wins}-{Losses}";

    public Team(string name, int wins, int losses)
    {
        Name = name;
        Wins = wins;
        Losses = losses;
    }
}

public sealed class Matchup
{
    public int Index { get; }
    public Team Home { get; }
    public Team Away { get; }
    public double TrueHomeProb { get; }
    public double HomeOdds { get; }
    public double AwayOdds { get; }

    /// <summary>Set once at round lock, shared by every leg referencing this matchup.</summary>
    public Side? Result { get; internal set; }

    public Matchup(int index, Team home, Team away, double trueHomeProb, double homeOdds, double awayOdds)
    {
        Index = index;
        Home = home;
        Away = away;
        TrueHomeProb = trueHomeProb;
        HomeOdds = homeOdds;
        AwayOdds = awayOdds;
    }

    public double TrueProb(Side side) => side == Side.Home ? TrueHomeProb : 1.0 - TrueHomeProb;
    public double Odds(Side side) => side == Side.Home ? HomeOdds : AwayOdds;
    public double FairOdds(Side side) => 1.0 / TrueProb(side);
}

public sealed class Slate
{
    public int Round { get; }
    public IReadOnlyList<Matchup> Matchups { get; }

    public Slate(int round, IReadOnlyList<Matchup> matchups)
    {
        Round = round;
        Matchups = matchups;
    }
}

public readonly struct Pick
{
    public int MatchupIndex { get; }
    public Side Side { get; }

    public Pick(int matchupIndex, Side side)
    {
        MatchupIndex = matchupIndex;
        Side = side;
    }
}

public sealed class Leg
{
    public Matchup Matchup { get; }
    public Side Side { get; }

    /// <summary>The matchup's own price for the picked side — the odds before any relic touched them.</summary>
    public double BaseOdds { get; }

    /// <summary>The locked contract odds. Equals <see cref="BaseOdds"/> unless a compose-time relic
    /// (boosted_odds, promo_code) rewrote it before the ticket locked.</summary>
    public double OfferedOdds { get; internal set; }

    /// <summary>Set when a Mulligan Slip voids this leg after it reveals Lost: the leg is struck from
    /// the ticket (excluded from payout, win condition, and cash-out products).</summary>
    public bool IsVoided { get; internal set; }

    /// <summary>Ref's Whistle rescue (charm expansion): a successful grading re-roll marks THIS
    /// ticket's copy of the leg Won. Ticket-local by construction — Legs belong to one ticket;
    /// the shared <see cref="Matchup.Result"/> never bends (Lucky Charm precedent).</summary>
    public bool RescuedWon { get; internal set; }

    public Leg(Matchup matchup, Side side, double offeredOdds)
    {
        Matchup = matchup;
        Side = side;
        OfferedOdds = offeredOdds;
        BaseOdds = offeredOdds;
    }

    public double TrueProb => Matchup.TrueProb(Side);

    public LegState State =>
        Matchup.Result == null ? LegState.Pending
        : Matchup.Result == Side ? LegState.Won
        : LegState.Lost;

    /// <summary>This ticket's grading of the leg. Voided legs never count as won; a whistle-rescued
    /// leg counts as won for this ticket only.</summary>
    public bool GradesWon => !IsVoided && (RescuedWon || State == LegState.Won);
}

public sealed class Ticket
{
    public IReadOnlyList<Leg> Legs { get; }
    public double Stake { get; }
    public double VigPaid { get; }
    public TicketState State { get; internal set; } = TicketState.Open;

    /// <summary>Stable per-run identity: "round.placementIndex" — the DeriveRng key component
    /// (charm expansion, PLAN.md rev 5).</summary>
    public string Id { get; internal set; } = "";

    /// <summary>The named factor map behind <see cref="PayoutMultiplier"/> (charm expansion):
    /// each payout effect owns one named ×(1+x) factor ("multiplier", "scar", "photo", "whale",
    /// "collection", "chalk", "iron", "jar", "system", "housekey", "don"). Immutable after lock
    /// EXCEPT the designed toggles (photo drops when its last qualifying leg is voided).</summary>
    private readonly Dictionary<string, double> _factors = new Dictionary<string, double>();

    internal void SetFactor(string name, double value) => _factors[name] = value;
    internal void RemoveFactor(string name) => _factors.Remove(name);
    internal bool HasFactor(string name) => _factors.ContainsKey(name);

    /// <summary>Payout scale from relic effects — THE product slot (design/10 B2): the product
    /// of every named factor, so items stack multiplicatively. Scales the win payout and the
    /// cash-out fair value.</summary>
    public double PayoutMultiplier
    {
        get
        {
            double p = 1.0;
            foreach (double f in _factors.Values) p *= f;
            return p;
        }
    }

    /// <summary>The locked contract modifier (one per ticket — the one-modifier law): Free Bet
    /// refunds the stake on a loss; Double or Nothing doubles the product and suppresses
    /// cash-out offers.</summary>
    public TicketModifier Modifier { get; internal set; } = TicketModifier.None;

    /// <summary>Free Bet's exactly-once latch, set by the terminal-realization ledger.</summary>
    public bool Refunded { get; internal set; }

    /// <summary>Scar Tissue bookkeeping (design/10 B): the stacks this ticket's bust would add,
    /// baked at placement from its stake fraction; and whether this ticket carries (and on a win
    /// or cash-out, burns) the current stacks — the round's FIRST-placed ticket carries.</summary>
    internal double ScarStacksIfBust { get; set; }
    internal bool ScarCarrier { get; set; }

    public Ticket(IReadOnlyList<Leg> legs, double stake, double vigPaid)
    {
        Legs = legs;
        Stake = stake;
        VigPaid = vigPaid;
    }

    /// <summary>Legs that still count toward the ticket: voided (mulligan'd) legs are excluded.</summary>
    public IEnumerable<Leg> ActiveLegs => Legs.Where(l => !l.IsVoided);

    /// <summary>A ticket wins when it has at least one active leg and every active leg grades Won.</summary>
    public bool GradesWon
    {
        get
        {
            bool any = false;
            foreach (Leg l in Legs)
            {
                if (l.IsVoided) continue;
                any = true;
                if (!l.GradesWon) return false;
            }
            return any;
        }
    }

    /// <summary>Payout on a win: stake × product of the active legs' offered odds (voided legs drop out),
    /// scaled by any relic payout multiplier.</summary>
    public double PotentialPayout => Stake * OddsMath.ParlayDecimal(ActiveLegs.Select(l => l.OfferedOdds).ToList()) * PayoutMultiplier;
}

using SBR.Engine;

namespace SBR.Engine.Tests;

public class SlateGeneratorTests
{
    private static Slate NewSlate(string seed = "SLATE-TEST", RunConfig? cfg = null)
        => SlateGenerator.Generate(1, new RngHub(seed).Slate, cfg ?? new RunConfig());

    [Fact]
    public void Slate_has_configured_matchup_count()
        => Assert.Equal(6, NewSlate().Matchups.Count);

    [Fact]
    public void True_probabilities_stay_in_configured_band()
    {
        for (int i = 0; i < 50; i++)
        {
            foreach (Matchup m in NewSlate($"SEED-{i}").Matchups)
                Assert.InRange(m.TrueHomeProb, 0.25, 0.75);
        }
    }

    [Fact]
    public void Offered_odds_carry_exactly_the_configured_overround()
    {
        foreach (Matchup m in NewSlate().Matchups)
        {
            double impliedSum = OddsMath.ImpliedProb(m.HomeOdds) + OddsMath.ImpliedProb(m.AwayOdds);
            Assert.Equal(1.05, impliedSum, 10);
        }
    }

    [Fact]
    public void Team_names_are_distinct_within_a_slate()
    {
        var names = NewSlate().Matchups
            .SelectMany(m => new[] { m.Home.Name, m.Away.Name })
            .ToList();
        Assert.Equal(names.Count, names.Distinct().Count());
    }

    [Fact]
    public void Records_reflect_the_configured_prior_games()
    {
        foreach (Matchup m in NewSlate().Matchups)
        {
            Assert.Equal(9, m.Home.Wins + m.Home.Losses);
            Assert.Equal(9, m.Away.Wins + m.Away.Losses);
        }
    }

    [Fact]
    public void Same_seed_regenerates_the_identical_slate()
    {
        Slate a = NewSlate("DETERMINISM");
        Slate b = NewSlate("DETERMINISM");
        for (int i = 0; i < a.Matchups.Count; i++)
        {
            Assert.Equal(a.Matchups[i].Home.Name, b.Matchups[i].Home.Name);
            Assert.Equal(a.Matchups[i].Away.Name, b.Matchups[i].Away.Name);
            Assert.Equal(a.Matchups[i].TrueHomeProb, b.Matchups[i].TrueHomeProb, 12);
            Assert.Equal(a.Matchups[i].HomeOdds, b.Matchups[i].HomeOdds, 12);
        }
    }

    [Fact]
    public void Different_seeds_differ()
    {
        Slate a = NewSlate("SEED-A");
        Slate b = NewSlate("SEED-B");
        bool anyDifferent = false;
        for (int i = 0; i < a.Matchups.Count; i++)
            anyDifferent |= a.Matchups[i].TrueHomeProb != b.Matchups[i].TrueHomeProb;
        Assert.True(anyDifferent);
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace SBR.Engine;

public enum Phase { Betting, Sweat, Settlement, Shop, RunWon, RunLost }

/// <summary>One settle's telemetry (the economy rework's payment model): what was due, what
/// happened, whether the Totem fired. Presentation renders it; the sim audits it.</summary>
public readonly struct SettlementReport
{
    public readonly int Round;
    public readonly double Payment;
    public readonly double BankBefore;
    public readonly double BankAfter;
    public readonly double Shortfall;   // 0 when the payment was met
    public readonly bool TotemFired;
    public readonly Phase Outcome;

    public SettlementReport(int round, double payment, double bankBefore, double bankAfter,
        double shortfall, bool totemFired, Phase outcome)
    {
        Round = round;
        Payment = payment;
        BankBefore = bankBefore;
        BankAfter = bankAfter;
        Shortfall = shortfall;
        TotemFired = totemFired;
        Outcome = outcome;
    }

    public bool Paid => Shortfall == 0;
}

/// <summary>
/// The run state machine, economy-rework edition (PLAN.md 2026-07-13). Callers drive:
/// PlaceTicket* → LockRound → (sweat the sessions / cash out / play consumables) → FinishSweat →
/// Settle → (Shop: buy/sell) → ExitShop → … Settle now DEDUCTS the round's payment from the bank
/// (the income-rate race, design/10): a payment you cannot meet ends the run — unless the Totem
/// of Undying fires (never on the final payment). Debt-as-HP and the float are deleted.
///
/// Passives live in the <see cref="EffectEngine"/> (Multiplier / Scar Tissue / Totem — all payout
/// effects multiply into Ticket.PayoutMultiplier). Consumables are a separate pool of player-TIMED
/// verbs: Profit Boost at PlaceTicket, Mulligan Slip at a sweat's pending-loss window. The
/// bookie GIFTS a consumable after consecutive losing rounds (the
/// pity/retention channel — he wants you betting). LockRound still samples the fixed outcome
/// universe; consumable timing can never perturb the run seed.
/// </summary>
public sealed class Run
{
    public RunConfig Config { get; }
    public RngHub Rng { get; }
    public int Round { get; private set; } = 1;
    public double Bank { get; private set; }

    /// <summary>COMPS (design/10 F): the book's loyalty currency, earned per dollar staked,
    /// spent in the shop. Charm-expansion accounting (PLAN.md rev 5): the authoritative balance
    /// is an INTEGER count of tenths — no hidden fractional state. Wagering earnings pool in a
    /// per-round raw buffer and commit ONCE at LockRound (remainder discarded); every other
    /// mutation moves exact tenths at its own commit point.</summary>
    public double Comps => _deciComps / 10.0;

    private long _deciComps;
    private double _compsAccrualRaw;

    /// <summary>Converts a comps amount to integer tenths (AwayFromZero — PLAN.md rev 5).</summary>
    internal static long ToDeci(double comps)
        => (long)Math.Round(comps * 10.0, MidpointRounding.AwayFromZero);

    public Phase Phase { get; private set; } = Phase.Betting;
    public Slate CurrentSlate { get; private set; }

    private readonly List<Ticket> _tickets = new List<Ticket>();
    public IReadOnlyList<Ticket> Tickets => _tickets;

    private readonly List<SweatSession> _sweats = new List<SweatSession>();

    /// <summary>One session per ticket in placement order; empty until the round is locked.</summary>
    public IReadOnlyList<SweatSession> Sweats => _sweats;

    private readonly EffectEngine _effects;

    /// <summary>Owned passives, in acquisition (purchase) order.</summary>
    public IReadOnlyList<RelicDefinition> OwnedRelics => _effects.Owned;

    private readonly List<ConsumableDefinition> _consumables = new List<ConsumableDefinition>();

    /// <summary>Held consumables (≤ Config.ConsumableSlots), separate pool from relics.</summary>
    public IReadOnlyList<ConsumableDefinition> OwnedConsumables => _consumables;

    private readonly List<RelicDefinition> _shopOffers = new List<RelicDefinition>();
    private readonly List<ConsumableDefinition> _consumableOffers = new List<ConsumableDefinition>();

    /// <summary>Passive offers in the current shop (all unowned; Totem only if never purchased).</summary>
    public IReadOnlyList<RelicDefinition> ShopOffers => _shopOffers;

    /// <summary>Consumable offers in the current shop.</summary>
    public IReadOnlyList<ConsumableDefinition> ConsumableOffers => _consumableOffers;

    /// <summary>The BASE payment schedule: Config.Payments plus Totem surcharges (booked at base
    /// rates — PLAN.md rev 5 §9) plus Marker relief. House Key never mutates this — its ×1.15
    /// applies through the getters below on UNPAID entries only, so selling the Key simply drops
    /// the factor.</summary>
    private readonly double[] _payments;

    public double CurrentPayment => _payments[Round - 1] * _effects.PaymentFactor;

    /// <summary>The following round's payment (surcharges and payment factors included), or null
    /// on the final round — what a player planning shop spending is planning against.</summary>
    public double? NextPayment
        => Round < Config.Rounds ? _payments[Round] * _effects.PaymentFactor : (double?)null;

    /// <summary>The full live schedule — the book's public ledger. Unpaid entries (current round
    /// onward) carry the live payment factor; settled entries show their base history.</summary>
    public IReadOnlyList<double> PaymentSchedule
    {
        get
        {
            var view = new double[_payments.Length];
            double factor = _effects.PaymentFactor;
            for (int i = 0; i < _payments.Length; i++)
                view[i] = i >= Round - 1 ? _payments[i] * factor : _payments[i];
            return view;
        }
    }

    /// <summary>Telemetry of the most recent settle; null before the first.</summary>
    public SettlementReport? LastSettlement { get; private set; }

    /// <summary>The consumable the bookie just gifted at the round's open (null when none) —
    /// presentation's cue for the gift text.</summary>
    public ConsumableDefinition? LastGift { get; private set; }

    /// <summary>Scar Tissue's visible ratchet state, in percentage points.</summary>
    public double ScarStacks => _effects.ScarStacks;

    /// <summary>The Totem is sellable and its charge consumable, but it can be BOUGHT only once
    /// per run, ever (design/10 B).</summary>
    public bool TotemEverPurchased { get; private set; }

    private double _bankAtBettingStart;
    private int _consecutiveLosingRounds;
    private int _roundsSinceGift;

    // Charm-expansion legality latches (PLAN.md rev 5 §7-8).
    private bool _markerPlayedThisRound;
    private bool _managerUsedThisVisit;
    private int _managerRedealOrdinal;

    /// <summary>The visible effect-state snapshot (ratchet stacks, streaks) — the UI's window
    /// into persistent item state (design/10 mandate, PLAN.md rev 5 §20).</summary>
    public IReadOnlyList<EffectStat> EffectStates => _effects.StateSnapshot();

    public Run(string runSeed, RunConfig? config = null)
    {
        Config = config ?? new RunConfig();
        Rng = new RngHub(runSeed);
        Bank = Config.StartingBank;
        _effects = new EffectEngine(GrantComps);
        _payments = (double[])Config.Payments.Clone();
        _bankAtBettingStart = Bank;
        _roundsSinceGift = Config.GiftCooldownRounds; // the first eligible gift is not cooldown-blocked
        CurrentSlate = SlateGenerator.Generate(Round, Rng.Slate, Config);
    }

    // ------------------------------------------------------------------ betting

    /// <summary>Places a ticket. profitBoostLeg ≥ 0 plays a held Profit Boost on that leg (its
    /// offered odds ×<see cref="RelicCatalog.ProfitBoostMult"/> before pricing) and consumes it.
    /// A locked contract <paramref name="modifier"/> (Free Bet / Double or Nothing — one per
    /// ticket, the one-modifier law) consumes its consumable and prices into the contract.</summary>
    public Ticket PlaceTicket(IReadOnlyList<Pick> picks, double stake, int profitBoostLeg = -1,
        TicketModifier modifier = TicketModifier.None)
    {
        RequirePhase(Phase.Betting);
        if (_tickets.Count >= Config.MaxTicketsPerRound)
            throw new InvalidOperationException($"Max {Config.MaxTicketsPerRound} tickets per round");
        if (picks.Count < 1 || picks.Count > Config.MaxLegs)
            throw new ArgumentException($"Tickets take 1 to {Config.MaxLegs} legs, got {picks.Count}");
        if (picks.Select(p => p.MatchupIndex).Distinct().Count() != picks.Count)
            throw new ArgumentException("A ticket cannot have two legs on the same matchup");
        if (stake < Config.MinStake)
            throw new ArgumentException($"Minimum stake is {Config.MinStake}, got {stake}");

        double maxStake = Config.MaxStakeFraction * Bank;
        if (stake > maxStake)
            throw new ArgumentException($"Stake {stake} exceeds the max stake {maxStake} for bank {Bank}");

        // Atomic legality (PLAN.md rev 5 §7): every consumable this placement needs is validated
        // BEFORE anything is consumed.
        if (profitBoostLeg >= 0)
        {
            if (profitBoostLeg >= picks.Count)
                throw new ArgumentException($"Profit Boost leg {profitBoostLeg} is not on this ticket");
            if (!OwnsConsumable("profit_boost"))
                throw new InvalidOperationException("No Profit Boost held");
        }
        if (modifier == TicketModifier.FreeBet && !OwnsConsumable("free_bet"))
            throw new InvalidOperationException("No Free Bet Token held");
        if (modifier == TicketModifier.DoubleOrNothing && !OwnsConsumable("double_or_nothing"))
            throw new InvalidOperationException("No Double or Nothing Slip held");

        var legs = picks
            .Select(p =>
            {
                Matchup matchup = CurrentSlate.Matchups[p.MatchupIndex];
                return new Leg(matchup, p.Side, matchup.Odds(p.Side));
            })
            .ToList();

        // The played Profit Boost rewrites the chosen leg's offered odds BEFORE vig is computed —
        // like every promo, it can legitimately drive the ticket's vig to zero or below.
        if (profitBoostLeg >= 0)
        {
            legs[profitBoostLeg].OfferedOdds *= RelicCatalog.ProfitBoostMult;
            ConsumeConsumable("profit_boost");
        }

        double offered = OddsMath.ParlayDecimal(legs.Select(l => l.OfferedOdds).ToList());
        double fair = OddsMath.FairDecimal(OddsMath.ParlayProb(legs.Select(l => l.TrueProb).ToList()));
        var ticket = new Ticket(legs, stake, OddsMath.VigPaid(stake, offered, fair))
        {
            Id = $"{Round}.{_tickets.Count}",
        };

        if (modifier != TicketModifier.None)
        {
            ConsumeConsumable(modifier == TicketModifier.FreeBet ? "free_bet" : "double_or_nothing");
            ticket.Modifier = modifier;
            if (modifier == TicketModifier.DoubleOrNothing)
                ticket.SetFactor("don", RelicCatalog.DoubleOrNothingMult);
        }

        // Placement effects (Multiplier, Scar carrier) see the bank BEFORE the stake is deducted.
        _effects.ApplyTicketPlaced(ticket, stake, Bank, isFirstTicketThisRound: _tickets.Count == 0);

        Bank -= stake;
        _compsAccrualRaw += stake * Config.CompsPerDollarStaked; // pools raw; commits once at lock
        _tickets.Add(ticket);
        return ticket;
    }

    /// <summary>Plays a held Bookie's Marker: this round's payment drops by the relief fraction.
    /// Once per round — he keeps count (PLAN.md rev 5 §7).</summary>
    public void PlayBookiesMarker()
    {
        RequirePhase(Phase.Betting);
        if (_markerPlayedThisRound)
            throw new InvalidOperationException("The Marker is once per round");
        if (!OwnsConsumable("bookies_marker"))
            throw new InvalidOperationException("No Bookie's Marker held");

        ConsumeConsumable("bookies_marker");
        _markerPlayedThisRound = true;
        _payments[Round - 1] *= 1.0 - RelicCatalog.MarkerRelief;
    }

    public void LockRound()
    {
        RequirePhase(Phase.Betting);

        // The round's comps accrual COMMITS here — once, in tenths, remainder discarded — so
        // the Whale/Collection snapshots below read the same balance the player sees.
        _deciComps += ToDeci(_compsAccrualRaw);
        _compsAccrualRaw = 0;

        // Lock-time factor snapshots (chalk/iron/jar/system/whale/collection/housekey/photo):
        // no RNG involved, and the factor maps are frozen after this except the designed toggles.
        _effects.ApplyLock(this);

        // Every game on the slate resolves, bet or not, in slate order: outcomes for a seed are
        // identical no matter what the player wagered (the fixed universe).
        foreach (Matchup matchup in CurrentSlate.Matchups)
            matchup.Result = Rng.Outcomes.NextDouble() < matchup.TrueHomeProb ? Side.Home : Side.Away;

        _sweats.Clear();
        foreach (Ticket ticket in _tickets)
        {
            IReadOnlyList<IReadOnlyList<DramaEvent>> paths =
                DramaGenerator.BuildTicketPaths(ticket, Rng.Drama, Config.Drama, Round);

            _sweats.Add(new SweatSession(ticket, paths, Config, CreditBank, _effects,
                mulliganAvailable: () => OwnsConsumable("mulligan_slip"),
                whistleAvailable: () => OwnsConsumable("refs_whistle"),
                HandleBust));
        }

        Phase = Phase.Sweat;
    }

    // ------------------------------------------------------------------ sweat-time consumables

    /// <summary>Plays a held Mulligan Slip on the session's pending dead leg: the leg is voided
    /// and the sweat continues. Only valid inside the pending-loss window.</summary>
    public void PlayMulliganSlip(SweatSession session)
    {
        RequirePhase(Phase.Sweat);
        if (session == null) throw new ArgumentNullException(nameof(session));
        if (!session.HasPendingLoss)
            throw new InvalidOperationException("No dead leg is awaiting a Mulligan Slip");
        if (!OwnsConsumable("mulligan_slip"))
            throw new InvalidOperationException("No Mulligan Slip held");

        ConsumeConsumable("mulligan_slip");
        session.ResolvePendingLossAsMulligan();
        // The designed post-lock toggle (PLAN.md rev 5 §2): a void can strip the ticket's last
        // qualifying longshot leg — only the photo factor re-evaluates.
        _effects.RefreshPhotoFactor(session.TicketRef);
    }

    /// <summary>Plays a held Ref's Whistle on the session's pending dead leg: the leg's GRADING
    /// re-rolls once at the win-prob the player was living on before the killing event (this
    /// slip only — the shared result never bends). Overturned → the leg stands at full odds;
    /// confirmed → the ticket dies. Works on single-leg tickets (PLAN.md rev 5 §4-5).</summary>
    public void PlayRefsWhistle(SweatSession session)
    {
        RequirePhase(Phase.Sweat);
        if (session == null) throw new ArgumentNullException(nameof(session));
        if (!session.HasPendingLoss)
            throw new InvalidOperationException("No dead leg is awaiting a Ref's Whistle");
        if (!OwnsConsumable("refs_whistle"))
            throw new InvalidOperationException("No Ref's Whistle held");

        ConsumeConsumable("refs_whistle");
        Pcg32 roll = Rng.Derive(Round, session.TicketRef.Id, session.PendingDeadLegIndex, "whistle", 0);
        session.ResolvePendingLossWithWhistle(roll);
    }

    // Timeout (a cash-out offer hold) was CUT at playtest #8 — its PlayTimeout verb lived here.
    // The SweatSession live-intervention seam it rode (ApplyLiveEffect/OfferHoldEffect) remains.

    // ------------------------------------------------------------------ settle

    /// <summary>Settles the round after the sweat: every still-Open ticket resolves Won (all active
    /// legs green — payout credited, scar carrier burns) or Lost (the scar feeds). Then the
    /// terminal-realization ledger runs (PLAN.md rev 5 §4): Free Bet refunds issue exactly once,
    /// early busts included.</summary>
    public void FinishSweat()
    {
        RequirePhase(Phase.Sweat);
        if (!_sweats.All(s => s.IsComplete))
            throw new InvalidOperationException("Every sweat session must be complete before finishing the sweat.");

        foreach (Ticket ticket in _tickets)
        {
            if (ticket.State != TicketState.Open) continue; // CashedOut or dead-leg Lost: already settled

            if (ticket.GradesWon)
            {
                ticket.State = TicketState.Won;
                Bank += ticket.PotentialPayout;
                _effects.OnTicketRealized(ticket);
            }
            else
            {
                ticket.State = TicketState.Lost;
                HandleBust(ticket);
            }
        }

        // Terminal-realization ledger: every Lost Free Bet ticket refunds its stake, once.
        // The loss still happened everywhere it matters (scar fed, jar counts it).
        foreach (Ticket ticket in _tickets)
        {
            if (ticket.State == TicketState.Lost
                && ticket.Modifier == TicketModifier.FreeBet
                && !ticket.Refunded)
            {
                ticket.Refunded = true;
                Bank += ticket.Stake;
            }
        }

        Phase = Phase.Settlement;
    }

    /// <summary>Drains every session without cashing out or playing consumables (pending losses
    /// auto-decline), then finishes the sweat. The sim's fast path.</summary>
    public void FastForwardRound()
    {
        RequirePhase(Phase.Sweat);
        foreach (SweatSession session in _sweats)
            while (session.MoveNext(out _)) { }
        FinishSweat();
    }

    private void CreditBank(double amount) => Bank += amount;

    private void HandleBust(Ticket ticket) => _effects.OnBust(ticket);

    /// <summary>
    /// The payment settle (design/10): the round's payment is DEDUCTED. Meet it and the run
    /// advances (final round → RunWon). Miss it and the run is over — unless the Totem of Undying
    /// has a charge and this is not the final payment: the whole payment is DEFERRED (the bank is
    /// untouched — working capital survives, playtest #8) and the NEXT payment grows by
    /// payment × (1 + juice). The final payment is never deferrable ("no next favor").
    /// </summary>
    public void Settle()
    {
        RequirePhase(Phase.Settlement);
        bool finalRound = Round == Config.Rounds;
        // The EFFECTIVE payment: base schedule × the live payment factor (House Key). The base
        // array is never factor-mutated — getters own the view (PLAN.md rev 5 §9).
        double payment = _payments[Round - 1] * _effects.PaymentFactor;
        double bankBefore = Bank;
        double shortfall = 0;
        bool totemFired = false;

        // RoundResolution fires BEFORE the payment (after the refund ledger): The System and
        // the Bad Beat Jar read the round as played, not as taxed.
        double roundPnl = bankBefore - _bankAtBettingStart;
        int won = 0, lost = 0, cashed = 0;
        double refunds = 0;
        foreach (Ticket t in _tickets)
        {
            if (t.State == TicketState.Won) won++;
            else if (t.State == TicketState.Lost) lost++;
            else if (t.State == TicketState.CashedOut) cashed++;
            if (t.Refunded) refunds += t.Stake;
        }
        _effects.OnRoundResolved(new RoundResolution(
            Round, roundPnl, _tickets.Count, won, lost, cashed, refunds));

        if (Bank >= payment)
        {
            Bank -= payment;
            Phase = finalRound ? Phase.RunWon : Phase.Shop;
        }
        else if (!finalRound && _effects.TryConsumeTotem())
        {
            // Playtest #8: the totem DEFERS the whole payment — bank untouched, and the payment
            // plus juice lands on the next one. The surcharge books at BASE rates (Codex r2 #3):
            // the House Key factor applies once, through the getters, never compounded in.
            shortfall = payment - Bank;
            _payments[Round] += _payments[Round - 1] * (1.0 + Config.TotemJuiceRate);
            totemFired = true;
            Phase = Phase.Shop;
        }
        else
        {
            shortfall = payment - Bank;
            Phase = Phase.RunLost;
        }

        LastSettlement = new SettlementReport(Round, payment, bankBefore, Bank, shortfall, totemFired, Phase);

        _consecutiveLosingRounds = roundPnl < 0 ? _consecutiveLosingRounds + 1 : 0;

        if (Phase == Phase.Shop)
            EnterShop();
    }

    // ------------------------------------------------------------------ shop

    /// <summary>Buys the passive at the offer index. Buying the Totem marks it purchased for the
    /// rest of the run (it never reappears in the shop, even after selling or burning).</summary>
    public void BuyRelic(int offerIndex)
    {
        RequirePhase(Phase.Shop);
        if (offerIndex < 0 || offerIndex >= _shopOffers.Count)
            throw new ArgumentOutOfRangeException(nameof(offerIndex));

        RelicDefinition def = _shopOffers[offerIndex];
        long price = ToDeci(def.Price);
        if (price > _deciComps)
            throw new InvalidOperationException($"Relic {def.Id} costs {def.Price} comps, you have {Comps}");
        if (OwnedRelics.Count >= Config.RelicSlots)
            throw new InvalidOperationException($"All {Config.RelicSlots} relic slots are full");

        _deciComps -= price;
        _effects.Add(def);
        if (def.Id == RelicCatalog.TotemId)
            TotemEverPurchased = true;
        _shopOffers.RemoveAt(offerIndex);
    }

    public void BuyConsumable(int offerIndex)
    {
        RequirePhase(Phase.Shop);
        if (offerIndex < 0 || offerIndex >= _consumableOffers.Count)
            throw new ArgumentOutOfRangeException(nameof(offerIndex));

        ConsumableDefinition def = _consumableOffers[offerIndex];
        long price = ToDeci(def.Price);
        if (price > _deciComps)
            throw new InvalidOperationException($"{def.Id} costs {def.Price} comps, you have {Comps}");
        if (_consumables.Count >= Config.ConsumableSlots)
            throw new InvalidOperationException($"All {Config.ConsumableSlots} consumable slots are full");

        _deciComps -= price;
        _consumables.Add(def);
        _consumableOffers.RemoveAt(offerIndex);
    }

    /// <summary>The single resale truth (PLAN.md rev 5 §10): Bobblehead's 3× override rides its
    /// resaleMult param; a fired (spent) Totem is worth 0; everything else sells at the global
    /// SellBackFraction of list.</summary>
    public double GetResaleValue(RelicDefinition def)
    {
        if (_effects.TotemSpent(def)) return 0.0;
        if (def.Params.TryGetValue("resaleMult", out double mult))
            return def.Price * mult;
        return def.Price * Config.SellBackFraction;
    }

    /// <summary>Sells the owned passive at the index for its <see cref="GetResaleValue"/>. A sold
    /// stateful passive loses its state (stacks die with the behavior); a sold Totem cannot be
    /// re-bought.</summary>
    public void SellRelic(int ownedIndex)
    {
        RequirePhase(Phase.Shop);
        if (ownedIndex < 0 || ownedIndex >= _effects.Owned.Count)
            throw new ArgumentOutOfRangeException(nameof(ownedIndex));

        _deciComps += ToDeci(GetResaleValue(_effects.Owned[ownedIndex]));
        _effects.RemoveAt(ownedIndex);
    }

    public void SellConsumable(int ownedIndex)
    {
        RequirePhase(Phase.Shop);
        if (ownedIndex < 0 || ownedIndex >= _consumables.Count)
            throw new ArgumentOutOfRangeException(nameof(ownedIndex));

        _deciComps += ToDeci(_consumables[ownedIndex].Price * Config.SellBackFraction);
        _consumables.RemoveAt(ownedIndex);
    }

    /// <summary>Plays a held Ask for the Manager: the whole hand is redealt once per visit. The
    /// redeal draws from a DERIVED stream — the Shop stream is untouched, so future visits deal
    /// identically whether or not the Manager was called (PLAN.md rev 5 §6, §8).</summary>
    public void PlayAskManager()
    {
        RequirePhase(Phase.Shop);
        if (_managerUsedThisVisit)
            throw new InvalidOperationException("The Manager comes out once per visit");
        if (!OwnsConsumable("ask_manager"))
            throw new InvalidOperationException("No Ask for the Manager held");

        ConsumeConsumable("ask_manager");
        _managerUsedThisVisit = true;
        DealOffers(Rng.Derive(Round, "", -1, "redeal", _managerRedealOrdinal++));
    }

    /// <summary>Shop entry: one-time effects fire (Rake's Rebate interest), the Manager latch
    /// resets, and the hand is dealt. A Manager redeal calls <see cref="DealOffers"/> ONLY —
    /// entry effects never replay (PLAN.md rev 5 §8).</summary>
    private void EnterShop()
    {
        _effects.OnShopEnter(this);
        _managerUsedThisVisit = false;
        DealOffers(Rng.Shop);
    }

    /// <summary>Pure dealing (the DEALT HAND, PLAN.md rev 5 §8): PassiveOfferCount distinct
    /// passives from the unowned pool (a purchased-ever Totem is out forever; short pools deal
    /// what remains) + ConsumableOfferCount distinct consumables.</summary>
    private void DealOffers(Pcg32 rng)
    {
        _shopOffers.Clear();
        var pool = new List<RelicDefinition>();
        foreach (RelicDefinition d in RelicCatalog.All)
        {
            if (_effects.Owns(d.Id)) continue;
            if (d.Id == RelicCatalog.TotemId && TotemEverPurchased) continue;
            pool.Add(d);
        }
        int deal = Math.Min(Config.PassiveOfferCount, pool.Count);
        for (int i = 0; i < deal; i++)
        {
            int j = rng.NextInt(i, pool.Count);
            (pool[i], pool[j]) = (pool[j], pool[i]);
            _shopOffers.Add(pool[i]);
        }

        _consumableOffers.Clear();
        var candidates = new List<ConsumableDefinition>(RelicCatalog.Consumables);
        int take = Math.Min(Config.ConsumableOfferCount, candidates.Count);
        for (int i = 0; i < take; i++)
        {
            int j = rng.NextInt(i, candidates.Count);
            (candidates[i], candidates[j]) = (candidates[j], candidates[i]);
            _consumableOffers.Add(candidates[i]);
        }
    }

    /// <summary>Rake's Rebate seam: interest on the held balance, committed in exact tenths.
    /// Public for the deci-comp quantization tests; gameplay reaches it only via the Rebate.</summary>
    public void ApplyCompsInterest(double rate)
        => _deciComps += (long)Math.Round(_deciComps * rate, MidpointRounding.AwayFromZero);

    public void ExitShop()
    {
        RequirePhase(Phase.Shop);
        _shopOffers.Clear();
        _consumableOffers.Clear();
        Round++;
        _tickets.Clear();
        _sweats.Clear();
        _markerPlayedThisRound = false;
        CurrentSlate = SlateGenerator.Generate(Round, Rng.Slate, Config);
        Phase = Phase.Betting;
        _bankAtBettingStart = Bank;

        // The bookie's gift (pity/retention channel, design/10 D): after enough consecutive
        // losing rounds, off cooldown, with a slot free, he texts you a promo — he wants you
        // betting. Deterministic per seed via the Shop stream.
        LastGift = null;
        _roundsSinceGift++;
        if (_consecutiveLosingRounds >= Config.GiftAfterLosingRounds
            && _roundsSinceGift >= Config.GiftCooldownRounds
            && _consumables.Count < Config.ConsumableSlots)
        {
            ConsumableDefinition gift =
                RelicCatalog.Consumables[Rng.Shop.NextInt(0, RelicCatalog.Consumables.Count)];
            _consumables.Add(gift);
            LastGift = gift;
            _roundsSinceGift = 0;
        }
    }

    // ------------------------------------------------------------------ audit/test seams

    /// <summary>Grants a passive directly — no shop, no price, no slot check. The sim's
    /// granted-free item audit and the engine tests script item states through this.</summary>
    public void GrantRelic(RelicDefinition def)
    {
        _effects.Add(def);
        if (def.Id == RelicCatalog.TotemId)
            TotemEverPurchased = true;
    }

    /// <summary>Grants a consumable directly (audit/test seam; ignores slot limits).</summary>
    public void GrantConsumable(ConsumableDefinition def) => _consumables.Add(def);

    /// <summary>Grants comps directly (Comp'd Suite's award seam + tests), in exact tenths.</summary>
    public void GrantComps(double comps) => _deciComps += ToDeci(comps);

    // ------------------------------------------------------------------ helpers

    public bool OwnsConsumable(string id)
    {
        foreach (ConsumableDefinition c in _consumables)
            if (c.Id == id) return true;
        return false;
    }

    private void ConsumeConsumable(string id)
    {
        for (int i = 0; i < _consumables.Count; i++)
        {
            if (_consumables[i].Id == id)
            {
                _consumables.RemoveAt(i);
                return;
            }
        }
        throw new InvalidOperationException($"No {id} held");
    }

    private void RequirePhase(Phase expected)
    {
        if (Phase != expected)
            throw new InvalidOperationException($"Expected phase {expected}, but run is in {Phase}");
    }
}

namespace SBR.Engine;

/// <summary>
/// Named RNG streams per design/05: outcomes, drama, slate, and shop draw from
/// independent generators so that, e.g., which relics the shop offers can never
/// perturb match results for the same run seed.
/// </summary>
public sealed class RngHub
{
    public string RunSeed { get; }

    /// <summary>Match results.</summary>
    public Pcg32 Outcomes { get; }

    /// <summary>Drama-generator event sequences (Week 2).</summary>
    public Pcg32 Drama { get; }

    /// <summary>Slate, team, and odds generation.</summary>
    public Pcg32 Slate { get; }

    /// <summary>Shop offers (Week 3).</summary>
    public Pcg32 Shop { get; }

    /// <summary>Relic effects: tout-sheet intel and lucky-charm second-chance rolls (Week 3).</summary>
    public Pcg32 Relics { get; }

    public RngHub(string runSeed)
    {
        RunSeed = runSeed;
        ulong seed = Fnv1a64(runSeed);
        Outcomes = new Pcg32(seed, Fnv1a64("outcomes"));
        Drama = new Pcg32(seed, Fnv1a64("drama"));
        Slate = new Pcg32(seed, Fnv1a64("slate"));
        Shop = new Pcg32(seed, Fnv1a64("shop"));
        Relics = new Pcg32(seed, Fnv1a64("relics"));
    }

    public static ulong Fnv1a64(string s)
    {
        ulong hash = 14695981039346656037UL;
        foreach (char c in s)
        {
            hash ^= c;
            hash *= 1099511628211UL;
        }
        return hash;
    }

    /// <summary>
    /// Derived one-shot stream (charm expansion, PLAN.md rev 5 §6): fully keyed by run seed,
    /// round, ticket, leg, action, and use ordinal, so no two derivations collide and NONE of
    /// the named streams above is ever consumed — consumable timing can never perturb the run.
    /// Whistle rolls key (round, ticketId, legIndex, "whistle", 0); Manager redeals key
    /// (round, "", -1, "redeal", useOrdinal).
    /// </summary>
    public Pcg32 Derive(int round, string ticketId, int legIndex, string action, int ordinal)
        => new Pcg32(Fnv1a64(RunSeed), Fnv1a64($"{round}#{ticketId}#{legIndex}#{action}#{ordinal}"));
}

using System;
using System.Globalization;
using System.Threading;
using SBR.Engine;

namespace SBR.ConsoleGame;

/// <summary>
/// Thin console primitives: ConsoleColor writes that always restore the prior colour, money/odds
/// formatting, the win-prob bar, and the handful of input helpers. No raw ANSI (Windows-safe).
/// Every method that could throw on a redirected stream (Clear, sleeps) degrades quietly so the
/// --auto smoke harness and piped runs never blow up.
/// </summary>
internal static class Ui
{
    private static readonly CultureInfo Inv = CultureInfo.InvariantCulture;

    public static void Write(ConsoleColor c, string s)
    {
        ConsoleColor prev = Console.ForegroundColor;
        Console.ForegroundColor = c;
        Console.Write(s);
        Console.ForegroundColor = prev;
    }

    public static void WriteLine(ConsoleColor c, string s)
    {
        Write(c, s);
        Console.WriteLine();
    }

    public static void Line() => Console.WriteLine();

    public static void Rule() => WriteLine(ConsoleColor.DarkGray, new string('─', 62));

    /// <summary>Whole-dollar money, thousands-separated. Negatives render as "-$X".</summary>
    public static string Money(double v)
    {
        double r = Math.Round(v);
        string body = Math.Abs(r).ToString("#,##0", Inv);
        return (r < 0 ? "-$" : "$") + body;
    }

    /// <summary>Signed whole-dollar delta, e.g. "+$412" / "-$200".</summary>
    public static string Signed(double v)
    {
        double r = Math.Round(v);
        return (r < 0 ? "-$" : "+$") + Math.Abs(r).ToString("#,##0", Inv);
    }

    /// <summary>American odds string with an explicit leading sign (+150 / -145).</summary>
    public static string American(double decimalOdds)
    {
        int a = OddsMath.AmericanFromDecimal(decimalOdds);
        return a >= 0 ? "+" + a.ToString(Inv) : a.ToString(Inv);
    }

    public static int Pct(double p) => (int)Math.Round(p * 100.0);

    /// <summary>A [####----]-style win-prob bar of the given width.</summary>
    public static string Bar(double prob, int width)
    {
        int filled = (int)Math.Round(Math.Clamp(prob, 0.0, 1.0) * width);
        filled = Math.Clamp(filled, 0, width);
        return "[" + new string('#', filled) + new string('-', width - filled) + "]";
    }

    public static void Clear()
    {
        try { Console.Clear(); } catch { /* redirected stream: nothing to clear */ }
    }

    /// <summary>Sleep, unless input is redirected (piped/auto) — then return instantly so nothing blocks.</summary>
    public static void Beat(int ms)
    {
        if (Console.IsInputRedirected) return;
        Thread.Sleep(ms);
    }

    /// <summary>True once stdin hit end-of-file (a piped script ran out of lines). Callers treat it
    /// as "quit" — otherwise a premature-EOF piped session would spin on the command loop forever.</summary>
    public static bool Eof { get; private set; }

    public static string Prompt(string label)
    {
        Write(ConsoleColor.White, label);
        string? s = Console.ReadLine();
        if (s == null)
        {
            Eof = true;
            return "";
        }
        return s.Trim();
    }

    public static void Pause()
    {
        Write(ConsoleColor.DarkGray, "  (enter to continue) ");
        Console.ReadLine();
    }

    public static bool Confirm(string label)
    {
        string s = Prompt(label).ToUpperInvariant();
        return s.StartsWith("Y", StringComparison.Ordinal);
    }

    public static void Title()
    {
        Clear();
        WriteLine(ConsoleColor.Cyan, "╔══════════════════════════════════════════════════════════╗");
        WriteLine(ConsoleColor.Cyan, "║   S B R   —   build it · lock it · sweat it              ║");
        WriteLine(ConsoleColor.Cyan, "╚══════════════════════════════════════════════════════════╝");
        WriteLine(ConsoleColor.DarkGray, "  a sports-betting roguelite prototype · the text era");
        Line();
    }
}

namespace SBR.Engine;

/// <summary>Tuning defaults. The /sim harness exists to move these numbers — the economy rework's
/// gate campaign (PLAN.md 2026-07-13, gates G1–G6) owns the payment curve.</summary>
public sealed class RunConfig
{
    public double StartingBank { get; set; } = 350;

    /// <summary>The debt-payment schedule (economy rework, design/10): DEDUCTED from the bank at
    /// each settle — miss a payment and the run is over (unless the Totem fires). Two-phase convex
    /// (the campaign's discovered shape): gentle build window, then the cliff. Under the COMPS
    /// currency (design/10 F) the cash bank starts at only ~2–3 payments, so BETTING IS MANDATORY
    /// from round 1 — idling is death (Allen's round-1 ruling). The grid re-tunes these.</summary>
    public double[] Payments { get; set; } = { 60, 70, 85, 105, 155, 375, 710, 1350 };

    /// <summary>COMPS (design/10 F): the second currency, earned per dollar STAKED — the book's
    /// loyalty program, and items are bought with it. Chasing comps is −EV cash, exactly like a
    /// real VIP program; the shop no longer competes with payments for bankroll.</summary>
    public double CompsPerDollarStaked { get; set; } = 0.12;

    public double Overround { get; set; } = 0.05;
    public double CashOutMargin { get; set; } = 0.08;
    public double MinStake { get; set; } = 10;

    /// <summary>Cap on a single ticket's stake as a fraction of the current bank. 1.0 = uncapped (all-in
    /// allowed) — lifted 2026-07-08 after playtest #1. Kept as a dial for /sim experiments. Boundary
    /// inclusive: a stake exactly at the cap is allowed.</summary>
    public double MaxStakeFraction { get; set; } = 1.0;

    public int MaxTicketsPerRound { get; set; } = 3;
    public int MatchupsPerSlate { get; set; } = 6;
    public int MaxLegs { get; set; } = 6;
    public int PriorGames { get; set; } = 9;
    public double MinTrueProb { get; set; } = 0.25;
    public double MaxTrueProb { get; set; } = 0.75;

    /// <summary>Max passive relics owned at once. The rework catalog has 3 passives; slots stay
    /// roomier for the committed item-growth direction (design/10 B2).</summary>
    public int RelicSlots { get; set; } = 5;

    /// <summary>Max consumables held at once (separate pool from relics — playtest #1 split).
    /// 3 since playtest #8: with one shop offer per visit, a third slot lets a player bank saves
    /// for the cliff — the G3 band's buy-back for the tighter offer draw.</summary>
    public int ConsumableSlots { get; set; } = 3;

    /// <summary>Passive offers dealt per shop visit (charm expansion: the DEALT HAND — a random
    /// draw from the unowned pool replaces show-everything at catalog size 15). Tuned to 4:
    /// at 3 the engine-finding variance starved too many builds; at 5 the win rate rode the
    /// band ceiling. A specific item shows ~27%/visit at 4-of-15 — scarcity stays real.</summary>
    public int PassiveOfferCount { get; set; } = 4;

    /// <summary>Consumable offers dealt per shop visit. History: 2 → 1 at playtest #8 (a 2-item
    /// pool with 2 slots guaranteed the strongest item every shop) → 3 for the charm expansion:
    /// the 7-item pool does the dilution (a specific tool shows ~43% of visits), and the wider
    /// hand is where the toolbox decisions live.</summary>
    public int ConsumableOfferCount { get; set; } = 3;

    /// <summary>Sell-back fraction of list price, both pools (design/10, Allen 2026-07-12).</summary>
    public double SellBackFraction { get; set; } = 0.5;

    /// <summary>Consecutive net-losing rounds before the bookie texts a free consumable
    /// (the gift/pity channel, design/10 D), and the minimum rounds between gifts.</summary>
    public int GiftAfterLosingRounds { get; set; } = 2;
    public int GiftCooldownRounds { get; set; } = 2;

    /// <summary>Totem of Undying: the DEFERRED payment is added to the NEXT payment at
    /// payment × (1 + this rate). Playtest #8 made the totem leave the bank untouched; the G3
    /// campaign showed the juice barely moves win rate (the offer draw is the binding knob), so
    /// the ratified 0.5 stands.</summary>
    public double TotemJuiceRate { get; set; } = 0.5;

    /// <summary>Pacing dials for the drama generator (design/04); flows through Run into every SweatSession.</summary>
    public DramaConfig Drama { get; set; } = new DramaConfig();

    public int Rounds => Payments.Length;
}

using System;
using System.Collections.Generic;
using System.Globalization;
using SBR.Engine;

namespace SBR.ConsoleGame;

internal enum BetAction { Locked, Quit }

/// <summary>
/// The Phase.Betting screen and its single-letter command loop. Renders the header (bank, target,
/// any bookie debt), relics, the slate, and tickets placed so far, then dispatches B / L / Q. Every
/// engine call is wrapped so a bad input prints the message and returns to the loop — the shell
/// never crashes.
/// </summary>
internal static class BettingScreen
{
    public static BetAction Run(Run run)
    {
        while (true)
        {
            Render(run);
            string cmd = Ui.Prompt(CommandBar()).ToUpperInvariant();
            if (Ui.Eof) return BetAction.Quit;
            switch (cmd)
            {
                case "B":
                    Build(run);
                    break;

                case "K":
                    try
                    {
                        run.PlayBookiesMarker();
                        Ui.WriteLine(ConsoleColor.Cyan,
                            $"MARKER PLAYED — this round's payment drops to {Ui.Money(run.CurrentPayment)}.");
                    }
                    catch (Exception ex) { Ui.WriteLine(ConsoleColor.Red, ex.Message); }
                    Ui.Pause();
                    break;

                case "L":
                    if (run.Tickets.Count == 0 && !Ui.Confirm("no bets this round? the payment still comes due — y/n: ")) break;
                    run.LockRound();
                    return BetAction.Locked;

                case "Q":
                    if (Ui.Confirm("quit the run? y/n: ")) return BetAction.Quit;
                    break;

                default:
                    Unknown();
                    break;
            }
        }
    }

    private static void Unknown()
    {
        Ui.WriteLine(ConsoleColor.Red, "Unknown command.");
        Ui.Pause();
    }

    private static string CommandBar()
        => "commands: [B]uild ticket  [K] marker  [L]ock round  [Q]uit  > ";

    // ---- rendering ----

    private static void Render(Run run)
    {
        Ui.Clear();
        Ui.WriteLine(ConsoleColor.Cyan,
            $"ROUND {run.Round}/{run.Config.Rounds}  ·  BANK {Ui.Money(run.Bank)}  ·  PAYMENT DUE {Ui.Money(run.CurrentPayment)}"
            + $"  ·  COMPS {run.Comps:0.#}  ·  SEED {run.Rng.RunSeed}");
        Ui.WriteLine(ConsoleColor.DarkGray,
            $"tickets {run.Tickets.Count}/{run.Config.MaxTicketsPerRound}  ·  relics {run.OwnedRelics.Count}/{run.Config.RelicSlots}"
            + $"  ·  consumables {run.OwnedConsumables.Count}/{run.Config.ConsumableSlots}"
            + $"  ·  staking earns comps ({run.Config.CompsPerDollarStaked:0.##}/$)");

        // The whole ledger is public information (design/10) — show what is coming.
        var schedule = new List<string>();
        for (int r = run.Round - 1; r < run.PaymentSchedule.Count; r++)
            schedule.Add(Ui.Money(run.PaymentSchedule[r]));
        Ui.WriteLine(ConsoleColor.DarkGray, "SCHEDULE: " + string.Join(" → ", schedule));

        if (run.ScarStacks > 0)
            Ui.WriteLine(ConsoleColor.Magenta,
                $"SCAR {run.ScarStacks:0.#}pp — your FIRST ticket this round carries it (burns on a hit)");
        GameLoop.WriteEffectStates(run); // chalk/iron/jar/system stacks (rev 5 §20)

        if (run.OwnedRelics.Count > 0)
        {
            var names = new List<string>();
            foreach (RelicDefinition r in run.OwnedRelics) names.Add(r.Name);
            Ui.WriteLine(ConsoleColor.Cyan, "RELICS: " + string.Join(", ", names));
        }

        if (run.OwnedConsumables.Count > 0)
        {
            var names = new List<string>();
            foreach (ConsumableDefinition c in run.OwnedConsumables) names.Add(c.Name);
            Ui.WriteLine(ConsoleColor.Cyan, "CONSUMABLES: " + string.Join(", ", names));
        }

        Ui.Rule();
        RenderSlate(run);

        if (run.Tickets.Count > 0)
        {
            Ui.Line();
            Ui.WriteLine(ConsoleColor.White, "TICKETS");
            for (int i = 0; i < run.Tickets.Count; i++)
                Ui.WriteLine(ConsoleColor.Gray, $" {i + 1}. {DescribeLegs(run.Tickets[i])}  |  {Ui.Money(run.Tickets[i].Stake)} → {Ui.Money(run.Tickets[i].PotentialPayout)}");
        }

        Ui.Line();
    }

    private static void RenderSlate(Run run)
    {
        Ui.WriteLine(ConsoleColor.White, "SLATE  (away @ home · moneyline)");

        foreach (Matchup m in run.CurrentSlate.Matchups)
        {
            string away = $"{m.Away.Name} ({m.Away.Record})";
            string home = $"{m.Home.Name} ({m.Home.Record})";
            string line = $" {m.Index + 1}. {away.PadRight(28)} {Ui.American(m.AwayOdds),5}   @   {home.PadRight(28)} {Ui.American(m.HomeOdds),5}";
            Ui.WriteLine(ConsoleColor.Gray, line);
        }
    }

    private static string DescribeLegs(Ticket t)
    {
        var parts = new List<string>();
        foreach (Leg leg in t.Legs)
        {
            string team = Short(leg.Side == Side.Home ? leg.Matchup.Home.Name : leg.Matchup.Away.Name);
            string mark = Math.Abs(leg.OfferedOdds - leg.BaseOdds) > 1e-9 ? " ^boosted" : "";
            parts.Add($"{team} {Ui.American(leg.OfferedOdds)}{mark}");
        }
        return string.Join(", ", parts);
    }

    // ---- B: build a ticket ----

    private static void Build(Run run)
    {
        string picksLine = Ui.Prompt("picks> (e.g. 1H 3A 5H)  ");
        List<Pick> picks;
        try
        {
            picks = ParsePicks(picksLine, run.CurrentSlate.Matchups.Count);
        }
        catch (Exception ex)
        {
            Ui.WriteLine(ConsoleColor.Red, ex.Message);
            Ui.Pause();
            return;
        }

        if (picks.Count == 0)
        {
            Ui.WriteLine(ConsoleColor.Red, "No picks entered.");
            Ui.Pause();
            return;
        }

        string stakeLine = Ui.Prompt("stake> ");
        if (!double.TryParse(stakeLine, NumberStyles.Any, CultureInfo.InvariantCulture, out double stake))
        {
            Ui.WriteLine(ConsoleColor.Red, "Stake must be a number.");
            Ui.Pause();
            return;
        }

        // A held Profit Boost is played at the betslip (design/10 D): pick the leg it lands on.
        int boostLeg = -1;
        if (run.OwnsConsumable("profit_boost") && picks.Count > 0)
        {
            string b = Ui.Prompt($"PROFIT BOOST held — boost which leg? (1-{picks.Count}, enter to skip) ");
            if (int.TryParse(b, NumberStyles.Integer, CultureInfo.InvariantCulture, out int bl)
                && bl >= 1 && bl <= picks.Count)
            {
                boostLeg = bl - 1;
            }
        }

        // Locked contract modifiers (one per ticket — the one-modifier law).
        TicketModifier modifier = TicketModifier.None;
        bool hasFree = run.OwnsConsumable("free_bet");
        bool hasDon = run.OwnsConsumable("double_or_nothing");
        if (hasFree || hasDon)
        {
            string opts = hasFree && hasDon ? "[F]ree bet / [D]ouble-or-nothing"
                : hasFree ? "[F]ree bet" : "[D]ouble-or-nothing";
            string m = Ui.Prompt($"modifier? {opts} (enter to skip) ").ToUpperInvariant();
            if (m == "F" && hasFree) modifier = TicketModifier.FreeBet;
            else if (m == "D" && hasDon) modifier = TicketModifier.DoubleOrNothing;
        }

        try
        {
            Ticket t = run.PlaceTicket(picks, stake, boostLeg, modifier);
            string tag = t.Modifier == TicketModifier.FreeBet ? "  [FREE BET]"
                : t.Modifier == TicketModifier.DoubleOrNothing ? "  [DOUBLE OR NOTHING — no cash-out]" : "";
            Ui.WriteLine(ConsoleColor.Green,
                $"TICKET PLACED: {DescribeLegs(t)}  |  {Ui.Money(t.Stake)} → {Ui.Money(t.PotentialPayout)}{tag}");
        }
        catch (Exception ex)
        {
            Ui.WriteLine(ConsoleColor.Red, ex.Message); // engine validation, verbatim
        }

        Ui.Pause();
    }

    // ---- parsing ----

    private static List<Pick> ParsePicks(string line, int matchupCount)
    {
        var picks = new List<Pick>();
        foreach (string tok in line.Split(new[] { ' ', ',' }, StringSplitOptions.RemoveEmptyEntries))
        {
            (int idx, Side side) = ParseOne(tok, matchupCount);
            picks.Add(new Pick(idx, side));
        }
        return picks;
    }

    private static (int idx, Side side) ParseOne(string token, int matchupCount)
    {
        token = token.Trim();
        if (token.Length < 2)
            throw new ArgumentException($"Bad pick '{token}' — use a number then H or A, e.g. 1H.");

        char sc = char.ToUpperInvariant(token[token.Length - 1]);
        Side side = sc == 'H' ? Side.Home
                  : sc == 'A' ? Side.Away
                  : throw new ArgumentException($"Bad side in '{token}' — end with H (home) or A (away).");

        string num = token.Substring(0, token.Length - 1);
        if (!int.TryParse(num, NumberStyles.Integer, CultureInfo.InvariantCulture, out int n))
            throw new ArgumentException($"Bad matchup number in '{token}'.");

        int idx = n - 1;
        if (idx < 0 || idx >= matchupCount)
            throw new ArgumentException($"Matchup {n} is off the slate (pick 1–{matchupCount}).");

        return (idx, side);
    }

    // ---- helpers ----

    private static string Short(string teamName)
    {
        int i = teamName.LastIndexOf(' ');
        return i >= 0 ? teamName.Substring(i + 1) : teamName;
    }
}

