using System.Collections.Generic;
using SBR.Engine;

namespace SBR.Sim;

/// <summary>
/// Per-run scratch for a bot. Strategy objects are stateless singletons shared across parallel runs,
/// so anything a bot must remember within one run lives here (created fresh per run by the harness).
/// </summary>
public sealed class BotState
{
    /// <summary>The bot's estimate of P(home wins) per matchup index for the current round. Populated by
    /// the bot at bet time from the info a player could have (de-vigged odds).</summary>
    public readonly Dictionary<int, double> HomeProbEst = new();

    public void NewRound() => HomeProbEst.Clear();
}

/// <summary>The pending-loss window verbs a bot can choose between (charm expansion, PLAN.md
/// rev 5 §13). RunPlayer validates legality (holdings, mulligan's ≥2-active-legs rule) and
/// falls back to Decline when the choice is illegal.</summary>
public enum PendingLossAction { Decline, Mulligan, Whistle }

/// <summary>
/// A pluggable strategy bot (PRD F9). Hooks: <see cref="Bet"/> (betting window), <see cref="ShouldCashOut"/>
/// (per sweat event, only when <see cref="ControlsSweat"/>), <see cref="ChoosePendingLossAction"/>
/// (the save window), and <see cref="Shop"/> (between rounds).
///
/// HONESTY RULE (enforced by convention across all bots): a bot may read only what a player could know —
/// odds, records, the bank/debt/requirement, and revealed drama events (evt.WinProbAfter). A bot must
/// NEVER read Matchup.TrueHomeProb, Leg.TrueProb, or Matchup.Result. Only the harness (Metrics) reads truth.
/// </summary>
public interface IStrategy
{
    string Name { get; }

    /// <summary>When false the harness fast-forwards the sweat (never cashing out) and never calls
    /// <see cref="ShouldCashOut"/>. Naive is the only bot that opts out.</summary>
    bool ControlsSweat { get; }

    /// <summary>Betting window: place 0..MaxTickets tickets via run.PlaceTicket.</summary>
    void Bet(Run run, BotState state, Pcg32 rng);

    /// <summary>
    /// Called once per sweat event on an open, cash-out-eligible ticket when an offer exists.
    /// Return true to take <paramref name="offer"/>. <paramref name="bankNow"/> is the live bank and
    /// <paramref name="target"/> the round's settle requirement (target + any bookie debt);
    /// <paramref name="evt"/>.WinProbAfter is the on-screen live win% of the current leg
    /// (legitimate player information).
    /// </summary>
    bool ShouldCashOut(Run run, Ticket ticket, SweatSession session, DramaEvent evt,
        double offer, double bankNow, double target, BotState state, Pcg32 rng);

    /// <summary>
    /// The pending-loss window (rev 5 §13). Default policy (the documented bot greed): a legal
    /// Mulligan is the certain save — take it; else a held Whistle fires when the captured
    /// pre-kill prob gives at least a coin-flip's worth of rescue; else decline.
    /// </summary>
    PendingLossAction ChoosePendingLossAction(Run run, Ticket ticket, SweatSession session,
        BotState state, Pcg32 rng)
    {
        if (run.OwnsConsumable("mulligan_slip") && session.CanMulliganPendingLoss)
            return PendingLossAction.Mulligan;
        if (run.OwnsConsumable("refs_whistle") && session.PendingLossProbBefore >= 0.35)
            return PendingLossAction.Whistle;
        return PendingLossAction.Decline;
    }

    /// <summary>Shop window: buy relics via run.BuyRelic.</summary>
    void Shop(Run run, BotState state, Pcg32 rng);
}
using System;
using System.Collections.Generic;
using SBR.Engine;

namespace SBR.Sim;

/// <summary>
/// NAIVE — the PRD S3 baseline: "bet favorites, never cash out, no relics" (target: median death round 3–4).
///
/// Policy, every round:
///   • One 2-leg parlay on the two biggest favorites. The bot cannot see true probs, so it reads the
///     ODDS: the two shortest-priced sides on the slate (each matchup's favorite is its shorter side, so
///     the two globally shortest sides always land on distinct matchups — a legal ticket).
///   • Stake = 25% of the current bank, floored to whole dollars, never below MinStake; skip the round's
///     bet entirely if the bank is under MinStake (per the OPEN-QUESTIONS playtest note — a bank fraction,
///     NOT the old flat $50 cap that made a naive bettor mathematically unable to clear round 1).
///   • Never cashes out (ControlsSweat = false → the harness fast-forwards the sweat).
///   • Buys nothing.
///
/// HONESTY: reads only Matchup.Odds/HomeOdds/AwayOdds (public book prices). Never touches true probs.
/// </summary>
public sealed class NaiveStrategy : IStrategy
{
    public string Name => "naive";
    public bool ControlsSweat => false;

    private const double StakeFraction = 0.25;
    private const int Legs = 2;

    public void Bet(Run run, BotState state, Pcg32 rng)
    {
        if (run.Bank < run.Config.MinStake) return;

        double stake = Math.Max(run.Config.MinStake, Math.Floor(StakeFraction * run.Bank));
        if (stake > run.Bank) return; // defensive; StakeFraction < 1 keeps this from tripping

        IReadOnlyList<Matchup> slate = run.CurrentSlate.Matchups;
        if (slate.Count < Legs) return;

        // Each matchup's favorite (shorter-priced side) and its odds.
        var favs = new List<(int matchup, Side side, double odds)>(slate.Count);
        foreach (Matchup m in slate)
        {
            Side fav = m.HomeOdds <= m.AwayOdds ? Side.Home : Side.Away;
            favs.Add((m.Index, fav, m.Odds(fav)));
        }
        favs.Sort((a, b) => a.odds.CompareTo(b.odds)); // shortest-priced first

        var picks = new List<Pick>(Legs);
        for (int i = 0; i < Legs; i++)
            picks.Add(new Pick(favs[i].matchup, favs[i].side));

        run.PlaceTicket(picks, stake);
    }

    // Never called (ControlsSweat is false), but the interface requires it.
    public bool ShouldCashOut(Run run, Ticket ticket, SweatSession session, DramaEvent evt,
        double offer, double bankNow, double target, BotState state, Pcg32 rng) => false;

    public void Shop(Run run, BotState state, Pcg32 rng) { /* buys nothing */ }
}
using System;
using System.Collections.Generic;
using SBR.Engine;

namespace SBR.Sim;

/// <summary>
/// RANDOM — a noise floor between naive and skilled: legal but thoughtless play.
///
/// Policy:
///   • Betting: 1–3 tickets, each 1–4 legs on random distinct matchups and random sides, each staked a
///     random 10–50% of the (shrinking) bank, floored to whole dollars and never below MinStake.
///   • Sweat: steps the sessions and cashes out with 5% probability per event whenever an offer exists.
///   • Shop: half the time, buys one random affordable offer.
///
/// HONESTY: picks sides and matchups at random — it never consults probabilities at all, true or implied.
/// </summary>
public sealed class RandomStrategy : IStrategy
{
    public string Name => "random";
    public bool ControlsSweat => true;

    private const double CashOutChancePerEvent = 0.05;
    private const double ShopBuyChance = 0.5;

    public void Bet(Run run, BotState state, Pcg32 rng)
    {
        int slateCount = run.CurrentSlate.Matchups.Count;
        int tickets = rng.NextInt(1, Math.Min(run.Config.MaxTicketsPerRound, 3) + 1); // 1..3

        for (int t = 0; t < tickets; t++)
        {
            if (run.Bank < run.Config.MinStake) break;

            int maxLegs = Math.Min(4, Math.Min(run.Config.MaxLegs, slateCount));
            int legs = rng.NextInt(1, maxLegs + 1); // 1..4

            var picks = new List<Pick>(legs);
            foreach (int m in DistinctMatchups(rng, slateCount, legs))
                picks.Add(new Pick(m, rng.NextDouble() < 0.5 ? Side.Home : Side.Away));

            double frac = 0.1 + 0.4 * rng.NextDouble(); // 10..50%
            double stake = Math.Max(run.Config.MinStake, Math.Floor(frac * run.Bank));
            if (stake > run.Bank) break;

            run.PlaceTicket(picks, stake);
        }
    }

    public bool ShouldCashOut(Run run, Ticket ticket, SweatSession session, DramaEvent evt,
        double offer, double bankNow, double target, BotState state, Pcg32 rng)
        => rng.NextDouble() < CashOutChancePerEvent;

    public void Shop(Run run, BotState state, Pcg32 rng)
    {
        // Codex r2 #13 fix: affordability is COMPS (the shop currency), never cash — and the
        // random shopper picks legally across BOTH dealt rows within their separate slot limits.
        if (rng.NextDouble() >= ShopBuyChance) return;

        var passives = new List<int>();
        if (run.OwnedRelics.Count < run.Config.RelicSlots)
            for (int i = 0; i < run.ShopOffers.Count; i++)
                if (run.ShopOffers[i].Price <= run.Comps) passives.Add(i);

        var consumables = new List<int>();
        if (run.OwnedConsumables.Count < run.Config.ConsumableSlots)
            for (int i = 0; i < run.ConsumableOffers.Count; i++)
                if (run.ConsumableOffers[i].Price <= run.Comps) consumables.Add(i);

        int total = passives.Count + consumables.Count;
        if (total == 0) return;

        int pick = rng.NextInt(0, total);
        if (pick < passives.Count) run.BuyRelic(passives[pick]);
        else run.BuyConsumable(consumables[pick - passives.Count]);
    }

    // Partial Fisher-Yates: `count` distinct indices from [0, n).
    private static IEnumerable<int> DistinctMatchups(Pcg32 rng, int n, int count)
    {
        var pool = new int[n];
        for (int i = 0; i < n; i++) pool[i] = i;
        for (int i = 0; i < count; i++)
        {
            int j = rng.NextInt(i, n);
            (pool[i], pool[j]) = (pool[j], pool[i]);
            yield return pool[i];
        }
    }
}

        if (picks.Select(p => p.MatchupIndex).Distinct().Count() != picks.Count)
            throw new ArgumentException("A ticket cannot have two legs on the same matchup");
        if (stake < Config.MinStake)
            throw new ArgumentException($"Minimum stake is {Config.MinStake}, got {stake}");

        double maxStake = Config.MaxStakeFraction * Bank;
        if (stake > maxStake)
            throw new ArgumentException($"Stake {stake} exceeds the max stake {maxStake} for bank {Bank}");

        // Atomic legality (PLAN.md rev 5 §7): every consumable this placement needs is validated
        // BEFORE anything is consumed.
        if (profitBoostLeg >= 0)
        {
            if (profitBoostLeg >= picks.Count)
                throw new ArgumentException($"Profit Boost leg {profitBoostLeg} is not on this ticket");
            if (!OwnsConsumable("profit_boost"))
                throw new InvalidOperationException("No Profit Boost held");
        }
        if (modifier == TicketModifier.FreeBet && !OwnsConsumable("free_bet"))
            throw new InvalidOperationException("No Free Bet Token held");
        if (modifier == TicketModifier.DoubleOrNothing && !OwnsConsumable("double_or_nothing"))
            throw new InvalidOperationException("No Double or Nothing Slip held");

        var legs = picks
            .Select(p =>
            {
                Matchup matchup = CurrentSlate.Matchups[p.MatchupIndex];
                return new Leg(matchup, p.Side, matchup.Odds(p.Side));
            })
            .ToList();

        // The played Profit Boost rewrites the chosen leg's offered odds BEFORE vig is computed —
        // like every promo, it can legitimately drive the ticket's vig to zero or below.
        if (profitBoostLeg >= 0)
        {
            legs[profitBoostLeg].OfferedOdds *= RelicCatalog.ProfitBoostMult;
            ConsumeConsumable("profit_boost");
        }

        double offered = OddsMath.ParlayDecimal(legs.Select(l => l.OfferedOdds).ToList());
        double fair = OddsMath.FairDecimal(OddsMath.ParlayProb(legs.Select(l => l.TrueProb).ToList()));
        var ticket = new Ticket(legs, stake, OddsMath.VigPaid(stake, offered, fair))
        {
            Id = $"{Round}.{_tickets.Count}",
        };

        if (modifier != TicketModifier.None)
        {
            ConsumeConsumable(modifier == TicketModifier.FreeBet ? "free_bet" : "double_or_nothing");
            ticket.Modifier = modifier;
            if (modifier == TicketModifier.DoubleOrNothing)
                ticket.SetFactor("don", RelicCatalog.DoubleOrNothingMult);
        }

        // Placement effects (Multiplier, Scar carrier) see the bank BEFORE the stake is deducted.
        _effects.ApplyTicketPlaced(ticket, stake, Bank, isFirstTicketThisRound: _tickets.Count == 0);

        Bank -= stake;
        _compsAccrualRaw += stake * Config.CompsPerDollarStaked; // pools raw; commits once at lock
        _tickets.Add(ticket);
        return ticket;
    }

    /// <summary>Plays a held Bookie's Marker: this round's payment drops by the relief fraction.
    /// Once per round — he keeps count (PLAN.md rev 5 §7).</summary>
    public void PlayBookiesMarker()
    {
        RequirePhase(Phase.Betting);
        if (_markerPlayedThisRound)
            throw new InvalidOperationException("The Marker is once per round");
        if (!OwnsConsumable("bookies_marker"))
            throw new InvalidOperationException("No Bookie's Marker held");

        ConsumeConsumable("bookies_marker");
        _markerPlayedThisRound = true;
        _payments[Round - 1] *= 1.0 - RelicCatalog.MarkerRelief;
    }

    public void LockRound()
    {
        RequirePhase(Phase.Betting);

        // The round's comps accrual COMMITS here — once, in tenths, remainder discarded — so
        // the Whale/Collection snapshots below read the same balance the player sees.
        _deciComps += ToDeci(_compsAccrualRaw);
        _compsAccrualRaw = 0;

        // Lock-time factor snapshots (chalk/iron/jar/system/whale/collection/housekey/photo):
        // no RNG involved, and the factor maps are frozen after this except the designed toggles.
        _effects.ApplyLock(this);

        // Every game on the slate resolves, bet or not, in slate order: outcomes for a seed are
        // identical no matter what the player wagered (the fixed universe).
        foreach (Matchup matchup in CurrentSlate.Matchups)
            matchup.Result = Rng.Outcomes.NextDouble() < matchup.TrueHomeProb ? Side.Home : Side.Away;

        _sweats.Clear();
        foreach (Ticket ticket in _tickets)
        {
            IReadOnlyList<IReadOnlyList<DramaEvent>> paths =
                DramaGenerator.BuildTicketPaths(ticket, Rng.Drama, Config.Drama, Round);

            _sweats.Add(new SweatSession(ticket, paths, Config, CreditBank, _effects,
                mulliganAvailable: () => OwnsConsumable("mulligan_slip"),
                whistleAvailable: () => OwnsConsumable("refs_whistle"),
                HandleBust));
        }

        Phase = Phase.Sweat;
    }

    // ------------------------------------------------------------------ sweat-time consumables

    /// <summary>Plays a held Mulligan Slip on the session's pending dead leg: the leg is voided
    /// and the sweat continues. Only valid inside the pending-loss window.</summary>
    public void PlayMulliganSlip(SweatSession session)
    {
        RequirePhase(Phase.Sweat);
        if (session == null) throw new ArgumentNullException(nameof(session));
        if (!session.HasPendingLoss)
            throw new InvalidOperationException("No dead leg is awaiting a Mulligan Slip");
        if (!OwnsConsumable("mulligan_slip"))
            throw new InvalidOperationException("No Mulligan Slip held");

        ConsumeConsumable("mulligan_slip");
        session.ResolvePendingLossAsMulligan();
        // The designed post-lock toggle (PLAN.md rev 5 §2): a void can strip the ticket's last
        // qualifying longshot leg — only the photo factor re-evaluates.
        _effects.RefreshPhotoFactor(session.TicketRef);
    }

    /// <summary>Plays a held Ref's Whistle on the session's pending dead leg: the leg's GRADING
    /// re-rolls once at the win-prob the player was living on before the killing event (this
    /// slip only — the shared result never bends). Overturned → the leg stands at full odds;
    /// confirmed → the ticket dies. Works on single-leg tickets (PLAN.md rev 5 §4-5).</summary>
    public void PlayRefsWhistle(SweatSession session)
    {
        RequirePhase(Phase.Sweat);
        if (session == null) throw new ArgumentNullException(nameof(session));
        if (!session.HasPendingLoss)
            throw new InvalidOperationException("No dead leg is awaiting a Ref's Whistle");
        if (!OwnsConsumable("refs_whistle"))
            throw new InvalidOperationException("No Ref's Whistle held");

        ConsumeConsumable("refs_whistle");
        Pcg32 roll = Rng.Derive(Round, session.TicketRef.Id, session.PendingDeadLegIndex, "whistle", 0);
        session.ResolvePendingLossWithWhistle(roll);
    }

    // Timeout (a cash-out offer hold) was CUT at playtest #8 — its PlayTimeout verb lived here.
    // The SweatSession live-intervention seam it rode (ApplyLiveEffect/OfferHoldEffect) remains.

    // ------------------------------------------------------------------ settle

    /// <summary>Settles the round after the sweat: every still-Open ticket resolves Won (all active
    /// legs green — payout credited, scar carrier burns) or Lost (the scar feeds). Then the
    /// terminal-realization ledger runs (PLAN.md rev 5 §4): Free Bet refunds issue exactly once,
    /// early busts included.</summary>
    public void FinishSweat()
    {
        RequirePhase(Phase.Sweat);
        if (!_sweats.All(s => s.IsComplete))
            throw new InvalidOperationException("Every sweat session must be complete before finishing the sweat.");

        foreach (Ticket ticket in _tickets)
        {
            if (ticket.State != TicketState.Open) continue; // CashedOut or dead-leg Lost: already settled

            if (ticket.GradesWon)
            {
                ticket.State = TicketState.Won;
                Bank += ticket.PotentialPayout;
                _effects.OnTicketRealized(ticket);
            }
            else
            {
                ticket.State = TicketState.Lost;
                HandleBust(ticket);
            }
        }

        // Terminal-realization ledger: every Lost Free Bet ticket refunds its stake, once.
        // The loss still happened everywhere it matters (scar fed, jar counts it).
        foreach (Ticket ticket in _tickets)
        {
            if (ticket.State == TicketState.Lost
                && ticket.Modifier == TicketModifier.FreeBet
                && !ticket.Refunded)
            {
                ticket.Refunded = true;
                Bank += ticket.Stake;
            }
        }

        Phase = Phase.Settlement;
    }

    /// <summary>Drains every session without cashing out or playing consumables (pending losses
    /// auto-decline), then finishes the sweat. The sim's fast path.</summary>
    public void FastForwardRound()
    {
        RequirePhase(Phase.Sweat);
        foreach (SweatSession session in _sweats)
            while (session.MoveNext(out _)) { }
        FinishSweat();
    }

    private void CreditBank(double amount) => Bank += amount;

    private void HandleBust(Ticket ticket) => _effects.OnBust(ticket);

