using System;
using System.Collections.Generic;
using System.Linq;

namespace SBR.Engine;

public enum Side { Home, Away }

public enum LegState { Pending, Won, Lost }

public enum TicketState { Open, Won, Lost, CashedOut }

/// <summary>A ticket's final, ticket-local grading of one leg — what OnLegResolved carries
/// after any pending-loss window has closed (charm expansion, PLAN.md rev 5).</summary>
public enum LegGrade { Won, Lost, Voided }

/// <summary>Locked contract modifiers (charm expansion): at most ONE per ticket — the
/// one-modifier law, mirror of the one-product-slot law. Locked at placement, part of the
/// ticket's outcome→cash-flow contract (they price into cash-outs and G4).</summary>
public enum TicketModifier { None, FreeBet, DoubleOrNothing }

public sealed class Team
{
    public string Name { get; }
    public int Wins { get; }
    public int Losses { get; }
    public string Record => $"{Wins}-{Losses}";

    public Team(string name, int wins, int losses)
    {
        Name = name;
        Wins = wins;
        Losses = losses;
    }
}

public sealed class Matchup
{
    public int Index { get; }
    public Team Home { get; }
    public Team Away { get; }
    public double TrueHomeProb { get; }
    public double HomeOdds { get; }
    public double AwayOdds { get; }

    /// <summary>Set once at round lock, shared by every leg referencing this matchup.</summary>
    public Side? Result { get; internal set; }

    public Matchup(int index, Team home, Team away, double trueHomeProb, double homeOdds, double awayOdds)
    {
        Index = index;
        Home = home;
        Away = away;
        TrueHomeProb = trueHomeProb;
        HomeOdds = homeOdds;
        AwayOdds = awayOdds;
    }

    public double TrueProb(Side side) => side == Side.Home ? TrueHomeProb : 1.0 - TrueHomeProb;
    public double Odds(Side side) => side == Side.Home ? HomeOdds : AwayOdds;
    public double FairOdds(Side side) => 1.0 / TrueProb(side);
}

public sealed class Slate
{
    public int Round { get; }
    public IReadOnlyList<Matchup> Matchups { get; }

    public Slate(int round, IReadOnlyList<Matchup> matchups)
    {
        Round = round;
        Matchups = matchups;
    }
}

public readonly struct Pick
{
    public int MatchupIndex { get; }
    public Side Side { get; }

    public Pick(int matchupIndex, Side side)
    {
        MatchupIndex = matchupIndex;
        Side = side;
    }
}

public sealed class Leg
{
    public Matchup Matchup { get; }
    public Side Side { get; }

    /// <summary>The matchup's own price for the picked side — the odds before any relic touched them.</summary>
    public double BaseOdds { get; }

    /// <summary>The locked contract odds. Equals <see cref="BaseOdds"/> unless a compose-time relic
    /// (boosted_odds, promo_code) rewrote it before the ticket locked.</summary>
    public double OfferedOdds { get; internal set; }

    /// <summary>Set when a Mulligan Slip voids this leg after it reveals Lost: the leg is struck from
    /// the ticket (excluded from payout, win condition, and cash-out products).</summary>
    public bool IsVoided { get; internal set; }

    /// <summary>Ref's Whistle rescue (charm expansion): a successful grading re-roll marks THIS
    /// ticket's copy of the leg Won. Ticket-local by construction — Legs belong to one ticket;
    /// the shared <see cref="Matchup.Result"/> never bends (Lucky Charm precedent).</summary>
    public bool RescuedWon { get; internal set; }

    public Leg(Matchup matchup, Side side, double offeredOdds)
    {
        Matchup = matchup;
        Side = side;
        OfferedOdds = offeredOdds;
        BaseOdds = offeredOdds;
    }

    public double TrueProb => Matchup.TrueProb(Side);

    public LegState State =>
        Matchup.Result == null ? LegState.Pending
        : Matchup.Result == Side ? LegState.Won
        : LegState.Lost;

    /// <summary>This ticket's grading of the leg. Voided legs never count as won; a whistle-rescued
    /// leg counts as won for this ticket only.</summary>
    public bool GradesWon => !IsVoided && (RescuedWon || State == LegState.Won);
}

public sealed class Ticket
{
    public IReadOnlyList<Leg> Legs { get; }
    public double Stake { get; }
    public double VigPaid { get; }
    public TicketState State { get; internal set; } = TicketState.Open;

    /// <summary>Stable per-run identity: "round.placementIndex" — the DeriveRng key component
    /// (charm expansion, PLAN.md rev 5).</summary>
    public string Id { get; internal set; } = "";

    /// <summary>The named factor map behind <see cref="PayoutMultiplier"/> (charm expansion):
    /// each payout effect owns one named ×(1+x) factor ("multiplier", "scar", "photo", "whale",
    /// "collection", "chalk", "iron", "jar", "system", "housekey", "don"). Immutable after lock
    /// EXCEPT the designed toggles (photo drops when its last qualifying leg is voided).</summary>
    private readonly Dictionary<string, double> _factors = new Dictionary<string, double>();

    internal void SetFactor(string name, double value) => _factors[name] = value;
    internal void RemoveFactor(string name) => _factors.Remove(name);
    internal bool HasFactor(string name) => _factors.ContainsKey(name);

    /// <summary>Payout scale from relic effects — THE product slot (design/10 B2): the product
    /// of every named factor, so items stack multiplicatively. Scales the win payout and the
    /// cash-out fair value.</summary>
    public double PayoutMultiplier
    {
        get
        {
            double p = 1.0;
            foreach (double f in _factors.Values) p *= f;
            return p;
        }
    }

    /// <summary>The locked contract modifier (one per ticket — the one-modifier law): Free Bet
    /// refunds the stake on a loss; Double or Nothing doubles the product and suppresses
    /// cash-out offers.</summary>
    public TicketModifier Modifier { get; internal set; } = TicketModifier.None;

    /// <summary>Free Bet's exactly-once latch, set by the terminal-realization ledger.</summary>
    public bool Refunded { get; internal set; }

    /// <summary>Scar Tissue bookkeeping (design/10 B): the stacks this ticket's bust would add,
    /// baked at placement from its stake fraction; and whether this ticket carries (and on a win
    /// or cash-out, burns) the current stacks — the round's FIRST-placed ticket carries.</summary>
    internal double ScarStacksIfBust { get; set; }
    internal bool ScarCarrier { get; set; }

    public Ticket(IReadOnlyList<Leg> legs, double stake, double vigPaid)
    {
        Legs = legs;
        Stake = stake;
        VigPaid = vigPaid;
    }

    /// <summary>Legs that still count toward the ticket: voided (mulligan'd) legs are excluded.</summary>
    public IEnumerable<Leg> ActiveLegs => Legs.Where(l => !l.IsVoided);

    /// <summary>A ticket wins when it has at least one active leg and every active leg grades Won.</summary>
    public bool GradesWon
    {
        get
        {
            bool any = false;
            foreach (Leg l in Legs)
            {
                if (l.IsVoided) continue;
                any = true;
                if (!l.GradesWon) return false;
            }
            return any;
        }
    }

    /// <summary>Payout on a win: stake × product of the active legs' offered odds (voided legs drop out),
    /// scaled by any relic payout multiplier.</summary>
    public double PotentialPayout => Stake * OddsMath.ParlayDecimal(ActiveLegs.Select(l => l.OfferedOdds).ToList()) * PayoutMultiplier;
}

using System;
using System.Collections.Generic;
using System.Globalization;
using SBR.Engine;

namespace SBR.ConsoleGame;

internal enum BetAction { Locked, Quit }

/// <summary>
/// The Phase.Betting screen and its single-letter command loop. Renders the header (bank, target,
/// any bookie debt), relics, the slate, and tickets placed so far, then dispatches B / L / Q. Every
/// engine call is wrapped so a bad input prints the message and returns to the loop — the shell
/// never crashes.
/// </summary>
internal static class BettingScreen
{
    public static BetAction Run(Run run)
    {
        while (true)
        {
            Render(run);
            string cmd = Ui.Prompt(CommandBar()).ToUpperInvariant();
            if (Ui.Eof) return BetAction.Quit;
            switch (cmd)
            {
                case "B":
                    Build(run);
                    break;

                case "K":
                    try
                    {
                        run.PlayBookiesMarker();
                        Ui.WriteLine(ConsoleColor.Cyan,
                            $"MARKER PLAYED — this round's payment drops to {Ui.Money(run.CurrentPayment)}.");
                    }
                    catch (Exception ex) { Ui.WriteLine(ConsoleColor.Red, ex.Message); }
                    Ui.Pause();
                    break;

                case "L":
                    if (run.Tickets.Count == 0 && !Ui.Confirm("no bets this round? the payment still comes due — y/n: ")) break;
                    run.LockRound();
                    return BetAction.Locked;

                case "Q":
                    if (Ui.Confirm("quit the run? y/n: ")) return BetAction.Quit;
                    break;

                default:
                    Unknown();
                    break;
            }
        }
    }

    private static void Unknown()
    {
        Ui.WriteLine(ConsoleColor.Red, "Unknown command.");
        Ui.Pause();
    }

    private static string CommandBar()
        => "commands: [B]uild ticket  [K] marker  [L]ock round  [Q]uit  > ";

    // ---- rendering ----

    private static void Render(Run run)
    {
        Ui.Clear();
        Ui.WriteLine(ConsoleColor.Cyan,
            $"ROUND {run.Round}/{run.Config.Rounds}  ·  BANK {Ui.Money(run.Bank)}  ·  PAYMENT DUE {Ui.Money(run.CurrentPayment)}"
            + $"  ·  COMPS {run.Comps:0.#}  ·  SEED {run.Rng.RunSeed}");
        Ui.WriteLine(ConsoleColor.DarkGray,
            $"tickets {run.Tickets.Count}/{run.Config.MaxTicketsPerRound}  ·  relics {run.OwnedRelics.Count}/{run.Config.RelicSlots}"
            + $"  ·  consumables {run.OwnedConsumables.Count}/{run.Config.ConsumableSlots}"
            + $"  ·  staking earns comps ({run.Config.CompsPerDollarStaked:0.##}/$)");

        // The whole ledger is public information (design/10) — show what is coming.
        var schedule = new List<string>();
        for (int r = run.Round - 1; r < run.PaymentSchedule.Count; r++)
            schedule.Add(Ui.Money(run.PaymentSchedule[r]));
        Ui.WriteLine(ConsoleColor.DarkGray, "SCHEDULE: " + string.Join(" → ", schedule));

        if (run.ScarStacks > 0)
            Ui.WriteLine(ConsoleColor.Magenta,
                $"SCAR {run.ScarStacks:0.#}pp — your FIRST ticket this round carries it (burns on a hit)");
        GameLoop.WriteEffectStates(run); // chalk/iron/jar/system stacks (rev 5 §20)

        if (run.OwnedRelics.Count > 0)
        {
            var names = new List<string>();
            foreach (RelicDefinition r in run.OwnedRelics) names.Add(r.Name);
            Ui.WriteLine(ConsoleColor.Cyan, "RELICS: " + string.Join(", ", names));
        }

        if (run.OwnedConsumables.Count > 0)
        {
            var names = new List<string>();
            foreach (ConsumableDefinition c in run.OwnedConsumables) names.Add(c.Name);
            Ui.WriteLine(ConsoleColor.Cyan, "CONSUMABLES: " + string.Join(", ", names));
        }

        Ui.Rule();
        RenderSlate(run);

        if (run.Tickets.Count > 0)
        {
            Ui.Line();
            Ui.WriteLine(ConsoleColor.White, "TICKETS");
            for (int i = 0; i < run.Tickets.Count; i++)
                Ui.WriteLine(ConsoleColor.Gray, $" {i + 1}. {DescribeLegs(run.Tickets[i])}  |  {Ui.Money(run.Tickets[i].Stake)} → {Ui.Money(run.Tickets[i].PotentialPayout)}");
        }

        Ui.Line();
    }

    private static void RenderSlate(Run run)
    {
        Ui.WriteLine(ConsoleColor.White, "SLATE  (away @ home · moneyline)");

        foreach (Matchup m in run.CurrentSlate.Matchups)
        {
            string away = $"{m.Away.Name} ({m.Away.Record})";
            string home = $"{m.Home.Name} ({m.Home.Record})";
            string line = $" {m.Index + 1}. {away.PadRight(28)} {Ui.American(m.AwayOdds),5}   @   {home.PadRight(28)} {Ui.American(m.HomeOdds),5}";
            Ui.WriteLine(ConsoleColor.Gray, line);
        }
    }

    private static string DescribeLegs(Ticket t)
    {
        var parts = new List<string>();
        foreach (Leg leg in t.Legs)
        {
            string team = Short(leg.Side == Side.Home ? leg.Matchup.Home.Name : leg.Matchup.Away.Name);
            string mark = Math.Abs(leg.OfferedOdds - leg.BaseOdds) > 1e-9 ? " ^boosted" : "";
            parts.Add($"{team} {Ui.American(leg.OfferedOdds)}{mark}");
        }
        return string.Join(", ", parts);
    }

    // ---- B: build a ticket ----

    private static void Build(Run run)
    {
        string picksLine = Ui.Prompt("picks> (e.g. 1H 3A 5H)  ");
        List<Pick> picks;
        try
        {
            picks = ParsePicks(picksLine, run.CurrentSlate.Matchups.Count);
        }
        catch (Exception ex)
        {
            Ui.WriteLine(ConsoleColor.Red, ex.Message);
            Ui.Pause();
            return;
        }

        if (picks.Count == 0)
        {
            Ui.WriteLine(ConsoleColor.Red, "No picks entered.");
            Ui.Pause();
            return;
        }

        string stakeLine = Ui.Prompt("stake> ");
        if (!double.TryParse(stakeLine, NumberStyles.Any, CultureInfo.InvariantCulture, out double stake))
        {
            Ui.WriteLine(ConsoleColor.Red, "Stake must be a number.");
            Ui.Pause();
            return;
        }

        // A held Profit Boost is played at the betslip (design/10 D): pick the leg it lands on.
        int boostLeg = -1;
        if (run.OwnsConsumable("profit_boost") && picks.Count > 0)
        {
            string b = Ui.Prompt($"PROFIT BOOST held — boost which leg? (1-{picks.Count}, enter to skip) ");
            if (int.TryParse(b, NumberStyles.Integer, CultureInfo.InvariantCulture, out int bl)
                && bl >= 1 && bl <= picks.Count)
            {
                boostLeg = bl - 1;
            }
        }

        // Locked contract modifiers (one per ticket — the one-modifier law).
        TicketModifier modifier = TicketModifier.None;
        bool hasFree = run.OwnsConsumable("free_bet");
        bool hasDon = run.OwnsConsumable("double_or_nothing");
        if (hasFree || hasDon)
        {
            string opts = hasFree && hasDon ? "[F]ree bet / [D]ouble-or-nothing"
                : hasFree ? "[F]ree bet" : "[D]ouble-or-nothing";
            string m = Ui.Prompt($"modifier? {opts} (enter to skip) ").ToUpperInvariant();
            if (m == "F" && hasFree) modifier = TicketModifier.FreeBet;
            else if (m == "D" && hasDon) modifier = TicketModifier.DoubleOrNothing;
        }

        try
        {
            Ticket t = run.PlaceTicket(picks, stake, boostLeg, modifier);
            string tag = t.Modifier == TicketModifier.FreeBet ? "  [FREE BET]"
                : t.Modifier == TicketModifier.DoubleOrNothing ? "  [DOUBLE OR NOTHING — no cash-out]" : "";
            Ui.WriteLine(ConsoleColor.Green,
                $"TICKET PLACED: {DescribeLegs(t)}  |  {Ui.Money(t.Stake)} → {Ui.Money(t.PotentialPayout)}{tag}");
        }
        catch (Exception ex)
        {
            Ui.WriteLine(ConsoleColor.Red, ex.Message); // engine validation, verbatim
        }

        Ui.Pause();
    }

    // ---- parsing ----

    private static List<Pick> ParsePicks(string line, int matchupCount)
    {
        var picks = new List<Pick>();
        foreach (string tok in line.Split(new[] { ' ', ',' }, StringSplitOptions.RemoveEmptyEntries))
        {
            (int idx, Side side) = ParseOne(tok, matchupCount);
            picks.Add(new Pick(idx, side));
        }
        return picks;
    }

    private static (int idx, Side side) ParseOne(string token, int matchupCount)
    {
        token = token.Trim();
        if (token.Length < 2)
            throw new ArgumentException($"Bad pick '{token}' — use a number then H or A, e.g. 1H.");

        char sc = char.ToUpperInvariant(token[token.Length - 1]);
        Side side = sc == 'H' ? Side.Home
                  : sc == 'A' ? Side.Away
                  : throw new ArgumentException($"Bad side in '{token}' — end with H (home) or A (away).");

        string num = token.Substring(0, token.Length - 1);
        if (!int.TryParse(num, NumberStyles.Integer, CultureInfo.InvariantCulture, out int n))
            throw new ArgumentException($"Bad matchup number in '{token}'.");

        int idx = n - 1;
        if (idx < 0 || idx >= matchupCount)
            throw new ArgumentException($"Matchup {n} is off the slate (pick 1–{matchupCount}).");

        return (idx, side);
    }

    // ---- helpers ----

    private static string Short(string teamName)
    {
        int i = teamName.LastIndexOf(' ');
        return i >= 0 ? teamName.Substring(i + 1) : teamName;
    }
}

