using System;
using System.Collections.Generic;
using SBR.Engine;

namespace SBR.Sim;

/// <summary>
/// NAIVE — the PRD S3 baseline: "bet favorites, never cash out, no relics" (target: median death round 3–4).
///
/// Policy, every round:
///   • One 2-leg parlay on the two biggest favorites. The bot cannot see true probs, so it reads the
///     ODDS: the two shortest-priced sides on the slate (each matchup's favorite is its shorter side, so
///     the two globally shortest sides always land on distinct matchups — a legal ticket).
///   • Stake = 25% of the current bank, floored to whole dollars, never below MinStake; skip the round's
///     bet entirely if the bank is under MinStake (per the OPEN-QUESTIONS playtest note — a bank fraction,
///     NOT the old flat $50 cap that made a naive bettor mathematically unable to clear round 1).
///   • Never cashes out (ControlsSweat = false → the harness fast-forwards the sweat).
///   • Buys nothing.
///
/// HONESTY: reads only Matchup.Odds/HomeOdds/AwayOdds (public book prices). Never touches true probs.
/// </summary>
public sealed class NaiveStrategy : IStrategy
{
    public string Name => "naive";
    public bool ControlsSweat => false;

    private const double StakeFraction = 0.25;
    private const int Legs = 2;

    public void Bet(Run run, BotState state, Pcg32 rng)
    {
        if (run.Bank < run.Config.MinStake) return;

        double stake = Math.Max(run.Config.MinStake, Math.Floor(StakeFraction * run.Bank));
        if (stake > run.Bank) return; // defensive; StakeFraction < 1 keeps this from tripping

        IReadOnlyList<Matchup> slate = run.CurrentSlate.Matchups;
        if (slate.Count < Legs) return;

        // Each matchup's favorite (shorter-priced side) and its odds.
        var favs = new List<(int matchup, Side side, double odds)>(slate.Count);
        foreach (Matchup m in slate)
        {
            Side fav = m.HomeOdds <= m.AwayOdds ? Side.Home : Side.Away;
            favs.Add((m.Index, fav, m.Odds(fav)));
        }
        favs.Sort((a, b) => a.odds.CompareTo(b.odds)); // shortest-priced first

        var picks = new List<Pick>(Legs);
        for (int i = 0; i < Legs; i++)
            picks.Add(new Pick(favs[i].matchup, favs[i].side));

        run.PlaceTicket(picks, stake);
    }

    // Never called (ControlsSweat is false), but the interface requires it.
    public bool ShouldCashOut(Run run, Ticket ticket, SweatSession session, DramaEvent evt,
        double offer, double bankNow, double target, BotState state, Pcg32 rng) => false;

    public void Shop(Run run, BotState state, Pcg32 rng) { /* buys nothing */ }
}

using SBR.Engine;

namespace SBR.ConsoleGame;

/// <summary>
/// The flavour renderer. Engine DramaEvents carry no text on purpose (design/04: the "sport" is a
/// reskin of the event vocabulary), so the console owns the words. Lines are keyed by (Type, direction)
/// where direction is the sign of the win-prob move for the picked side; the first beat of a leg
/// compares against the leg's pre-event TrueProb anchor. Variant chosen by Step (deterministic, no RNG).
/// Tone: deadpan sports broadcast with a dark-comedy undertow (design/00).
/// </summary>
internal static class EventText
{
    public static string For(DramaEvent e, Leg leg, double prevProb)
    {
        if (e.Type == DramaEventType.LegFinal) return "FINAL WHISTLE";

        string picked = Short(leg.Side == Side.Home ? leg.Matchup.Home.Name : leg.Matchup.Away.Name);
        string other = Short(leg.Side == Side.Home ? leg.Matchup.Away.Name : leg.Matchup.Home.Name);
        bool up = e.WinProbAfter >= prevProb;

        // Tag overrides win over the base table.
        if (e.Tag == TensionTag.NearMiss)
            return up ? "off the bar — a miracle brewing?!" : "…cleared off the line. it's slipping away";

        string line = Base(e.Type, up, picked, other, e.Step);
        if (e.Tag == TensionTag.LeadChange) line += " — LEAD CHANGE";
        return line;
    }

    private static string Base(DramaEventType type, bool up, string picked, string other, int step)
    {
        string[] variants = Table(type, up);
        return variants[step % variants.Length]
            .Replace("{picked}", picked)
            .Replace("{other}", other);
    }

    private static string[] Table(DramaEventType type, bool up) => (type, up) switch
    {
        (DramaEventType.Score, true) => ScoreUp,
        (DramaEventType.Score, false) => ScoreDown,
        (DramaEventType.BigPlay, true) => BigUp,
        (DramaEventType.BigPlay, false) => BigDown,
        (DramaEventType.Momentum, true) => MomUp,
        _ => MomDown,
    };

    private static readonly string[] ScoreUp =
    {
        "{picked} slot it home.",
        "{picked} score — far post says yes.",
        "Goal for {picked} — the number ticks your way.",
    };

    private static readonly string[] ScoreDown =
    {
        "{other} answer right back.",
        "{other} poke one in at the near post. Ugly.",
        "{other} on the board; your slip flinches.",
    };

    private static readonly string[] BigUp =
    {
        "{picked} tear away — IT'S IN!",
        "{picked} break the line and finish — the crowd loses it.",
        "{picked} counter at full sprint. This is happening.",
    };

    private static readonly string[] BigDown =
    {
        "Disaster — {other} go the length of the pitch.",
        "{other} rip through on the break. Cover your eyes.",
        "{other} walk it in. That one hurt.",
    };

    private static readonly string[] MomUp =
    {
        "{picked} squeezing the half.",
        "{picked} pin them deep — passes and patience.",
        "{picked} tighten the screws.",
    };

    private static readonly string[] MomDown =
    {
        "{other} keeping the ball.",
        "{other} pass it around, slow and mean.",
        "{other} settle in; the drift is against you.",
    };

    /// <summary>The team's noun (last word of the "City Noun" name) — punchier for the ticker.</summary>
    private static string Short(string teamName)
    {
        int i = teamName.LastIndexOf(' ');
        return i >= 0 ? teamName.Substring(i + 1) : teamName;
    }
}

using System.Collections.Generic;
using SBR.Engine;

namespace SBR.Sim;

/// <summary>
/// Per-run scratch for a bot. Strategy objects are stateless singletons shared across parallel runs,
/// so anything a bot must remember within one run lives here (created fresh per run by the harness).
/// </summary>
public sealed class BotState
{
    /// <summary>The bot's estimate of P(home wins) per matchup index for the current round. Populated by
    /// the bot at bet time from the info a player could have (de-vigged odds).</summary>
    public readonly Dictionary<int, double> HomeProbEst = new();

    public void NewRound() => HomeProbEst.Clear();
}

/// <summary>The pending-loss window verbs a bot can choose between (charm expansion, PLAN.md
/// rev 5 §13). RunPlayer validates legality (holdings, mulligan's ≥2-active-legs rule) and
/// falls back to Decline when the choice is illegal.</summary>
public enum PendingLossAction { Decline, Mulligan, Whistle }

/// <summary>
/// A pluggable strategy bot (PRD F9). Hooks: <see cref="Bet"/> (betting window), <see cref="ShouldCashOut"/>
/// (per sweat event, only when <see cref="ControlsSweat"/>), <see cref="ChoosePendingLossAction"/>
/// (the save window), and <see cref="Shop"/> (between rounds).
///
/// HONESTY RULE (enforced by convention across all bots): a bot may read only what a player could know —
/// odds, records, the bank/debt/requirement, and revealed drama events (evt.WinProbAfter). A bot must
/// NEVER read Matchup.TrueHomeProb, Leg.TrueProb, or Matchup.Result. Only the harness (Metrics) reads truth.
/// </summary>
public interface IStrategy
{
    string Name { get; }

    /// <summary>When false the harness fast-forwards the sweat (never cashing out) and never calls
    /// <see cref="ShouldCashOut"/>. Naive is the only bot that opts out.</summary>
    bool ControlsSweat { get; }

    /// <summary>Betting window: place 0..MaxTickets tickets via run.PlaceTicket.</summary>
    void Bet(Run run, BotState state, Pcg32 rng);

    /// <summary>
    /// Called once per sweat event on an open, cash-out-eligible ticket when an offer exists.
    /// Return true to take <paramref name="offer"/>. <paramref name="bankNow"/> is the live bank and
    /// <paramref name="target"/> the round's settle requirement (target + any bookie debt);
    /// <paramref name="evt"/>.WinProbAfter is the on-screen live win% of the current leg
    /// (legitimate player information).
    /// </summary>
    bool ShouldCashOut(Run run, Ticket ticket, SweatSession session, DramaEvent evt,
        double offer, double bankNow, double target, BotState state, Pcg32 rng);

    /// <summary>
    /// The pending-loss window (rev 5 §13). Default policy (the documented bot greed): a legal
    /// Mulligan is the certain save — take it; else a held Whistle fires when the captured
    /// pre-kill prob gives at least a coin-flip's worth of rescue; else decline.
    /// </summary>
    PendingLossAction ChoosePendingLossAction(Run run, Ticket ticket, SweatSession session,
        BotState state, Pcg32 rng)
    {
        if (run.OwnsConsumable("mulligan_slip") && session.CanMulliganPendingLoss)
            return PendingLossAction.Mulligan;
        if (run.OwnsConsumable("refs_whistle") && session.PendingLossProbBefore >= 0.35)
            return PendingLossAction.Whistle;
        return PendingLossAction.Decline;
    }

    /// <summary>Shop window: buy relics via run.BuyRelic.</summary>
    void Shop(Run run, BotState state, Pcg32 rng);
}

using System;
using System.Globalization;
using System.Threading;
using SBR.Engine;

namespace SBR.ConsoleGame;

/// <summary>
/// Thin console primitives: ConsoleColor writes that always restore the prior colour, money/odds
/// formatting, the win-prob bar, and the handful of input helpers. No raw ANSI (Windows-safe).
/// Every method that could throw on a redirected stream (Clear, sleeps) degrades quietly so the
/// --auto smoke harness and piped runs never blow up.
/// </summary>
internal static class Ui
{
    private static readonly CultureInfo Inv = CultureInfo.InvariantCulture;

    public static void Write(ConsoleColor c, string s)
    {
        ConsoleColor prev = Console.ForegroundColor;
        Console.ForegroundColor = c;
        Console.Write(s);
        Console.ForegroundColor = prev;
    }

    public static void WriteLine(ConsoleColor c, string s)
    {
        Write(c, s);
        Console.WriteLine();
    }

    public static void Line() => Console.WriteLine();

    public static void Rule() => WriteLine(ConsoleColor.DarkGray, new string('─', 62));

    /// <summary>Whole-dollar money, thousands-separated. Negatives render as "-$X".</summary>
    public static string Money(double v)
    {
        double r = Math.Round(v);
        string body = Math.Abs(r).ToString("#,##0", Inv);
        return (r < 0 ? "-$" : "$") + body;
    }

    /// <summary>Signed whole-dollar delta, e.g. "+$412" / "-$200".</summary>
    public static string Signed(double v)
    {
        double r = Math.Round(v);
        return (r < 0 ? "-$" : "+$") + Math.Abs(r).ToString("#,##0", Inv);
    }

    /// <summary>American odds string with an explicit leading sign (+150 / -145).</summary>
    public static string American(double decimalOdds)
    {
        int a = OddsMath.AmericanFromDecimal(decimalOdds);
        return a >= 0 ? "+" + a.ToString(Inv) : a.ToString(Inv);
    }

    public static int Pct(double p) => (int)Math.Round(p * 100.0);

    /// <summary>A [####----]-style win-prob bar of the given width.</summary>
    public static string Bar(double prob, int width)
    {
        int filled = (int)Math.Round(Math.Clamp(prob, 0.0, 1.0) * width);
        filled = Math.Clamp(filled, 0, width);
        return "[" + new string('#', filled) + new string('-', width - filled) + "]";
    }

    public static void Clear()
    {
        try { Console.Clear(); } catch { /* redirected stream: nothing to clear */ }
    }

    /// <summary>Sleep, unless input is redirected (piped/auto) — then return instantly so nothing blocks.</summary>
    public static void Beat(int ms)
    {
        if (Console.IsInputRedirected) return;
        Thread.Sleep(ms);
    }

    /// <summary>True once stdin hit end-of-file (a piped script ran out of lines). Callers treat it
    /// as "quit" — otherwise a premature-EOF piped session would spin on the command loop forever.</summary>
    public static bool Eof { get; private set; }

    public static string Prompt(string label)
    {
        Write(ConsoleColor.White, label);
        string? s = Console.ReadLine();
        if (s == null)
        {
            Eof = true;
            return "";
        }
        return s.Trim();
    }

    public static void Pause()
    {
        Write(ConsoleColor.DarkGray, "  (enter to continue) ");
        Console.ReadLine();
    }

    public static bool Confirm(string label)
    {
        string s = Prompt(label).ToUpperInvariant();
        return s.StartsWith("Y", StringComparison.Ordinal);
    }

    public static void Title()
    {
        Clear();
        WriteLine(ConsoleColor.Cyan, "╔══════════════════════════════════════════════════════════╗");
        WriteLine(ConsoleColor.Cyan, "║   S B R   —   build it · lock it · sweat it              ║");
        WriteLine(ConsoleColor.Cyan, "╚══════════════════════════════════════════════════════════╝");
        WriteLine(ConsoleColor.DarkGray, "  a sports-betting roguelite prototype · the text era");
        Line();
    }
}

using System;
using System.Collections.Generic;

namespace SBR.Engine;

/// <summary>
/// Pure betting math per design/02. Everything is decimal odds internally;
/// American odds exist only at the display boundary.
/// </summary>
public static class OddsMath
{
    public static double ImpliedProb(double decimalOdds)
    {
        RequireOdds(decimalOdds);
        return 1.0 / decimalOdds;
    }

    public static double FairDecimal(double p)
    {
        RequireProb(p);
        return 1.0 / p;
    }

    public static int AmericanFromDecimal(double decimalOdds)
    {
        RequireOdds(decimalOdds);
        return decimalOdds >= 2.0
            ? (int)Math.Round(100.0 * (decimalOdds - 1.0))
            : -(int)Math.Round(100.0 / (decimalOdds - 1.0));
    }

    public static double DecimalFromAmerican(int american)
    {
        if (american >= 100) return 1.0 + american / 100.0;
        if (american <= -100) return 1.0 + 100.0 / -american;
        throw new ArgumentException($"American odds must be >= +100 or <= -100, got {american}");
    }

    /// <summary>
    /// Prices a two-way market at true probability plus a proportional overround,
    /// so implied probabilities sum to 1 + overround (design/02 vig definition).
    /// </summary>
    public static (double home, double away) OverroundOdds(double trueHomeProb, double overround)
    {
        RequireProb(trueHomeProb);
        if (overround < 0) throw new ArgumentException("overround must be >= 0");
        double qHome = trueHomeProb * (1.0 + overround);
        double qAway = (1.0 - trueHomeProb) * (1.0 + overround);
        return (1.0 / qHome, 1.0 / qAway);
    }

    public static double Ev(double p, double stake, double decimalOdds)
    {
        RequireProb(p);
        RequireOdds(decimalOdds);
        return stake * (p * decimalOdds - 1.0);
    }

    public static double ParlayDecimal(IReadOnlyList<double> legOdds)
    {
        double product = 1.0;
        for (int i = 0; i < legOdds.Count; i++)
        {
            RequireOdds(legOdds[i]);
            product *= legOdds[i];
        }
        return product;
    }

    public static double ParlayProb(IReadOnlyList<double> legProbs)
    {
        double product = 1.0;
        for (int i = 0; i < legProbs.Count; i++)
        {
            RequireProb(legProbs[i]);
            product *= legProbs[i];
        }
        return product;
    }

    /// <summary>The EV haircut the book took at ticket lock: s × (1 − o_offered / o_fair).</summary>
    public static double VigPaid(double stake, double offeredDecimal, double fairDecimal)
    {
        RequireOdds(offeredDecimal);
        RequireOdds(fairDecimal);
        return stake * (1.0 - offeredDecimal / fairDecimal);
    }

    /// <summary>
    /// Fair value of a partially resolved parlay: s × Π(o_resolved) × Π(p_j × o_j remaining).
    /// Anchors: nothing resolved → P(win) × payout; everything resolved → full payout.
    /// </summary>
    public static double CashOutFair(double stake, double resolvedOddsProduct, IReadOnlyList<(double p, double o)> remainingLegs)
    {
        double value = stake * resolvedOddsProduct;
        for (int i = 0; i < remainingLegs.Count; i++)
        {
            RequireProb(remainingLegs[i].p);
            RequireOdds(remainingLegs[i].o);
            value *= remainingLegs[i].p * remainingLegs[i].o;
        }
        return value;
    }

    public static double CashOutOffer(double fairValue, double margin) => fairValue * (1.0 - margin);

    private static void RequireOdds(double o)
    {
        if (o <= 1.0 || double.IsNaN(o) || double.IsInfinity(o))
            throw new ArgumentException($"Decimal odds must be > 1, got {o}");
    }

    private static void RequireProb(double p)
    {
        if (p <= 0.0 || p >= 1.0 || double.IsNaN(p))
            throw new ArgumentException($"Probability must be in (0, 1), got {p}");
    }
}

using System;
using System.Collections.Generic;
using SBR.Engine;

namespace SBR.Sim;

/// <summary>
/// RANDOM — a noise floor between naive and skilled: legal but thoughtless play.
///
/// Policy:
///   • Betting: 1–3 tickets, each 1–4 legs on random distinct matchups and random sides, each staked a
///     random 10–50% of the (shrinking) bank, floored to whole dollars and never below MinStake.
///   • Sweat: steps the sessions and cashes out with 5% probability per event whenever an offer exists.
///   • Shop: half the time, buys one random affordable offer.
///
/// HONESTY: picks sides and matchups at random — it never consults probabilities at all, true or implied.
/// </summary>
public sealed class RandomStrategy : IStrategy
{
    public string Name => "random";
    public bool ControlsSweat => true;

    private const double CashOutChancePerEvent = 0.05;
    private const double ShopBuyChance = 0.5;

    public void Bet(Run run, BotState state, Pcg32 rng)
    {
        int slateCount = run.CurrentSlate.Matchups.Count;
        int tickets = rng.NextInt(1, Math.Min(run.Config.MaxTicketsPerRound, 3) + 1); // 1..3

        for (int t = 0; t < tickets; t++)
        {
            if (run.Bank < run.Config.MinStake) break;

            int maxLegs = Math.Min(4, Math.Min(run.Config.MaxLegs, slateCount));
            int legs = rng.NextInt(1, maxLegs + 1); // 1..4

            var picks = new List<Pick>(legs);
            foreach (int m in DistinctMatchups(rng, slateCount, legs))
                picks.Add(new Pick(m, rng.NextDouble() < 0.5 ? Side.Home : Side.Away));

            double frac = 0.1 + 0.4 * rng.NextDouble(); // 10..50%
            double stake = Math.Max(run.Config.MinStake, Math.Floor(frac * run.Bank));
            if (stake > run.Bank) break;

            run.PlaceTicket(picks, stake);
        }
    }

    public bool ShouldCashOut(Run run, Ticket ticket, SweatSession session, DramaEvent evt,
        double offer, double bankNow, double target, BotState state, Pcg32 rng)
        => rng.NextDouble() < CashOutChancePerEvent;

    public void Shop(Run run, BotState state, Pcg32 rng)
    {
        // Codex r2 #13 fix: affordability is COMPS (the shop currency), never cash — and the
        // random shopper picks legally across BOTH dealt rows within their separate slot limits.
        if (rng.NextDouble() >= ShopBuyChance) return;

        var passives = new List<int>();
        if (run.OwnedRelics.Count < run.Config.RelicSlots)
            for (int i = 0; i < run.ShopOffers.Count; i++)
                if (run.ShopOffers[i].Price <= run.Comps) passives.Add(i);

        var consumables = new List<int>();
        if (run.OwnedConsumables.Count < run.Config.ConsumableSlots)
            for (int i = 0; i < run.ConsumableOffers.Count; i++)
                if (run.ConsumableOffers[i].Price <= run.Comps) consumables.Add(i);

        int total = passives.Count + consumables.Count;
        if (total == 0) return;

        int pick = rng.NextInt(0, total);
        if (pick < passives.Count) run.BuyRelic(passives[pick]);
        else run.BuyConsumable(consumables[pick - passives.Count]);
    }

    // Partial Fisher-Yates: `count` distinct indices from [0, n).
    private static IEnumerable<int> DistinctMatchups(Pcg32 rng, int n, int count)
    {
        var pool = new int[n];
        for (int i = 0; i < n; i++) pool[i] = i;
        for (int i = 0; i < count; i++)
        {
            int j = rng.NextInt(i, n);
            (pool[i], pool[j]) = (pool[j], pool[i]);
            yield return pool[i];
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using SBR.Engine;

namespace SBR.ConsoleGame;

internal enum BetAction { Locked, Quit }

/// <summary>
/// The Phase.Betting screen and its single-letter command loop. Renders the header (bank, target,
/// any bookie debt), relics, the slate, and tickets placed so far, then dispatches B / L / Q. Every
/// engine call is wrapped so a bad input prints the message and returns to the loop — the shell
/// never crashes.
/// </summary>
internal static class BettingScreen
{
    public static BetAction Run(Run run)
    {
        while (true)
        {
            Render(run);
            string cmd = Ui.Prompt(CommandBar()).ToUpperInvariant();
            if (Ui.Eof) return BetAction.Quit;
            switch (cmd)
            {
                case "B":
                    Build(run);
                    break;

                case "K":
                    try
                    {
                        run.PlayBookiesMarker();
                        Ui.WriteLine(ConsoleColor.Cyan,
                            $"MARKER PLAYED — this round's payment drops to {Ui.Money(run.CurrentPayment)}.");
                    }
                    catch (Exception ex) { Ui.WriteLine(ConsoleColor.Red, ex.Message); }
                    Ui.Pause();
                    break;

                case "L":
                    if (run.Tickets.Count == 0 && !Ui.Confirm("no bets this round? the payment still comes due — y/n: ")) break;
                    run.LockRound();
                    return BetAction.Locked;

                case "Q":
                    if (Ui.Confirm("quit the run? y/n: ")) return BetAction.Quit;
                    break;

                default:
                    Unknown();
                    break;
            }
        }
    }

    private static void Unknown()
    {
        Ui.WriteLine(ConsoleColor.Red, "Unknown command.");
        Ui.Pause();
    }

    private static string CommandBar()
        => "commands: [B]uild ticket  [K] marker  [L]ock round  [Q]uit  > ";

    // ---- rendering ----

    private static void Render(Run run)
    {
        Ui.Clear();
        Ui.WriteLine(ConsoleColor.Cyan,
            $"ROUND {run.Round}/{run.Config.Rounds}  ·  BANK {Ui.Money(run.Bank)}  ·  PAYMENT DUE {Ui.Money(run.CurrentPayment)}"
            + $"  ·  COMPS {run.Comps:0.#}  ·  SEED {run.Rng.RunSeed}");
        Ui.WriteLine(ConsoleColor.DarkGray,
            $"tickets {run.Tickets.Count}/{run.Config.MaxTicketsPerRound}  ·  relics {run.OwnedRelics.Count}/{run.Config.RelicSlots}"
            + $"  ·  consumables {run.OwnedConsumables.Count}/{run.Config.ConsumableSlots}"
            + $"  ·  staking earns comps ({run.Config.CompsPerDollarStaked:0.##}/$)");

        // The whole ledger is public information (design/10) — show what is coming.
        var schedule = new List<string>();
        for (int r = run.Round - 1; r < run.PaymentSchedule.Count; r++)
            schedule.Add(Ui.Money(run.PaymentSchedule[r]));
        Ui.WriteLine(ConsoleColor.DarkGray, "SCHEDULE: " + string.Join(" → ", schedule));

        if (run.ScarStacks > 0)
            Ui.WriteLine(ConsoleColor.Magenta,
                $"SCAR {run.ScarStacks:0.#}pp — your FIRST ticket this round carries it (burns on a hit)");
        GameLoop.WriteEffectStates(run); // chalk/iron/jar/system stacks (rev 5 §20)

        if (run.OwnedRelics.Count > 0)
        {
            var names = new List<string>();
            foreach (RelicDefinition r in run.OwnedRelics) names.Add(r.Name);
            Ui.WriteLine(ConsoleColor.Cyan, "RELICS: " + string.Join(", ", names));
        }

        if (run.OwnedConsumables.Count > 0)
        {
            var names = new List<string>();
            foreach (ConsumableDefinition c in run.OwnedConsumables) names.Add(c.Name);
            Ui.WriteLine(ConsoleColor.Cyan, "CONSUMABLES: " + string.Join(", ", names));
        }

        Ui.Rule();
        RenderSlate(run);

        if (run.Tickets.Count > 0)
        {
            Ui.Line();
            Ui.WriteLine(ConsoleColor.White, "TICKETS");
            for (int i = 0; i < run.Tickets.Count; i++)
                Ui.WriteLine(ConsoleColor.Gray, $" {i + 1}. {DescribeLegs(run.Tickets[i])}  |  {Ui.Money(run.Tickets[i].Stake)} → {Ui.Money(run.Tickets[i].PotentialPayout)}");
        }

        Ui.Line();
    }

    private static void RenderSlate(Run run)
    {
        Ui.WriteLine(ConsoleColor.White, "SLATE  (away @ home · moneyline)");

        foreach (Matchup m in run.CurrentSlate.Matchups)
        {
            string away = $"{m.Away.Name} ({m.Away.Record})";
            string home = $"{m.Home.Name} ({m.Home.Record})";
            string line = $" {m.Index + 1}. {away.PadRight(28)} {Ui.American(m.AwayOdds),5}   @   {home.PadRight(28)} {Ui.American(m.HomeOdds),5}";
            Ui.WriteLine(ConsoleColor.Gray, line);
        }
    }

    private static string DescribeLegs(Ticket t)
    {
        var parts = new List<string>();
        foreach (Leg leg in t.Legs)
        {
            string team = Short(leg.Side == Side.Home ? leg.Matchup.Home.Name : leg.Matchup.Away.Name);
            string mark = Math.Abs(leg.OfferedOdds - leg.BaseOdds) > 1e-9 ? " ^boosted" : "";
            parts.Add($"{team} {Ui.American(leg.OfferedOdds)}{mark}");
        }
        return string.Join(", ", parts);
    }

    // ---- B: build a ticket ----

    private static void Build(Run run)
    {
        string picksLine = Ui.Prompt("picks> (e.g. 1H 3A 5H)  ");
        List<Pick> picks;
        try
        {
            picks = ParsePicks(picksLine, run.CurrentSlate.Matchups.Count);
        }
        catch (Exception ex)
        {
            Ui.WriteLine(ConsoleColor.Red, ex.Message);
            Ui.Pause();
            return;
        }

        if (picks.Count == 0)
        {
            Ui.WriteLine(ConsoleColor.Red, "No picks entered.");
            Ui.Pause();
            return;
        }

        string stakeLine = Ui.Prompt("stake> ");
        if (!double.TryParse(stakeLine, NumberStyles.Any, CultureInfo.InvariantCulture, out double stake))
        {
            Ui.WriteLine(ConsoleColor.Red, "Stake must be a number.");
            Ui.Pause();
            return;
        }

        // A held Profit Boost is played at the betslip (design/10 D): pick the leg it lands on.
        int boostLeg = -1;
        if (run.OwnsConsumable("profit_boost") && picks.Count > 0)
        {
            string b = Ui.Prompt($"PROFIT BOOST held — boost which leg? (1-{picks.Count}, enter to skip) ");
            if (int.TryParse(b, NumberStyles.Integer, CultureInfo.InvariantCulture, out int bl)
                && bl >= 1 && bl <= picks.Count)
            {
                boostLeg = bl - 1;
            }
        }

        // Locked contract modifiers (one per ticket — the one-modifier law).
        TicketModifier modifier = TicketModifier.None;
        bool hasFree = run.OwnsConsumable("free_bet");
        bool hasDon = run.OwnsConsumable("double_or_nothing");
        if (hasFree || hasDon)
        {
            string opts = hasFree && hasDon ? "[F]ree bet / [D]ouble-or-nothing"
                : hasFree ? "[F]ree bet" : "[D]ouble-or-nothing";
            string m = Ui.Prompt($"modifier? {opts} (enter to skip) ").ToUpperInvariant();
            if (m == "F" && hasFree) modifier = TicketModifier.FreeBet;
            else if (m == "D" && hasDon) modifier = TicketModifier.DoubleOrNothing;
        }

        try
        {
            Ticket t = run.PlaceTicket(picks, stake, boostLeg, modifier);
            string tag = t.Modifier == TicketModifier.FreeBet ? "  [FREE BET]"
                : t.Modifier == TicketModifier.DoubleOrNothing ? "  [DOUBLE OR NOTHING — no cash-out]" : "";
            Ui.WriteLine(ConsoleColor.Green,
                $"TICKET PLACED: {DescribeLegs(t)}  |  {Ui.Money(t.Stake)} → {Ui.Money(t.PotentialPayout)}{tag}");
        }
        catch (Exception ex)
        {
            Ui.WriteLine(ConsoleColor.Red, ex.Message); // engine validation, verbatim
        }

        Ui.Pause();
    }

    // ---- parsing ----

    private static List<Pick> ParsePicks(string line, int matchupCount)
    {
        var picks = new List<Pick>();
        foreach (string tok in line.Split(new[] { ' ', ',' }, StringSplitOptions.RemoveEmptyEntries))
        {
            (int idx, Side side) = ParseOne(tok, matchupCount);
            picks.Add(new Pick(idx, side));
        }
        return picks;
    }

    private static (int idx, Side side) ParseOne(string token, int matchupCount)
    {
        token = token.Trim();
        if (token.Length < 2)
            throw new ArgumentException($"Bad pick '{token}' — use a number then H or A, e.g. 1H.");

        char sc = char.ToUpperInvariant(token[token.Length - 1]);
        Side side = sc == 'H' ? Side.Home
                  : sc == 'A' ? Side.Away
                  : throw new ArgumentException($"Bad side in '{token}' — end with H (home) or A (away).");

        string num = token.Substring(0, token.Length - 1);
        if (!int.TryParse(num, NumberStyles.Integer, CultureInfo.InvariantCulture, out int n))
            throw new ArgumentException($"Bad matchup number in '{token}'.");

        int idx = n - 1;
        if (idx < 0 || idx >= matchupCount)
            throw new ArgumentException($"Matchup {n} is off the slate (pick 1–{matchupCount}).");

        return (idx, side);
    }

    // ---- helpers ----

    private static string Short(string teamName)
    {
        int i = teamName.LastIndexOf(' ');
        return i >= 0 ? teamName.Substring(i + 1) : teamName;
    }
}

using System;
using System.Collections.Generic;
using SBR.Engine;

namespace SBR.Sim;

/// <summary>
/// SKILLED — the G3 measuring stick (economy rework: median death ≥7, win 10–15% with items).
/// Estimates like a sharp, then sizes and times like one.
///
/// Estimation (p̂ per side): pure two-way de-vig of the offered odds — NORMALIZE the implied probs.
/// Because v0's book prices proportionally, this recovers true p exactly (noted for the record; the
/// information axis returns in v2 with pricing noise).
///
/// Betting (payment model): the settle DEDUCTS CurrentPayment, so the sharp plans to hold
/// bank ≥ payment at settle — sizing escalates when the payment is out of reach. A held Profit
/// Boost is played on the primary ticket's longest-odds leg (the biggest absolute odds gain).
///
/// Shop: passives in priority order (Multiplier → Scar → Totem: the static engine compounds all
/// run, the ratchet earns from variance, the totem is bought when affordable insurance), then a
/// Mulligan Slip / Profit Boost while a consumable slot is free — all only above a working-capital
/// floor of the NEXT payment.
///
/// HONESTY: reads only public state — odds, bank/payment, offers, revealed WinProbAfter, own items.
/// Never Matchup.TrueHomeProb / Leg.TrueProb / Matchup.Result.
/// </summary>
public class SkilledStrategy : IStrategy
{
    // ---- dials ----
    private const double StakeMin = 0.10;          // engine-bet floor (fraction of spare capital)
    private const double EngineStakeCap = 0.50;    // engine-bet cap (fraction of spare capital)
    private const double ClearBuffer = 1.08;       // survival aims ~8% past the payment
    private const double CashOutEvRatio = 0.95;    // accept a cash-out at ≥95% of estimated hold value
    private const double ShopHeadroomFloor = 1.00; // keep the NEXT payment intact when buying
    private const int MaxPrimaryLegs = 3;

    // Passive buy priority (highest first) over the FULL 15-passive catalog (rev 5 §13); the
    // dealt hand means the bot buys the best of what it is shown, tier-ranked. Bobblehead is
    // deliberately absent — it is handled by the flip rule (buy 2, sell 6: free money whenever
    // dealt), never held. Archetype bots override this list.
    private static readonly string[] DefaultRelicPriority =
    {
        RelicCatalog.MultiplierId, "longshot_photo", RelicCatalog.TotemId, "the_system",
        "chalk_eater", RelicCatalog.ScarTissueId, "whale_card", "bad_beat_jar",
        "iron_hands", "compd_suite", "rakes_rebate", "house_key",
        "golden_parachute", "the_collection",
    };

    private static readonly string[] ConsumablePriority =
        { "mulligan_slip", "refs_whistle", "free_bet", "profit_boost", "bookies_marker",
          "double_or_nothing", "ask_manager" };

    /// <summary>The tier list (archetype bots override).</summary>
    protected virtual string[] RelicPriorityList => DefaultRelicPriority;

    /// <summary>Comps the bot refuses to spend below (the Whale/Rebate hoard tension).</summary>
    protected virtual double CompsHoldFloor(Run run)
        => OwnsRelic(run, "whale_card") ? 20.0 : 0.0;

    /// <summary>Max parlay legs: a 4th leg when Comp'd Suite makes leg count pay.</summary>
    protected virtual int PrimaryLegCap(Run run)
        => OwnsRelic(run, "compd_suite") ? 4 : MaxPrimaryLegs;

    /// <summary>Which locked contract modifier to attach to the primary ticket (one per ticket —
    /// the one-modifier law). DoN doubles the committed engine parlay (p̂ ≥ 0.30 — a 3-leg
    /// favorites plan sits ~0.34); Free Bet insures everything else.</summary>
    protected virtual TicketModifier PickModifier(Run run, double planWinProb)
    {
        if (run.OwnsConsumable("double_or_nothing") && planWinProb >= 0.30)
            return TicketModifier.DoubleOrNothing;
        if (run.OwnsConsumable("free_bet")) return TicketModifier.FreeBet;
        return TicketModifier.None;
    }

    /// <summary>The bot's engine test, dealt-hand aware (the tuning campaign's first finding):
    /// ANY owned product source is an engine — waiting for The Multiplier specifically starves
    /// the build 4 shops out of 5.</summary>
    protected static bool OwnsAnyEngine(Run run)
    {
        foreach (RelicDefinition d in run.OwnedRelics)
        {
            switch (d.Id)
            {
                case "the_multiplier":
                case "longshot_photo":
                case "the_system":
                case "chalk_eater":
                case "bad_beat_jar":
                case "iron_hands":
                case "whale_card":
                case "the_collection":
                case "house_key":
                    return true;
            }
        }
        return false;
    }

    protected static bool OwnsRelic(Run run, string id)
    {
        foreach (RelicDefinition d in run.OwnedRelics)
            if (d.Id == id) return true;
        return false;
    }

    private readonly bool _shops;

    public SkilledStrategy() : this(shops: true) { }
    protected SkilledStrategy(bool shops) => _shops = shops;

    /// <summary>True in the G5 measurement variant: stake policy ignores item ownership.</summary>
    protected virtual bool FixedDiscipline => false;

    public virtual string Name => "skilled";
    public bool ControlsSweat => true;

    private readonly struct Cand
    {
        public readonly int Matchup;
        public readonly Side Side;
        public readonly double PHat;
        public readonly double Odds;
        public Cand(int matchup, Side side, double pHat, double odds)
        {
            Matchup = matchup; Side = side; PHat = pHat; Odds = odds;
        }
    }

    public void Bet(Run run, BotState state, Pcg32 rng)
    {
        IReadOnlyList<Matchup> slate = run.CurrentSlate.Matchups;

        foreach (Matchup m in slate)
            state.HomeProbEst[m.Index] = DevigHome(m);

        var cands = new List<Cand>(slate.Count);
        foreach (Matchup m in slate)
        {
            double pHome = state.HomeProbEst[m.Index];
            Side side = pHome >= 0.5 ? Side.Home : Side.Away;
            double pHat = side == Side.Home ? pHome : 1.0 - pHome;
            cands.Add(new Cand(m.Index, side, pHat, m.Odds(side)));
        }
        cands.Sort((a, b) => b.PHat.CompareTo(a.PHat)); // highest-confidence first

        if (run.Bank < run.Config.MinStake || cands.Count < 2) return;

        PlacePrimary(run, cands);
    }

    private void PlacePrimary(Run run, List<Cand> cands)
    {
        // The payment-model sharp (rework insight, first grid run): max-win-prob singles just
        // bleed vig while the payments drain the bank — wins come from the RIGHT TAIL. So:
        //  • SURVIVAL mode (this round's payment already out of reach at rest): escalate — the
        //    plan clearing the payment with the highest win probability, all-in if demanded.
        //  • ENGINE mode (payment covered): reserve the payment, and put the spare capital on the
        //    top-favorites 3-leg parlay — with The Multiplier owned it is strongly +EV, and one
        //    hit covers payments for rounds. Sized toward denting the REMAINING schedule, capped.
        double bank = run.Bank;
        double payment = run.CurrentPayment;

        if (bank < payment * ClearBuffer)
        {
            // Survival: existing escalation logic against the payment itself. A held Free Bet
            // insures the rescue ticket — the exact spot the refund is worth the most.
            double aimMult = payment * ClearBuffer / bank;
            var rescue = ChooseTicket(cands, aimMult, run.Config.MaxStakeFraction);
            if (rescue is not { } r) return;
            double rf = Math.Clamp(ReqFrac(aimMult, r.Odds), StakeMin, run.Config.MaxStakeFraction);
            double rs = Math.Clamp(Math.Floor(rf * bank), run.Config.MinStake, bank);
            if (rs < run.Config.MinStake) return;
            TicketModifier rescueMod = run.OwnsConsumable("free_bet")
                ? TicketModifier.FreeBet : TicketModifier.None;
            run.PlaceTicket(r.Picks, rs, BoostLeg(run, r.Picks), rescueMod);
            return;
        }

        // Engine mode. (Campaign note: reserving toward the NEXT payment too was tried and
        // BACKFIRED — won 7.0% → 4.0%. In an income race, under-betting starves the engine;
        // the game punishes timidity. Reserve today's payment only.)
        double spare = bank - payment;
        if (spare < run.Config.MinStake) return;

        int legs = Math.Min(PrimaryLegCap(run), cands.Count);
        double odds = 1.0, win = 1.0;
        var picks = new List<Pick>(legs);
        for (int i = 0; i < legs; i++)
        {
            odds *= cands[i].Odds;
            win *= cands[i].PHat;
            picks.Add(new Pick(cands[i].Matchup, cands[i].Side));
        }

        // Size toward denting what's left of the schedule: a hit should cover ~half the remaining
        // payments, within [Kelly-lite floor, EngineStakeCap × spare].
        double remaining = 0;
        for (int r2 = run.Round - 1; r2 < run.PaymentSchedule.Count; r2++)
            remaining += run.PaymentSchedule[r2];
        // Pre-engine, the comps era (design/10 F): the bank is ~2–3 payments, so income is
        // mandatory NOW — size the parlay so a hit funds this payment plus a seed of the next
        // (quota sizing), which also pumps comp volume toward the engine. Post-engine, size
        // toward denting the remaining schedule.
        bool engined = OwnsAnyEngine(run) && picks.Count >= 3;
        double stake;
        if (FixedDiscipline)
        {
            // The G5 measurement bot (Allen-approved fix): stakes 25% of spare REGARDLESS of item
            // ownership, so pair-vs-solo deltas measure composition, not ownership-induced
            // aggression (round 1's confound: the engine tempts bigger bets and earlier deaths).
            stake = Math.Clamp(Math.Floor(0.25 * spare), run.Config.MinStake, Math.Floor(spare));
            if (stake < run.Config.MinStake) return;
        }
        else if (!engined)
        {
            double quota = payment + 0.5 * (run.NextPayment ?? 0.0);
            double quotaStake = odds > 1.0 ? quota * ClearBuffer / odds : run.Config.MinStake;
            stake = Math.Clamp(Math.Floor(quotaStake), run.Config.MinStake, Math.Floor(spare));
            if (stake < run.Config.MinStake) return;
        }
        else
        {
            double targetPayout = 0.5 * remaining;
            double stakeForDent = targetPayout / (odds * 1.5);
            double cap = Math.Floor(EngineStakeCap * spare);
            if (cap < run.Config.MinStake) return; // spare too thin for an engine bet this round
            stake = Math.Clamp(Math.Floor(Math.Max(StakeMin * spare, stakeForDent)),
                run.Config.MinStake, cap);
        }

        run.PlaceTicket(picks, stake, BoostLeg(run, picks), PickModifier(run, win));
    }

    /// <summary>A held Profit Boost lands on the longest-odds leg — the largest absolute gain.</summary>
    private static int BoostLeg(Run run, List<Pick> picks)
    {
        if (!run.OwnsConsumable("profit_boost")) return -1;
        int boostLeg = -1;
        double bestOdds = -1.0;
        for (int i = 0; i < picks.Count; i++)
        {
            Matchup m = run.CurrentSlate.Matchups[picks[i].MatchupIndex];
            double o = m.Odds(picks[i].Side);
            if (o > bestOdds) { bestOdds = o; boostLeg = i; }
        }
        return boostLeg;
    }

