        int legSeen = -1;
        bool fastForward = false;

        while (session.MoveNext(out DramaEvent? e))
        {
            DramaEvent evt = e!;
            Leg leg = ticket.Legs[evt.LegIndex];
            if (evt.LegIndex != legSeen)
            {
