                            Ui.WriteLine(ConsoleColor.Green, "  REVIEWED — OVERTURNED. The leg STANDS at full odds.");
                            continue;
                        }
                        Ui.WriteLine(ConsoleColor.Red, "  REVIEWED — the call is CONFIRMED. Dead.");
                        break;

                    default:
                        session.DeclinePendingLoss();
                        break;
                }
