using System.Collections.Generic;
using SBR.Engine;

namespace SBR.Engine.Tests;

/// <summary>
/// The Week 2 determinism pin. Seed GOLDEN-W2, a scripted 2-ticket round (a 3-leg parlay that
/// wins its first leg then dies on its second, plus a winning single — the single keeps the
/// settlement pin sensitive to payout crediting, not just stake deduction). The full event
/// stream, the total count, and settlement are hard-coded below. An UNINTENTIONAL change here is
/// a determinism regression — investigate before re-pinning.
/// </summary>
public class GoldenSeedTests
{
    private const string Seed = "GOLDEN-W2";

    private static Run ScriptedRound()
    {
        // The Week-2 pin was taken at bank 500; the pin stays valid by pinning the config too
        // (outcomes/drama are bank-independent, but the settled-bank assertion is not).
        var run = new Run(Seed, new RunConfig { StartingBank = 500 });
        // F_0.4.0 universe: parlay (0,Away) win, (2,Away) DIES, (3,Home) never sweated.  Single: (1,Away) win.
        run.PlaceTicket(new[] { new Pick(0, Side.Away), new Pick(2, Side.Away), new Pick(3, Side.Home) }, 100);
        run.PlaceTicket(new[] { new Pick(1, Side.Away) }, 50);
        run.LockRound();
        return run;
    }

    private static List<DramaEvent> DrainAll(Run run)
    {
        var all = new List<DramaEvent>();
        foreach (SweatSession s in run.Sweats)
            while (s.MoveNext(out var e))
                all.Add(e);
        return all;
    }

    // (LegIndex, Step, Type, Tag) for every event, in fast-forward order. Re-pinned once for
    // F_0.4.0 Phase 1: the stat-line sampler changes the locked market universe intentionally.
    private static readonly (int leg, int step, DramaEventType type, TensionTag tag)[] Expected =
    {
        (0, 1, DramaEventType.BigPlay,  TensionTag.Swing),
        (0, 2, DramaEventType.LegFinal, TensionTag.Decisive),
        (1, 1, DramaEventType.Score, TensionTag.Swing),
        (1, 2, DramaEventType.BigPlay, TensionTag.Swing),
        (1, 3, DramaEventType.Score, TensionTag.Swing),
        (1, 4, DramaEventType.LegFinal, TensionTag.Decisive),
        (0, 1, DramaEventType.Momentum, TensionTag.LeadChange),
        (0, 2, DramaEventType.Momentum, TensionTag.LeadChange),
        (0, 3, DramaEventType.Momentum, TensionTag.Calm),
        (0, 4, DramaEventType.Score,    TensionTag.LeadChange),
        (0, 5, DramaEventType.Momentum, TensionTag.Calm),
        (0, 6, DramaEventType.Score,    TensionTag.Swing),
        (0, 7, DramaEventType.Score,    TensionTag.Swing),
        (0, 8, DramaEventType.LegFinal, TensionTag.Decisive),
    };

    // WinProbAfter (6 dp) for the first ten events.
    private static readonly double[] ExpectedFirstTenWinProb =
    {
        0.803542, 1.000000, 0.363411, 0.144328, 0.030000,
        0.000000, 0.523784, 0.484132, 0.493316, 0.636125,
    };

    [Fact]
    public void Golden_seed_event_stream_is_pinned()
    {
        Run run = ScriptedRound();
        List<DramaEvent> events = DrainAll(run);

        Assert.Equal(14, events.Count);
        Assert.Equal(Expected.Length, events.Count);

        for (int i = 0; i < events.Count; i++)
        {
            DramaEvent e = events[i];
            Assert.Equal(Expected[i].leg, e.LegIndex);
            Assert.Equal(Expected[i].step, e.Step);
            Assert.Equal(Expected[i].type, e.Type);
            Assert.Equal(Expected[i].tag, e.Tag);
        }

        for (int i = 0; i < ExpectedFirstTenWinProb.Length; i++)
            Assert.Equal(ExpectedFirstTenWinProb[i], events[i].WinProbAfter, 6);
    }

    [Fact]
    public void Golden_seed_settles_to_pinned_bank_and_phase()
    {
        Run run = ScriptedRound();
        DrainAll(run);
        run.FinishSweat();

        Assert.Equal(Phase.Settlement, run.Phase);
        Assert.Equal(TicketState.Lost, run.Tickets[0].State); // parlay died on its second leg
        Assert.Equal(TicketState.Won, run.Tickets[1].State);  // single hit — payout crediting stays pinned
        Assert.Equal(452.559054816409, run.Bank, 5);
    }

    [Fact]
    public void Golden_seed_replays_identically()
    {
        List<DramaEvent> a = DrainAll(ScriptedRound());
        List<DramaEvent> b = DrainAll(ScriptedRound());

        Assert.Equal(a.Count, b.Count);
        for (int i = 0; i < a.Count; i++)
        {
            Assert.Equal(a[i].LegIndex, b[i].LegIndex);
            Assert.Equal(a[i].Step, b[i].Step);
            Assert.Equal(a[i].Type, b[i].Type);
            Assert.Equal(a[i].Tag, b[i].Tag);
            Assert.Equal(a[i].WinProbAfter, b[i].WinProbAfter, 15);
        }
    }
}

using System;
using System.Collections.Generic;
using SBR.Engine;

namespace SBR.Game
{
    /// <summary>
    /// Pure-C# model behind the match theater (F_0.2.0). No UnityEngine — EditMode-testable.
    /// Owns what every theater surface must AGREE on: deterministic team colors from a
    /// non-reserved pool (design/08 palette law: green/red/gold are money signals, cyan is
    /// VOID — never team identity), the beat direction rule (EventText's law: sign of the
    /// win-prob move for the picked side, first beat against the leg's TrueProb anchor),
    /// and the beat history the stage/tape/scorebug all read. Consumes no engine RNG.
    /// </summary>
    public sealed class SweatPresentationModel
    {
        /// <summary>One recorded beat, presentation-local.</summary>
        public readonly struct BeatRecord
        {
            public readonly int LegIndex;
            public readonly int Step;
            public readonly DramaEventType Type;
            public readonly TensionTag Tag;
            /// <summary>True when the beat moved the PICKED side's win probability up (ties count up).</summary>
            public readonly bool Up;
            /// <summary>Signed win-probability movement from the previous beat (or TrueProb for the first).</summary>
            public readonly double Delta;
            public readonly double ProbAfter;

            public BeatRecord(int legIndex, int step, DramaEventType type, TensionTag tag, bool up,
                double delta, double probAfter)
            {
                LegIndex = legIndex;
                Step = step;
                Type = type;
                Tag = tag;
                Up = up;
                Delta = delta;
                ProbAfter = probAfter;
            }

            public BeatRecord(int legIndex, int step, DramaEventType type, TensionTag tag, bool up,
                double probAfter)
                : this(legIndex, step, type, tag, up, 0.0, probAfter) { }
        }

        private readonly List<BeatRecord> _beats = new List<BeatRecord>();
        private int _anchorLeg = -1;
        private double _prevProb;

        public IReadOnlyList<BeatRecord> Beats => _beats;

        /// <summary>Records a beat and returns its direction (the shared rule — one authority).</summary>
        public bool RecordBeat(DramaEvent evt, Leg leg)
        {
            if (evt.LegIndex != _anchorLeg)
            {
                _anchorLeg = evt.LegIndex;
                _prevProb = leg.TrueProb; // the pre-event anchor, exactly EventText's rule
            }
            double delta = evt.WinProbAfter - _prevProb;
            bool up = delta >= 0.0;
            _prevProb = evt.WinProbAfter;
            _beats.Add(new BeatRecord(evt.LegIndex, evt.Step, evt.Type, evt.Tag, up, delta, evt.WinProbAfter));
            return up;
        }

        /// <summary>Maps a beat's absolute probability movement to the tape's dot size band.</summary>
        public static int MagnitudeBand(double delta)
        {
            double magnitude = Math.Abs(delta);
            if (magnitude < 0.04) return 0;
            if (magnitude < 0.10) return 1;
            return 2;
        }

        /// <summary>New ticket — beat history and the direction anchor reset.</summary>
        public void ResetForTicket()
        {
            _beats.Clear();
            _anchorLeg = -1;
            _prevProb = 0.0;
        }
    }

    /// <summary>
    /// The synthesized score ledger (F_0.2.0 M-T3) — causal + honest. Pure C#, EditMode-testable.
    ///
    /// Laws (the plan's §Score ledger, verbatim intent):
    ///  - Attribution: a Score/BigPlay beat up ⇒ picked-team goal, down ⇒ opponent goal;
    ///    Momentum/NearMiss ⇒ no goal.
    ///  - Live-lead clamp (<see cref="MaxLiveLead"/> = ±1, a dial): a goal that would push the
    ///    live lead beyond the clamp stages as the CHALKED-OFF variant — full drama, VAR
    ///    disallow, no increment. Deliberate drama law: the theater tells one-goal-game
    ///    stories, blowout scorelines never sweat.
    ///  - Commit timing: a goal commits when its playback COMPLETES (<see cref="CompleteGoal"/>
    ///    is the only score mutator), never on MoveNext — a suspended scene has committed nothing.
    ///  - Finals (<see cref="PlanFinal"/>): the scoreline entering any LegFinal is within ±1
    ///    (clamp consequence), so a correction needs at most 2 staged goals. Won ⇒ stoppage-time
    ///    goal(s) until the picked team is strictly ahead. Lost ⇒ the killing shot commits only
    ///    if the opponent is not already strictly ahead (already −1 ⇒ chalked at the death),
    ///    then correction goal(s) until the opponent is strictly ahead. Voided ⇒ the ledger
    ///    freezes as-is under the VOID treatment — no goals, no corrections.
    ///  - Goal-playback invariant: every increment maps 1:1 to a completed staged goal.
    /// </summary>
    public sealed class ScoreLedger
    {
        /// <summary>The live-lead clamp dial (±goals). 1 = one-goal-game stories.</summary>
        public int MaxLiveLead { get; set; } = 1;

        /// <summary>Committed goals for the picked side, this leg.</summary>
        public int Picked { get; private set; }

        /// <summary>Committed goals for the opponent, this leg.</summary>
        public int Opponent { get; private set; }

        /// <summary>Total committed goal playbacks this leg (the invariant's counter).</summary>
        public int CommittedGoals { get; private set; }

        /// <summary>A goal the choreographer staged: who it's for, and whether it commits
        /// (false = the chalked-off VAR-disallow variant — plays in full, never scores).</summary>
        public readonly struct StagedGoal
        {
            public readonly bool ForPicked;
            public readonly bool Commits;

            public StagedGoal(bool forPicked, bool commits)
            {
                ForPicked = forPicked;
                Commits = commits;
            }
        }

        /// <summary>The final whistle's staging order: the goals scene #12/#13 must play
        /// (killing shot first on a Lost, then corrections), each completed via
        /// <see cref="CompleteGoal"/> as its sub-scene finishes.</summary>
        public readonly struct FinalPlan
        {
            public readonly LegGrade Grade;
            public readonly StagedGoal[] Goals;

            public FinalPlan(LegGrade grade, StagedGoal[] goals)
            {
                Grade = grade;
                Goals = goals;
            }
        }

        /// <summary>Above this live prob the scoreboard must show the picked side ahead —
        /// the score is a lagging quantized rendering of the probability (playtest #14).</summary>
        public double ReconcileHighBand { get; set; } = 0.70;

        /// <summary>Below this live prob the scoreboard must show the opponent ahead.</summary>
        public double ReconcileLowBand { get; set; } = 0.30;

        /// <summary>Attribution + clamp for a non-final beat. Null = this beat stages no goal.
        ///
        /// Two goal sources (playtest #14 amendment — "the bar and the board must agree"):
        ///  1. Type attribution (the original law): Score/BigPlay beats stage a goal for the
        ///     beat's beneficiary.
        ///  2. Prob reconciliation: when the live probability says one side should be AHEAD
        ///     (outside the reconcile bands) and the board disagrees, a beat moving in that
        ///     direction stages the reconciling goal regardless of its type — the mid-leg
        ///     generalization of the final whistle's stoppage-time correction. Without this,
        ///     the board can read 0-0 at 90% or "leading" at 25%, which plays as fake.
        ///
        /// Near-miss exemption and the live-lead clamp are enforced by the caller/clamp as
        /// before; reconciliation targets ±1 so it can never violate the clamp.</summary>
        public StagedGoal? StageBeatGoal(DramaEventType type, bool up, double delta, double probAfter)
        {
            bool typeGoal = type == DramaEventType.Score || type == DramaEventType.BigPlay;
            if (typeGoal)
            {
                // Type goals keep the original direction rule (ties up — EventText's law);
                // their |delta| ≥ 0.07 means they are never actually flat.
                int typeLeadAfter = up ? Picked + 1 - Opponent : Opponent + 1 - Picked;
                return new StagedGoal(forPicked: up, commits: typeLeadAfter <= MaxLiveLead);
            }

            // The board the probability implies: +1 (picked ahead), -1 (opponent ahead), or
            // 0 (mid-band — any scoreline within the clamp is a fine story, including 1-0
            // either way; reconciliation never drags a natural lead back to level).
            //
            // Direction gate (Sol, M-T4.1): SIGN-COMPATIBILITY, not the tie-broken bool. A
            // flat beat (delta 0 — real inputs: paths riding the generator's 0.03/0.97
            // clamp) supports EITHER side's band; contrary motion never reconciles. Strict
            // inequality would leave a ceiling-riding 97% path unreconciled forever — the
            // exact dissonance this amendment exists to kill. The staged goal's direction
            // comes from the BAND, never from the tie-break.
            int impliedLead = probAfter >= ReconcileHighBand ? 1
                : probAfter <= ReconcileLowBand ? -1 : 0;
            int lead = Picked - Opponent;
            bool reconcileUp = impliedLead > 0 && lead < impliedLead && delta >= 0.0;
            bool reconcileDown = impliedLead < 0 && lead > impliedLead && delta <= 0.0;
            if (!reconcileUp && !reconcileDown) return null;

            bool forPicked = reconcileUp;
            int leadAfter = forPicked ? Picked + 1 - Opponent : Opponent + 1 - Picked;
            return new StagedGoal(forPicked, commits: leadAfter <= MaxLiveLead);
        }

        /// <summary>The ONLY score mutator — called when a staged goal's playback completes.
        /// A chalked-off goal (Commits false) completes without moving anything.</summary>
        public void CompleteGoal(StagedGoal goal)
        {
            if (!goal.Commits) return;
            if (goal.ForPicked) Picked++;
            else Opponent++;
            CommittedGoals++;
        }

        /// <summary>The stoppage-time staging order for a LegFinal, from the FINAL ticket-local
        /// grade (single presentation authority — a suspended scene's ending is never chosen
        /// from WinProbAfter). Pure planning: nothing commits until playback completes.</summary>
        public FinalPlan PlanFinal(LegGrade grade)
        {
            var goals = new System.Collections.Generic.List<StagedGoal>(3);
            int p = Picked, o = Opponent;
            switch (grade)
            {
                case LegGrade.Won:
                    while (p <= o) { goals.Add(new StagedGoal(true, true)); p++; }
                    break;
                case LegGrade.Lost:
                    // The killing shot commits only if the opponent is not already strictly
                    // ahead; otherwise it stages chalked-off — disallowed at the death, the
                    // whistle still confirms Lost. MaxLiveLead is never violated.
                    bool killingCommits = o <= p;
                    goals.Add(new StagedGoal(false, killingCommits));
                    if (killingCommits) o++;
                    while (o <= p) { goals.Add(new StagedGoal(false, true)); o++; }
                    break;
                case LegGrade.Voided:
                default:
                    break; // the scoreline freezes as-is under the cyan VOID treatment
            }
            return new FinalPlan(grade, goals.ToArray());
        }

        /// <summary>New leg, new match: the scoreline resets.</summary>
        public void ResetForLeg()
        {
            Picked = 0;
            Opponent = 0;
            CommittedGoals = 0;
        }
    }

    /// <summary>
    /// The theater's team-color law (F_0.2.0): colors come from a fixed pool that excludes
    /// every reserved signal color — phosphor green (money-good), hot red (money-bad),
    /// gold (cash-out), cyan (VOID). Assignment is deterministic from the team NAME
    /// (FNV-1a, presentation-local — a team keeps its color across rounds and replays,
    /// no engine RNG involved); the away team takes the next distinct pool entry.
    /// </summary>
    public static class TheaterPalette
    {
        /// <summary>0xRRGGBB. Electric blue, magenta, orange, violet, broadcast white.</summary>
        public static readonly uint[] TeamPool = { 0x3D7BFF, 0xE84DD0, 0xFF8A2B, 0x9B5CF6, 0xF0F3F6 };

        public static (uint Home, uint Away) TeamColors(string homeName, string awayName)
        {
            int home = (int)(Fnv1a(homeName ?? string.Empty) % (uint)TeamPool.Length);
            int away = (int)(Fnv1a(awayName ?? string.Empty) % (uint)TeamPool.Length);
            if (away == home) away = (away + 1) % TeamPool.Length;
            return (TeamPool[home], TeamPool[away]);
        }

        private static uint Fnv1a(string s)
        {
            unchecked
            {
                uint h = 2166136261;
                for (int i = 0; i < s.Length; i++)
                {
                    h ^= s[i];
                    h *= 16777619;
                }
                return h;
            }
        }
    }
}

using System.Collections.Generic;
using NUnit.Framework;
using SBR.Engine;
using SBR.Game;

namespace SBR.Tests.EditMode
{
    /// <summary>
    /// M4 EditMode: the betslip model's toggle semantics, chip/nudge stake math, preview accuracy
    /// against the engine's own payout, and place blockers. Pure engine + model — no Unity runtime.
    /// </summary>
    public class BetslipModelTests
    {
        // The chip/reanchor math below was written against bank 500; the economy rework moved the
        // default to 350, so every run pins its config.
        private static RunConfig Bank500() => new RunConfig { StartingBank = 500 };

        [Test]
        public void Toggle_adds_switches_and_removes()
        {
            var run = new Run("SLIP-TOGGLE", Bank500());
            var slip = new BetslipModel(run);

            Assert.IsTrue(slip.Toggle(0, Side.Home));
            Assert.AreEqual(Side.Home, slip.SideOn(0));

            Assert.IsTrue(slip.Toggle(0, Side.Away), "clicking the other side switches");
            Assert.AreEqual(Side.Away, slip.SideOn(0));
            Assert.AreEqual(1, slip.Picks.Count, "switching must not duplicate the leg");

            Assert.IsTrue(slip.Toggle(0, Side.Away), "clicking the same side removes");
            Assert.IsNull(slip.SideOn(0));
            Assert.AreEqual(0, slip.Picks.Count);
        }

        [Test]
        public void Toggle_caps_new_legs_at_max_but_still_switches_existing()
        {
            var run = new Run("SLIP-CAP", new RunConfig { MaxLegs = 2, StartingBank = 500 });
            var slip = new BetslipModel(run);

            Assert.IsTrue(slip.Toggle(0, Side.Home));
            Assert.IsTrue(slip.Toggle(1, Side.Home));
            Assert.IsFalse(slip.Toggle(2, Side.Home), "a third NEW leg exceeds MaxLegs=2");
            Assert.AreEqual(2, slip.Picks.Count);

            Assert.IsTrue(slip.Toggle(1, Side.Away), "switching an existing leg is always allowed");
            Assert.AreEqual(Side.Away, slip.SideOn(1));
        }

        [Test]
        public void Stake_chips_and_nudges_clamp_to_min_and_bank()
        {
            var run = new Run("SLIP-STAKE", Bank500()); // starting bank 500
            var slip = new BetslipModel(run);

            Assert.AreEqual(50.0, slip.Stake, 1e-9, "default chip is 10% of bank");

            slip.SetStakeFraction(0.25);
            Assert.AreEqual(125.0, slip.Stake, 1e-9);

            slip.SetStakeFraction(1.0);
            Assert.AreEqual(500.0, slip.Stake, 1e-9, "MAX chip is the whole bank (uncapped stakes)");

            slip.Nudge(+10);
            Assert.AreEqual(500.0, slip.Stake, 1e-9, "nudge clamps at the bank");

            slip.SetStakeFraction(0.0);
            Assert.AreEqual(run.Config.MinStake, slip.Stake, 1e-9, "chips clamp up to the min stake");

            slip.Nudge(-10);
            Assert.AreEqual(run.Config.MinStake, slip.Stake, 1e-9, "nudge clamps at the min stake");
        }

        [Test]
        public void ToWin_preview_matches_the_engine_ticket_payout_without_relics()
        {
            var run = new Run("SLIP-PREVIEW", Bank500());
            var slip = new BetslipModel(run);

            slip.Toggle(0, Side.Home);
            slip.Toggle(3, Side.Away);
            slip.SetStakeFraction(0.25);
            double preview = slip.ToWin;

            Ticket ticket = slip.Place();
            Assert.AreEqual(preview, ticket.PotentialPayout, 1e-9,
                "with no compose-time relics the base-odds preview IS the engine payout");
        }

        [Test]
        public void Place_clears_the_slip_and_reanchors_the_stake_to_the_new_bank()
        {
            var run = new Run("SLIP-REANCHOR", Bank500()); // bank 500
            var slip = new BetslipModel(run);

            slip.Toggle(0, Side.Home);
            slip.SetStakeFraction(0.25); // 125
            slip.Place();

            Assert.AreEqual(0, slip.Picks.Count);
            Assert.AreEqual(375.0, run.Bank, 1e-9);
            Assert.AreEqual(37.0, slip.Stake, 1e-9, "stake re-anchors to floor(10% of the new bank)");
        }

        [Test]
        public void PlaceBlocker_walks_the_reasons()
        {
            var run = new Run("SLIP-BLOCK", Bank500());
            var slip = new BetslipModel(run);

            Assert.AreEqual("pick a side", slip.PlaceBlocker);

            slip.Toggle(0, Side.Home);
            Assert.IsNull(slip.PlaceBlocker);

            for (int i = 0; i < run.Config.MaxTicketsPerRound; i++)
            {
                run.PlaceTicket(new List<Pick> { new Pick(i + 1, Side.Home) }, 10);
            }
            Assert.AreEqual($"max {run.Config.MaxTicketsPerRound} tickets", slip.PlaceBlocker);

            run.LockRound();
            Assert.AreEqual("betting is closed", slip.PlaceBlocker);
        }

        [Test]
        public void Model_consumes_no_engine_rng()
        {
            var run = new Run("SLIP-PURE", Bank500());
            var slip = new BetslipModel(run);
            slip.Toggle(0, Side.Home);
            slip.Toggle(2, Side.Away);
            slip.SetStakeFraction(0.5);
            _ = slip.CombinedOdds;
            _ = slip.ToWin;
            slip.Place();

            var control = new Run("SLIP-PURE", Bank500());
            run.LockRound();
            control.LockRound();
            for (int i = 0; i < control.CurrentSlate.Matchups.Count; i++)
                Assert.AreEqual(control.CurrentSlate.Matchups[i].Result, run.CurrentSlate.Matchups[i].Result,
                    "slip math must never perturb the fixed outcome universe");
        }
    }
}

using System;
using System.Collections.Generic;

namespace SBR.Engine;

/// <summary>
/// The shared market model. Slate generation owns the public latent inputs and this class owns the
/// exact finite distributions used both to price a selection and to sample its locked stat line.
/// No method here consumes RNG except SampleStatLine, which has a fixed six-draw contract.
/// </summary>
/// <summary>Per-matchup cache of the exact distributions (built once, lazily, via
/// <c>Matchup.Dist</c>). Score lists are normalized exactly as <see cref="MatchModel.EnumerateScores"/>
/// returns them; count arrays keep the RAW truncated-Poisson terms plus their totals so the
/// sampler's <c>roll × total</c> walk is bit-identical to the uncached path.</summary>
internal sealed class MatchDistributions
{
    public IReadOnlyList<MatchModel.ScoreOutcome> HomeWinScores { get; private set; } = null!;
    public IReadOnlyList<MatchModel.ScoreOutcome> AwayWinScores { get; private set; } = null!;
    public double[] HomeCornerRaw { get; private set; } = null!;
    public double[] AwayCornerRaw { get; private set; } = null!;
    public double[] HomeCardRaw { get; private set; } = null!;
    public double[] AwayCardRaw { get; private set; } = null!;
    public double HomeCornerTotal { get; private set; }
    public double AwayCornerTotal { get; private set; }
    public double HomeCardTotal { get; private set; }
    public double AwayCardTotal { get; private set; }

    public static MatchDistributions Build(MatchLatents l, RunConfig config)
    {
        var d = new MatchDistributions
        {
            HomeWinScores = MatchModel.EnumerateScores(l, true, config),
            AwayWinScores = MatchModel.EnumerateScores(l, false, config),
        };
        (d.HomeCornerRaw, d.HomeCornerTotal) = MatchModel.RawPoisson(l.HomeCornerRate, config.MaxCornerGrid);
        (d.AwayCornerRaw, d.AwayCornerTotal) = MatchModel.RawPoisson(l.AwayCornerRate, config.MaxCornerGrid);
        (d.HomeCardRaw, d.HomeCardTotal) = MatchModel.RawPoisson(l.HomeCardRate, config.MaxCardGrid);
        (d.AwayCardRaw, d.AwayCardTotal) = MatchModel.RawPoisson(l.AwayCardRate, config.MaxCardGrid);
        return d;
    }
}

public static class MatchModel
{
    public readonly struct ScoreOutcome
    {
        public int HomeGoals { get; }
        public int AwayGoals { get; }
        public double Probability { get; }

        public ScoreOutcome(int homeGoals, int awayGoals, double probability)
        {
            HomeGoals = homeGoals;
            AwayGoals = awayGoals;
            Probability = probability;
        }
    }

    public static MatchLatents LatentsFor(double trueHomeProb, double goalTempo,
        double cornerTempo, double disciplineTempo, RunConfig config)
    {
        double homeAttack = 0.6 + 0.8 * trueHomeProb;
        double awayAttack = 0.6 + 0.8 * (1.0 - trueHomeProb);
        double homeDiscipline = 1.15 - 0.3 * trueHomeProb;
        double awayDiscipline = 1.15 - 0.3 * (1.0 - trueHomeProb);
        return new MatchLatents(
            config.BaseGoalRate * goalTempo * homeAttack,
            config.BaseGoalRate * goalTempo * awayAttack,
            config.BaseCornerRate * cornerTempo * homeAttack,
            config.BaseCornerRate * cornerTempo * awayAttack,
            config.BaseCardRate * disciplineTempo * homeDiscipline,
            config.BaseCardRate * disciplineTempo * awayDiscipline);
    }

    public static IReadOnlyList<MarketOffer> BuildOffers(Matchup matchup, RunConfig config)
    {
        var offers = new List<MarketOffer>
        {
            Offer(matchup, MarketSelection.Moneyline(Side.Home), config),
            Offer(matchup, MarketSelection.Moneyline(Side.Away), config),
        };
        foreach (double line in config.GoalLines)
        {
            offers.Add(Offer(matchup, MarketSelection.TotalGoals(line, true), config));
            offers.Add(Offer(matchup, MarketSelection.TotalGoals(line, false), config));
        }
        offers.Add(Offer(matchup, MarketSelection.BothTeamsToScore(true), config));
        offers.Add(Offer(matchup, MarketSelection.BothTeamsToScore(false), config));
        foreach (double line in config.CornerLines)
        {
            offers.Add(Offer(matchup, MarketSelection.TotalCorners(line, true), config));
            offers.Add(Offer(matchup, MarketSelection.TotalCorners(line, false), config));
        }
        foreach (double line in config.CardLines)
        {
            offers.Add(Offer(matchup, MarketSelection.TotalCards(line, true), config));
            offers.Add(Offer(matchup, MarketSelection.TotalCards(line, false), config));
        }
        return offers;
    }

    private static MarketOffer Offer(Matchup matchup, MarketSelection selection, RunConfig config)
    {
        double p = TrueProbability(matchup, selection);
        double odds = 1.0 / (p * (1.0 + config.Overround));
        // Locked odds are the contract, and OddsMath rejects decimals <= 1 everywhere downstream —
        // fail at pricing time, not when a parlay product first touches the leg.
        if (odds <= 1.0)
            throw new InvalidOperationException(
                $"{selection.Kind} {selection.Line} {selection.Choice} prices at {odds:0.000} <= 1.0 " +
                "(true prob too high for the configured overround — retune lines or grids)");
        return new MarketOffer(selection, p, odds);
    }

    public static MatchStatLine SampleStatLine(Matchup matchup, Pcg32 outcomes)
    {
        MatchDistributions d = matchup.Dist;
        bool homeWon = outcomes.NextDouble() < matchup.TrueHomeProb;
        ScoreOutcome score = SampleScore(homeWon ? d.HomeWinScores : d.AwayWinScores, outcomes);
        int homeCorners = SampleFromRaw(d.HomeCornerRaw, d.HomeCornerTotal, outcomes);
        int awayCorners = SampleFromRaw(d.AwayCornerRaw, d.AwayCornerTotal, outcomes);
        int homeCards = SampleFromRaw(d.HomeCardRaw, d.HomeCardTotal, outcomes);
        int awayCards = SampleFromRaw(d.AwayCardRaw, d.AwayCardTotal, outcomes);
        return new MatchStatLine(score.HomeGoals, score.AwayGoals, homeCorners, awayCorners, homeCards, awayCards);
    }

    public static double TrueProbability(Matchup matchup, MarketSelection selection)
    {
        MatchLatents l = matchup.Latents;
        RunConfig config = matchup.ModelConfig;
        switch (selection.Kind)
        {
            case MarketKind.Moneyline:
                RequireChoice(selection, MarketChoice.Home, MarketChoice.Away);
                return selection.Choice == MarketChoice.Home ? matchup.TrueHomeProb : 1.0 - matchup.TrueHomeProb;

            case MarketKind.TotalGoals:
                RequireChoice(selection, MarketChoice.Over, MarketChoice.Under);
                double overGoals = GoalTotalProbability(matchup, selection.Line, config);
                return selection.Choice == MarketChoice.Over ? overGoals : 1.0 - overGoals;

            case MarketKind.BothTeamsToScore:
                RequireChoice(selection, MarketChoice.Yes, MarketChoice.No);
                double btts = ScoreProbability(matchup, (h, a) => h >= 1 && a >= 1, config);
                return selection.Choice == MarketChoice.Yes ? btts : 1.0 - btts;

            case MarketKind.TotalCorners:
                RequireChoice(selection, MarketChoice.Over, MarketChoice.Under);
                double overCorners = CountTotalProbability(
                    matchup.Dist.HomeCornerRaw, matchup.Dist.HomeCornerTotal,
                    matchup.Dist.AwayCornerRaw, matchup.Dist.AwayCornerTotal, selection.Line);
                return selection.Choice == MarketChoice.Over ? overCorners : 1.0 - overCorners;

            case MarketKind.TotalCards:
                RequireChoice(selection, MarketChoice.Over, MarketChoice.Under);
                double overCards = CountTotalProbability(
                    matchup.Dist.HomeCardRaw, matchup.Dist.HomeCardTotal,
                    matchup.Dist.AwayCardRaw, matchup.Dist.AwayCardTotal, selection.Line);
                return selection.Choice == MarketChoice.Over ? overCards : 1.0 - overCards;

            case MarketKind.AnytimeScorer:
                throw new NotSupportedException("Anytime Scorer is a Phase 4 market");

            default:
                throw new ArgumentOutOfRangeException(nameof(selection));
        }
    }

    public static bool Grades(MatchStatLine line, MarketSelection selection)
    {
        switch (selection.Kind)
        {
            case MarketKind.Moneyline:
                return selection.Choice == (line.Winner == Side.Home ? MarketChoice.Home : MarketChoice.Away);
            case MarketKind.TotalGoals:
                return Compare(line.HomeGoals + line.AwayGoals, selection.Line, selection.Choice);
            case MarketKind.BothTeamsToScore:
                return (line.HomeGoals >= 1 && line.AwayGoals >= 1) == (selection.Choice == MarketChoice.Yes);
            case MarketKind.TotalCorners:
                return Compare(line.HomeCorners + line.AwayCorners, selection.Line, selection.Choice);
            case MarketKind.TotalCards:
                return Compare(line.HomeCards + line.AwayCards, selection.Line, selection.Choice);
            case MarketKind.AnytimeScorer:
                throw new NotSupportedException("Anytime Scorer is a Phase 4 market");
            default:
                throw new ArgumentOutOfRangeException(nameof(selection));
        }
    }

    public static string DisplayLabel(Matchup matchup, MarketSelection selection)
    {
        string match = $"{matchup.Away.Name} v {matchup.Home.Name}";
        switch (selection.Kind)
        {
            case MarketKind.Moneyline:
                return $"{(selection.Choice == MarketChoice.Home ? matchup.Home.Name : matchup.Away.Name)} ML — {match}";
            case MarketKind.TotalGoals:
                return $"{selection.Choice.ToString().ToUpperInvariant()} {selection.Line:0.0} GOALS — {match}";
            case MarketKind.BothTeamsToScore:
                return $"BTTS {selection.Choice.ToString().ToUpperInvariant()} — {match}";
            case MarketKind.TotalCorners:
                return $"{selection.Choice.ToString().ToUpperInvariant()} {selection.Line:0.0} CORNERS — {match}";
            case MarketKind.TotalCards:
                return $"{selection.Choice.ToString().ToUpperInvariant()} {selection.Line:0.0} CARDS — {match}";
            default:
                return selection.Kind.ToString();
        }
    }

    public static IReadOnlyList<ScoreOutcome> EnumerateScores(MatchLatents latents, bool homeWon, RunConfig config)
    {
        var values = new List<ScoreOutcome>();
        double total = 0.0;
        for (int h = 0; h <= config.MaxGoalsGrid; h++)
            for (int a = 0; a <= config.MaxGoalsGrid; a++)
                if ((homeWon && h > a) || (!homeWon && a > h))
                {
                    double p = PoissonPmf(h, latents.HomeGoalRate) * PoissonPmf(a, latents.AwayGoalRate);
                    values.Add(new ScoreOutcome(h, a, p));
                    total += p;
                }

        for (int i = 0; i < values.Count; i++)
            values[i] = new ScoreOutcome(values[i].HomeGoals, values[i].AwayGoals, values[i].Probability / total);
        return values;
    }

    private static ScoreOutcome SampleScore(IReadOnlyList<ScoreOutcome> scores, Pcg32 rng)
    {
        double roll = rng.NextDouble();
        for (int i = 0; i < scores.Count; i++)
        {
            roll -= scores[i].Probability;
            if (roll < 0.0) return scores[i];
        }
        return scores[scores.Count - 1];
    }

    private static int SampleFromRaw(double[] raw, double total, Pcg32 rng)
    {
        double roll = rng.NextDouble() * total;
        for (int i = 0; i < raw.Length; i++)
        {
            roll -= raw[i];
            if (roll < 0.0) return i;
        }
        return raw.Length - 1;
    }

    /// <summary>Raw truncated-Poisson terms plus their sum — the cache keeps them unnormalized
    /// so the sampler's roll × total walk stays bit-identical to the original uncached math.</summary>
    internal static (double[] raw, double total) RawPoisson(double lambda, int max)
    {
        var p = new double[max + 1];
        double total = 0.0;
        for (int i = 0; i <= max; i++) { p[i] = PoissonPmf(i, lambda); total += p[i]; }
        return (p, total);
    }

    private static double GoalTotalProbability(Matchup matchup, double line, RunConfig config)
        => ScoreProbability(matchup, (h, a) => h + a > line, config);

    private static double ScoreProbability(Matchup matchup, Func<int, int, bool> predicate, RunConfig config)
    {
        double p = 0.0;
        foreach (ScoreOutcome x in matchup.Dist.HomeWinScores)
            if (predicate(x.HomeGoals, x.AwayGoals)) p += matchup.TrueHomeProb * x.Probability;
        foreach (ScoreOutcome x in matchup.Dist.AwayWinScores)
            if (predicate(x.HomeGoals, x.AwayGoals)) p += (1.0 - matchup.TrueHomeProb) * x.Probability;
        return p;
    }

    private static double CountTotalProbability(double[] homeRaw, double homeTotal,
        double[] awayRaw, double awayTotal, double line)
    {
        double p = 0.0;
        for (int h = 0; h < homeRaw.Length; h++)
            for (int a = 0; a < awayRaw.Length; a++)
                if (h + a > line) p += (homeRaw[h] / homeTotal) * (awayRaw[a] / awayTotal);
        return p;
    }

    private static double PoissonPmf(int k, double lambda)
    {
        double p = Math.Exp(-lambda);
        for (int i = 1; i <= k; i++) p *= lambda / i;
        return p;
    }

    private static void RequireChoice(MarketSelection selection, MarketChoice first, MarketChoice second)
    {
        if (selection.Choice != first && selection.Choice != second)
            throw new ArgumentException($"Invalid choice {selection.Choice} for {selection.Kind}");
    }

    private static bool Compare(int value, double line, MarketChoice choice)
    {
        if (choice != MarketChoice.Over && choice != MarketChoice.Under)
            throw new ArgumentException($"Counting market requires Over or Under, got {choice}");
        return choice == MarketChoice.Over ? value > line : value < line;
    }
}

using System.Collections.Generic;
using NUnit.Framework;
using SBR.Engine;
using SBR.Probe;

namespace SBR.Tests.EditMode
{
    /// <summary>
    /// M1, Phase 2 — proves SBR.Engine.dll reproduces the Week 2 determinism pins inside Unity's
    /// (Mono) editor runtime. Ported from engine.tests/GoldenSeedTests.cs (the golden event stream,
    /// first-ten win probabilities, and settled bank) plus one engine.tests/DebtTests.cs case so the
    /// newest engine surface (debt-as-HP) is exercised through the DLL in Unity too. The pin data lives
    /// once in <see cref="GoldenReplay"/>; these tests assert the DLL's actual values against it.
    /// </summary>
    public class DeterminismEditModeTests
    {
        [Test]
        public void Golden_seed_event_stream_is_pinned()
        {
            Run run = GoldenReplay.ScriptedRound();
            List<DramaEvent> events = GoldenReplay.DrainAll(run);

            Assert.AreEqual(14, events.Count, "expected exactly 14 events (F_0.4.0 Phase 1 re-pin)");
            Assert.AreEqual(GoldenReplay.ExpectedEvents.Length, events.Count);

            for (int i = 0; i < events.Count; i++)
            {
                DramaEvent e = events[i];
                var x = GoldenReplay.ExpectedEvents[i];
                Assert.AreEqual(x.leg, e.LegIndex, $"LegIndex @ event {i}");
                Assert.AreEqual(x.step, e.Step, $"Step @ event {i}");
                Assert.AreEqual(x.type, e.Type, $"Type @ event {i}");
                Assert.AreEqual(x.tag, e.Tag, $"Tag @ event {i}");
            }

            // 6 dp, matching engine.tests' Assert.Equal(expected, actual, 6).
            for (int i = 0; i < GoldenReplay.ExpectedFirstTenWinProb.Length; i++)
                Assert.AreEqual(GoldenReplay.ExpectedFirstTenWinProb[i], events[i].WinProbAfter, 1e-6,
                    $"WinProbAfter @ event {i}");
        }

        [Test]
        public void Golden_seed_settles_to_pinned_bank_and_phase()
        {
            Run run = GoldenReplay.ScriptedRound();
            GoldenReplay.DrainAll(run);
            run.FinishSweat();

            Assert.AreEqual(Phase.Settlement, run.Phase);
            Assert.AreEqual(TicketState.Lost, run.Tickets[0].State); // parlay died on its second leg
            Assert.AreEqual(TicketState.Won, run.Tickets[1].State);  // single hit — payout crediting stays pinned
            Assert.AreEqual(GoldenReplay.ExpectedBank, run.Bank, 1e-5); // 5 dp
        }

        [Test]
        public void Golden_seed_replays_identically()
        {
            List<DramaEvent> a = GoldenReplay.DrainAll(GoldenReplay.ScriptedRound());
            List<DramaEvent> b = GoldenReplay.DrainAll(GoldenReplay.ScriptedRound());

            Assert.AreEqual(a.Count, b.Count);
            for (int i = 0; i < a.Count; i++)
            {
                Assert.AreEqual(a[i].LegIndex, b[i].LegIndex);
                Assert.AreEqual(a[i].Step, b[i].Step);
                Assert.AreEqual(a[i].Type, b[i].Type);
                Assert.AreEqual(a[i].Tag, b[i].Tag);
                Assert.AreEqual(a[i].WinProbAfter, b[i].WinProbAfter, 1e-15);
            }
        }

        [Test]
        public void Probe_verify_passes_and_reports_event_stream_hash()
        {
            GoldenReplay.Result r = GoldenReplay.Verify();
            Assert.IsTrue(r.Pass, r.Detail);
            Assert.IsNotNull(r.Hash);
            // Surfaces the golden fingerprint in the test log for cross-platform comparison.
            TestContext.WriteLine($"[EditMode/Mono] event-stream FNV-1a hash = {r.Hash}");
        }

        [Test]
        public void Payment_shortfall_with_the_totem_defers_and_surcharges_the_next_payment()
        {
            // The economy rework's mercy path (design/10, playtest #8): the Totem DEFERS a
            // non-final payment — the bank is untouched (working capital survives) and the
            // NEXT payment grows by payment × (1 + juice).
            var run = new Run("PAY-TOTEM", new RunConfig
            {
                StartingBank = 500,
                Payments = new double[] { 800, 400 },
                TotemJuiceRate = 0.5,
            });
            foreach (RelicDefinition def in RelicCatalog.All)
                if (def.Id == RelicCatalog.TotemId) run.GrantRelic(def);
            run.LockRound();
            run.FastForwardRound();
            run.Settle();

            Assert.AreEqual(Phase.Shop, run.Phase);                       // the run continues
            Assert.AreEqual(500.0, run.Bank, 1e-9);                       // the bank stands
            Assert.IsTrue(run.LastSettlement!.Value.TotemFired);
            run.ExitShop();
            Assert.AreEqual(400.0 + 800.0 * 1.5, run.CurrentPayment, 1e-9); // payment × 1.5 lands on P2
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace SBR.Engine;

public enum Side { Home, Away }

public enum MarketKind
{
    Moneyline,
    TotalGoals,
    BothTeamsToScore,
    TotalCorners,
    TotalCards,
    AnytimeScorer,
}

/// <summary>The two-way choice vocabulary is kept separate from team side because counting
/// markets use Over/Under and BTTS uses Yes/No.</summary>
public enum MarketChoice { Home, Away, Over, Under, Yes, No }

public enum LegState { Pending, Won, Lost }

public enum TicketState { Open, Won, Lost, CashedOut }

/// <summary>A ticket's final, ticket-local grading of one leg — what OnLegResolved carries
/// after any pending-loss window has closed (charm expansion, PLAN.md rev 5).</summary>
public enum LegGrade { Won, Lost, Voided }

/// <summary>Locked contract modifiers (charm expansion): at most ONE per ticket — the
/// one-modifier law, mirror of the one-product-slot law. Locked at placement, part of the
/// ticket's outcome→cash-flow contract (they price into cash-outs and G4).</summary>
public enum TicketModifier { None, FreeBet, DoubleOrNothing }

public readonly struct MarketSelection : IEquatable<MarketSelection>
{
    public MarketKind Kind { get; }
    public double Line { get; }
    public MarketChoice Choice { get; }
    public int PlayerIndex { get; }

    public MarketSelection(MarketKind kind, double line, MarketChoice choice, int playerIndex = -1)
    {
        Kind = kind;
        Line = line;
        Choice = choice;
        PlayerIndex = playerIndex;
    }

    public MarketSelection(MarketKind kind, double line, Side side)
        : this(kind, line, kind == MarketKind.Moneyline
            ? (side == Side.Home ? MarketChoice.Home : MarketChoice.Away)
            : throw new ArgumentException("Side choices are only valid for moneyline")) { }

    public MarketSelection(MarketKind kind, Side side)
        : this(kind, 0.0, side) { }

    public MarketSelection(MarketKind kind, double line, bool over)
        : this(kind, line, over ? MarketChoice.Over : MarketChoice.Under) { }

    public MarketSelection(MarketKind kind, bool yes)
        : this(kind, 0.0, yes ? MarketChoice.Yes : MarketChoice.No) { }

    public static MarketSelection Moneyline(Side side)
        => new MarketSelection(MarketKind.Moneyline, 0.0,
            side == Side.Home ? MarketChoice.Home : MarketChoice.Away);

    public static MarketSelection TotalGoals(double line, bool over)
        => new MarketSelection(MarketKind.TotalGoals, line, over ? MarketChoice.Over : MarketChoice.Under);

    public static MarketSelection BothTeamsToScore(bool yes)
        => new MarketSelection(MarketKind.BothTeamsToScore, 0.0, yes ? MarketChoice.Yes : MarketChoice.No);

    public static MarketSelection TotalCorners(double line, bool over)
        => new MarketSelection(MarketKind.TotalCorners, line, over ? MarketChoice.Over : MarketChoice.Under);

    public static MarketSelection TotalCards(double line, bool over)
        => new MarketSelection(MarketKind.TotalCards, line, over ? MarketChoice.Over : MarketChoice.Under);

    public bool Equals(MarketSelection other)
        => Kind == other.Kind && Line.Equals(other.Line) && Choice == other.Choice
            && PlayerIndex == other.PlayerIndex;
    public override bool Equals(object? obj) => obj is MarketSelection other && Equals(other);
    public override int GetHashCode() => HashCode.Combine((int)Kind, Line, (int)Choice, PlayerIndex);
    public static bool operator ==(MarketSelection left, MarketSelection right) => left.Equals(right);
    public static bool operator !=(MarketSelection left, MarketSelection right) => !left.Equals(right);
}

public sealed class MarketOffer
{
    public MarketSelection Selection { get; }
    public double TrueProb { get; }
    public double Odds { get; }

    public MarketOffer(MarketSelection selection, double trueProb, double odds)
    {
        Selection = selection;
        TrueProb = trueProb;
        Odds = odds;
    }
}

public readonly struct TeamStats
{
    public double GoalsFor { get; }
    public double Corners { get; }
    public double Cards { get; }

    public TeamStats(double goalsFor, double corners, double cards)
    {
