            }
            for (int i = 0; i < run.OwnedConsumables.Count; i++)
            {
                int index = i;
                LaptopUi.MakeButton(_root, "SellConsumable" + i, "SELL " + run.OwnedConsumables[i].Name,
                    new Vector2(0f, 0f), new Vector2(0f, 0f), new Vector2(x, 86f), new Vector2(150f, 26f), 9,
