                boardFrozen ? LaptopOs.Muted : LaptopOs.Accent,
                boardFrozen ? "THE SHOW IS ON THE TV   ·   BOARD CLOSED" : "TODAY'S BOARD   ·   MONEYLINE", _font);
            LaptopUi.MakeText(board, "BoardSub", new Vector2(0f, 1f), new Vector2(0f, 1f),
