using System;
using System.Collections.Generic;
using System.Linq;
using SBR.Engine;

namespace SBR.Game
{
    /// <summary>
    /// The working slip's state (M4) — pure C#, no Unity, so EditMode tests exercise it directly and
    /// the laptop UI stays a thin renderer. One slip is built at a time (M4 grill decision): clicking
    /// a slate side toggles the leg (same side removes, other side switches), stake is set by
    /// fraction-of-bank chips (10/25/50/MAX) or $10 nudges, and Place() hands the picks to the engine
    /// (which owns all validation and any compose-time relic odds rewrites).
    ///
    /// The slip's TO WIN preview uses BASE slate odds — a promo/boost relic can only make the placed
    /// ticket better than the preview, never worse (the placed-tickets list shows the real payout).
    /// </summary>
    public sealed class BetslipModel
    {
        private readonly Run _run;
        private readonly List<Pick> _picks = new List<Pick>();

        /// <summary>Whole-dollar stake. Clamped to [MinStake, MaxStakeFraction × bank] on every set.</summary>
        public double Stake { get; private set; }

        /// <summary>Index into Picks of the leg a held Profit Boost lands on, or −1. Any leg
        /// mutation clears it (indices shift; the player re-aims deliberately).</summary>
        public int BoostLeg { get; private set; } = -1;

        /// <summary>The locked contract modifier this slip will place with (one per ticket —
        /// the one-modifier law; charm expansion). Cleared with the slip.</summary>
        public TicketModifier Modifier { get; private set; } = TicketModifier.None;

        public IReadOnlyList<Pick> Picks => _picks;

        public BetslipModel(Run run)
        {
            _run = run ?? throw new ArgumentNullException(nameof(run));
            SetStakeFraction(0.10);
        }

        // ------------------------------------------------------------------ legs

        /// <summary>The slip's side on this matchup, if any.</summary>
        public Side? SideOn(int matchupIndex)
        {
            foreach (Pick p in _picks)
                if (p.MatchupIndex == matchupIndex) return p.Side;
            return null;
        }

        /// <summary>Slate-side click: adds the leg, switches side, or removes it (same side again).
        /// Returns false only when a NEW leg would exceed MaxLegs.</summary>
        public bool Toggle(int matchupIndex, Side side)
        {
            BoostLeg = -1;
            for (int i = 0; i < _picks.Count; i++)
            {
                if (_picks[i].MatchupIndex != matchupIndex) continue;
                if (_picks[i].Side == side) _picks.RemoveAt(i);
                else _picks[i] = new Pick(matchupIndex, side);
                return true;
            }

            if (_picks.Count >= _run.Config.MaxLegs) return false;
            _picks.Add(new Pick(matchupIndex, side));
            return true;
        }

        public void Remove(int matchupIndex)
        {
            BoostLeg = -1;
            _picks.RemoveAll(p => p.MatchupIndex == matchupIndex);
        }

        public void Clear()
        {
            BoostLeg = -1;
            _picks.Clear();
        }

        /// <summary>Aims (or un-aims) the held Profit Boost at a slip leg. No-op without the item.</summary>
        public void ToggleBoost(int pickIndex)
        {
            if (pickIndex < 0 || pickIndex >= _picks.Count) return;
            if (!_run.OwnsConsumable("profit_boost")) return;
            BoostLeg = BoostLeg == pickIndex ? -1 : pickIndex;
        }

        /// <summary>Toggles a locked contract modifier onto the slip (Free Bet xor DoN — picking
        /// one replaces the other). No-op without the matching consumable held.</summary>
        public void ToggleModifier(TicketModifier modifier)
        {
            if (modifier == TicketModifier.FreeBet && !_run.OwnsConsumable("free_bet")) return;
            if (modifier == TicketModifier.DoubleOrNothing && !_run.OwnsConsumable("double_or_nothing")) return;
            Modifier = Modifier == modifier ? TicketModifier.None : modifier;
        }

        // ------------------------------------------------------------------ stake

        /// <summary>A fraction chip: stake = floor(fraction × bank), clamped. 1.0 = the MAX chip.</summary>
        public void SetStakeFraction(double fraction)
            => Stake = ClampStake(Math.Floor(fraction * _run.Bank));

        /// <summary>The −/+ $10 nudge buttons.</summary>
        public void Nudge(double dollars) => Stake = ClampStake(Stake + dollars);

        private double ClampStake(double stake)
        {
            double max = Math.Floor(_run.Config.MaxStakeFraction * _run.Bank);
            return Math.Max(_run.Config.MinStake, Math.Min(stake, max));
        }

        // ------------------------------------------------------------------ derived

        /// <summary>Parlay decimal odds over the slip's BASE slate prices.</summary>
        public double CombinedOdds
        {
            get
            {
                if (_picks.Count == 0) return 0.0;
                var odds = new List<double>(_picks.Count);
                foreach (Pick p in _picks)
                    odds.Add(_run.CurrentSlate.Matchups[p.MatchupIndex].Odds(p.Side));
                return OddsMath.ParlayDecimal(odds);
            }
        }

        public double ToWin => _picks.Count == 0 ? 0.0 : Stake * CombinedOdds;

        /// <summary>Why PLACE is disabled, or null when it's live. UI renders the reason verbatim.</summary>
        public string PlaceBlocker
        {
            get
            {
                if (_run.Phase != Phase.Betting) return "betting is closed";
                if (_run.Tickets.Count >= _run.Config.MaxTicketsPerRound)
                    return $"max {_run.Config.MaxTicketsPerRound} tickets";
                if (_picks.Count == 0) return "pick a side";
                if (_run.Bank < _run.Config.MinStake) return "bank too small";
                if (Stake > _run.Config.MaxStakeFraction * _run.Bank) return "stake exceeds bank";
                return null;
            }
        }

        public bool CanPlace => PlaceBlocker == null;

        // ------------------------------------------------------------------ place

        /// <summary>Places the slip as an engine ticket (playing an aimed Profit Boost), clears it,
        /// and re-anchors the stake. Callers should check CanPlace; engine exceptions bubble.</summary>
        public Ticket Place()
        {
            Ticket ticket = _run.PlaceTicket(_picks.ToList(), Stake, BoostLeg, Modifier);
            Clear();
            Modifier = TicketModifier.None;
            SetStakeFraction(0.10);
            return ticket;
        }
    }
}

        internal void MarkCashedOut()
        {
            RevealedTicket ticket = CurrentTicket;
            if (ticket == null) return;
            ticket.State = RevealedTicketState.CashedOut;
            Revision++;
        }

        private RevealedTicket CurrentTicket
            => CurrentTicketIndex >= 0 && CurrentTicketIndex < _tickets.Count ? _tickets[CurrentTicketIndex] : null;

        private static RevealedTicket CopyTicket(Ticket source, int index)
        {
            var legs = new List<RevealedLeg>(source.Legs.Count);
            foreach (Leg leg in source.Legs)
            {
                (uint home, uint away) = TheaterPalette.TeamColors(leg.Matchup.Home.Name, leg.Matchup.Away.Name);
                legs.Add(new RevealedLeg
                {
                    Index = legs.Count,
                    TeamName = SweatFlavor.Short(leg.Side == Side.Home ? leg.Matchup.Home.Name : leg.Matchup.Away.Name).ToUpperInvariant(),
                    AmericanOdds = OddsFormat.American(leg.OfferedOdds),
                    TeamColor = leg.Side == Side.Home ? home : away,
                    State = RevealedLegState.Pending
                });
            }
            return new RevealedTicket
            {
                Index = index,
                Stake = source.Stake,
                PotentialPayout = source.PotentialPayout,
                State = RevealedTicketState.Riding,
                Legs = legs
            };
        }
    }

    /// <summary>
    /// The TV plays the sweat, live from the real engine (M3's emotional core; M4 wires it to the real
    /// round). A world-space UGUI canvas sits on the TV screen inset (0.98 x 0.55) in front of the
    /// emissive quad; a coroutine walks the locked round's sweats SERIALLY (M4 grill decision) - a ~2s
    /// auto-advance ticket card between sweats, a settle card after the last (target met / the bookie
    /// floats you), then the SHOP OPEN nudge while the laptop glows. Events step ONLY while the player
    /// is seated (design/04 - sitting starts/resumes, standing pauses mid-event with the offer frozen).
    /// Outside the sweat the TV idles per phase: PLACE YOUR BETS during Betting, SHOP OPEN during Shop,
    /// and the run verdict card on RunWon/RunLost with the room light dropping cold (M4 grill decision).
    ///
    /// Beats are all code-driven: GREEN = green flood + emissive spike, DEAD = static then the red DEAD
    /// line + the screen dropping darker, ticket-dead = a dim-to-black beat, cash-out = a gold flood
    /// with the amount big. The TvLight makes the room the reaction shot.
    ///
    /// Palette is law (design/08): green = money-good only, red = money-bad only, gold = cash-out.
    /// Pacing ports the console's table into <see cref="PacingFor"/> with serialized dials; no engine RNG
    /// is consumed by presentation (only MoveNext / CashOut* are called - everything is baked at lock).
    /// </summary>
    public sealed class TvSweatScreen : MonoBehaviour
    {
        [Header("Wiring (set by GrayboxRoomBuilder)")]
        public RunDirector director;
        public Renderer emissiveScreen;      // the TV quad behind the canvas - its phosphor glow

            _tMatchup.text =
                $"<color=#{awayRgb:X6}>{awayMark}{away}</color>  {awayScore} — {homeScore}  " +
                $"<color=#{homeRgb:X6}>{home}{homeMark}</color>";
            RevealedView.SetScore($"{away} {awayScore} — {home} {homeScore}");
        }

        private static Color TeamColor(Leg leg, bool pickedSide)
        {
            (uint home, uint away) = TheaterPalette.TeamColors(leg.Matchup.Home.Name, leg.Matchup.Away.Name);
            uint picked = leg.Side == Side.Home ? home : away;
            uint opponent = leg.Side == Side.Home ? away : home;
            return TheaterStage.FromRgb(pickedSide ? picked : opponent);
        }

        /// <summary>The always-on slip strip during a sweat (playtest #6: "what did I place, how much
        /// is at risk, at what odds?"). Rich-text legs colored by PRESENTED status — resolved legs use
        /// the presentation cursor, never engine truth (outcomes are baked at lock; the strip must not
        /// leak them early): green W / red L / cyan VOID. Unresolved legs wear THEIR TEAM'S theater
        /// color (playtest #13 — "which team am I sweating for?"): live at full strength, pending
        /// dimmed; the money colors still take over the instant a leg resolves.</summary>
        private void UpdateSlipStrip(int liveLeg)
        {
            if (_ticket == null) { _tSlipStrip.text = string.Empty; return; }

            string strip = $"RISK ${Money(_ticket.Stake)} → PAYS ${Money(_ticket.PotentialPayout)}     ";
            for (int i = 0; i < _ticket.Legs.Count; i++)
            {
                Leg leg = _ticket.Legs[i];
                string side = SweatFlavor.Short(
                    leg.Side == Side.Home ? leg.Matchup.Home.Name : leg.Matchup.Away.Name).ToUpperInvariant();
                string label = $"{side} {OddsFormat.American(leg.OfferedOdds)}";
                (uint homeRgb, uint awayRgb) = TheaterPalette.TeamColors(leg.Matchup.Home.Name, leg.Matchup.Away.Name);
                uint pickedRgb = leg.Side == Side.Home ? homeRgb : awayRgb;

                if (i > 0) strip += "  ·  ";
                if (i < _resolvedThrough)
                {
                    strip += leg.IsVoided ? $"<color=#9EDCF6>{label} VOID</color>"
                        : leg.GradesWon ? $"<color=#3CE873>{label} W</color>"
                        : $"<color=#FF4038>{label} L</color>";
                }
                else if (i == liveLeg)
                {
                    strip += $"<color=#{pickedRgb:X6}>{label} LIVE</color>";
                }
                else
                {
                    strip += $"<color=#{pickedRgb:X6}99>{label}</color>"; // dimmed team color
                }
            }
            _tSlipStrip.text = strip;
        }

        /// <summary>The auto-advance interstitial (M4): TICKET i/n, the legs line, stake → to-win.</summary>
        private void RenderTicketCard()
