                if (legs.Length > 0) legs += "   ·   ";
                string side = SweatFlavor.Short(
                    leg.Side == Side.Home ? leg.Matchup.Home.Name : leg.Matchup.Away.Name);
                legs += $"{side.ToUpperInvariant()} {OddsFormat.American(leg.OfferedOdds)}";
