8:    /// <summary>
9:    /// The working slip's state (M4) — pure C#, no Unity, so EditMode tests exercise it directly and
10:    /// the laptop UI stays a thin renderer. One slip is built at a time (M4 grill decision): clicking
11:    /// a slate side toggles the leg (same side removes, other side switches), stake is set by
12:    /// fraction-of-bank chips (10/25/50/MAX) or $10 nudges, and Place() hands the picks to the engine
13:    /// (which owns all validation and any compose-time relic odds rewrites).
14:    ///
15:    /// The slip's TO WIN preview uses BASE slate odds — a promo/boost relic can only make the placed
16:    /// ticket better than the preview, never worse (the placed-tickets list shows the real payout).
17:    /// </summary>
18:    public sealed class BetslipModel
19:    {
20:        private readonly Run _run;
21:        private readonly List<Pick> _picks = new List<Pick>();
22:
23:        /// <summary>Whole-dollar stake. Clamped to [MinStake, MaxStakeFraction × bank] on every set.</summary>
24:        public double Stake { get; private set; }
25:
26:        /// <summary>Index into Picks of the leg a held Profit Boost lands on, or −1. Any leg
27:        /// mutation clears it (indices shift; the player re-aims deliberately).</summary>
28:        public int BoostLeg { get; private set; } = -1;
29:
30:        /// <summary>The locked contract modifier this slip will place with (one per ticket —
31:        /// the one-modifier law; charm expansion). Cleared with the slip.</summary>
32:        public TicketModifier Modifier { get; private set; } = TicketModifier.None;
33:
34:        public IReadOnlyList<Pick> Picks => _picks;
35:
36:        public BetslipModel(Run run)
37:        {
38:            _run = run ?? throw new ArgumentNullException(nameof(run));
39:            SetStakeFraction(0.10);
40:        }
41:
42:        // ------------------------------------------------------------------ legs
43:
44:        /// <summary>The slip's side on this matchup, if any.</summary>
45:        public Side? SideOn(int matchupIndex)
46:        {
47:            foreach (Pick p in _picks)
48:                if (p.MatchupIndex == matchupIndex) return p.Side;
49:            return null;
50:        }
51:
52:        /// <summary>Slate-side click: adds the leg, switches side, or removes it (same side again).
53:        /// Returns false only when a NEW leg would exceed MaxLegs.</summary>
54:        public bool Toggle(int matchupIndex, Side side)
55:        {
56:            BoostLeg = -1;
57:            for (int i = 0; i < _picks.Count; i++)
58:            {
59:                if (_picks[i].MatchupIndex != matchupIndex) continue;
60:                if (_picks[i].Side == side) _picks.RemoveAt(i);
61:                else _picks[i] = new Pick(matchupIndex, side);
62:                return true;
63:            }
64:
65:            if (_picks.Count >= _run.Config.MaxLegs) return false;
66:            _picks.Add(new Pick(matchupIndex, side));
67:            return true;
68:        }
69:
70:        public void Remove(int matchupIndex)
71:        {
72:            BoostLeg = -1;
73:            _picks.RemoveAll(p => p.MatchupIndex == matchupIndex);
74:        }
75:
76:        public void Clear()
77:        {
78:            BoostLeg = -1;
79:            _picks.Clear();
80:        }
81:
82:        /// <summary>Aims (or un-aims) the held Profit Boost at a slip leg. No-op without the item.</summary>
83:        public void ToggleBoost(int pickIndex)
84:        {
85:            if (pickIndex < 0 || pickIndex >= _picks.Count) return;
86:            if (!_run.OwnsConsumable("profit_boost")) return;
87:            BoostLeg = BoostLeg == pickIndex ? -1 : pickIndex;
88:        }
89:
90:        /// <summary>Toggles a locked contract modifier onto the slip (Free Bet xor DoN — picking
91:        /// one replaces the other). No-op without the matching consumable held.</summary>
92:        public void ToggleModifier(TicketModifier modifier)
93:        {
94:            if (modifier == TicketModifier.FreeBet && !_run.OwnsConsumable("free_bet")) return;
95:            if (modifier == TicketModifier.DoubleOrNothing && !_run.OwnsConsumable("double_or_nothing")) return;
96:            Modifier = Modifier == modifier ? TicketModifier.None : modifier;
97:        }
98:
99:        // ------------------------------------------------------------------ stake
100:
101:        /// <summary>A fraction chip: stake = floor(fraction × bank), clamped. 1.0 = the MAX chip.</summary>
102:        public void SetStakeFraction(double fraction)
103:            => Stake = ClampStake(Math.Floor(fraction * _run.Bank));
104:
105:        /// <summary>The −/+ $10 nudge buttons.</summary>
106:        public void Nudge(double dollars) => Stake = ClampStake(Stake + dollars);
107:
108:        private double ClampStake(double stake)
109:        {
110:            double max = Math.Floor(_run.Config.MaxStakeFraction * _run.Bank);
111:            return Math.Max(_run.Config.MinStake, Math.Min(stake, max));
112:        }
113:
114:        // ------------------------------------------------------------------ derived
115:
116:        /// <summary>Parlay decimal odds over the slip's BASE slate prices.</summary>
117:        public double CombinedOdds
118:        {
119:            get
120:            {
121:                if (_picks.Count == 0) return 0.0;
122:                var odds = new List<double>(_picks.Count);
123:                foreach (Pick p in _picks)
124:                    odds.Add(_run.CurrentSlate.Matchups[p.MatchupIndex].Odds(p.Side));
125:                return OddsMath.ParlayDecimal(odds);
126:            }
127:        }
128:
129:        public double ToWin => _picks.Count == 0 ? 0.0 : Stake * CombinedOdds;
130:
131:        /// <summary>Why PLACE is disabled, or null when it's live. UI renders the reason verbatim.</summary>
132:        public string PlaceBlocker
133:        {
134:            get
135:            {
136:                if (_run.Phase != Phase.Betting) return "betting is closed";
137:                if (_run.Tickets.Count >= _run.Config.MaxTicketsPerRound)
138:                    return $"max {_run.Config.MaxTicketsPerRound} tickets";
139:                if (_picks.Count == 0) return "pick a side";
140:                if (_run.Bank < _run.Config.MinStake) return "bank too small";
141:                if (Stake > _run.Config.MaxStakeFraction * _run.Bank) return "stake exceeds bank";
142:                return null;
143:            }
144:        }
145:
146:        public bool CanPlace => PlaceBlocker == null;
147:
148:        // ------------------------------------------------------------------ place
149:
150:        /// <summary>Places the slip as an engine ticket (playing an aimed Profit Boost), clears it,
151:        /// and re-anchors the stake. Callers should check CanPlace; engine exceptions bubble.</summary>
152:        public Ticket Place()
153:        {
154:            Ticket ticket = _run.PlaceTicket(_picks.ToList(), Stake, BoostLeg, Modifier);
155:            Clear();
156:            Modifier = TicketModifier.None;
157:            SetStakeFraction(0.10);
158:            return ticket;
159:        }
160:    }
