36:    /// <summary>
37:    /// The TV-owned causal mirror. Laptop MY BETS may read this object, but it cannot access the sweat
38:    /// session or its live offer. Values advance only at the same reveal points as the TV chrome.
39:    /// </summary>
40:    public sealed class RevealedView
41:    {
42:        private readonly List<RevealedTicket> _tickets = new List<RevealedTicket>();
43:
44:        /// <summary>Structural changes only (tickets, legs, states, reset/clear) — the OS
45:        /// rebuilds its UI on this. Fast display values live on DisplayRevision.</summary>
46:        public int Revision { get; internal set; }
47:
48:        /// <summary>Per-frame display values (clock, prob, score, suspension). Consumers
49:        /// update cached labels in place — a ticking minute must never rebuild a canvas
50:        /// (Sol, F_0.3.0 performance finding).</summary>
51:        public int DisplayRevision { get; internal set; }
52:        public bool HasTicket { get; internal set; }
53:        public int CurrentTicketIndex { get; internal set; }
54:        public int TicketCount { get; internal set; }
55:        public float WinProbability { get; internal set; }
56:        public string ScoreText { get; internal set; } = string.Empty;
57:        public string ClockText { get; internal set; } = string.Empty;
58:        public bool MarketSuspended { get; internal set; }
59:        public IReadOnlyList<RevealedTicket> Tickets => _tickets;
60:
61:        internal void Reset(Run run, Ticket current, int currentIndex)
62:        {
63:            var previous = new List<RevealedTicket>(_tickets);
64:            _tickets.Clear();
65:            if (run != null)
66:            {
67:                for (int i = 0; i < run.Tickets.Count; i++)
68:                    _tickets.Add(i < currentIndex && i < previous.Count
69:                        ? previous[i] : CopyTicket(run.Tickets[i], i));
70:            }
71:            CurrentTicketIndex = currentIndex;
72:            TicketCount = _tickets.Count;
73:            HasTicket = current != null && current.Legs.Count > 0;
74:            WinProbability = HasTicket ? (float)current.Legs[0].TrueProb : 0f;
75:            ScoreText = string.Empty;
76:            ClockText = "PRE";
77:            MarketSuspended = false;
78:            Revision++;
79:        }
80:
81:        internal void BeginLeg(int legIndex, Leg leg)
82:        {
83:            if (!HasTicket || leg == null) return;
84:            RevealedTicket ticket = CurrentTicket;
85:            if (ticket == null || legIndex < 0 || legIndex >= ticket.Legs.Count) return;
86:            ticket.Legs[legIndex].State = RevealedLegState.Live;
87:            Revision++;
88:        }
89:
90:        internal void SetProbability(float probability)
91:        {
92:            if (!HasTicket) return;
93:            WinProbability = probability;
94:            DisplayRevision++;
95:        }
96:
97:        internal void SetClock(string clock)
98:        {
99:            if (!HasTicket) return;
100:            ClockText = clock ?? string.Empty;
101:            DisplayRevision++;
102:        }
103:
104:        internal void SetScore(string score)
105:        {
106:            if (!HasTicket) return;
107:            ScoreText = score ?? string.Empty;
108:            DisplayRevision++;
109:        }
110:
111:        internal void SetMarketSuspended(bool suspended)
112:        {
113:            if (!HasTicket) return;
114:            MarketSuspended = suspended;
115:            DisplayRevision++;
116:        }
117:
118:        internal void ResolveLeg(int legIndex, LegGrade grade)
119:        {
120:            RevealedTicket ticket = CurrentTicket;
121:            if (ticket == null || legIndex < 0 || legIndex >= ticket.Legs.Count) return;
122:            ticket.Legs[legIndex].State = grade == LegGrade.Won ? RevealedLegState.Won
123:                : grade == LegGrade.Lost ? RevealedLegState.Lost : RevealedLegState.Voided;
124:            if (grade == LegGrade.Lost) ticket.State = RevealedTicketState.Lost;
125:            else
126:            {
127:                bool allResolved = true;
128:                for (int i = 0; i < ticket.Legs.Count; i++)
129:                    if (ticket.Legs[i].State == RevealedLegState.Pending || ticket.Legs[i].State == RevealedLegState.Live)
130:                        allResolved = false;
131:                if (allResolved) ticket.State = RevealedTicketState.Won;
132:            }
133:            Revision++;
134:        }
135:
136:        /// <summary>The sweat is over and the TV moved on — the mirror empties with it
137:        /// (a stale round under a live banner is a lie; Sol, F_0.3.0 finding 2).</summary>
138:        internal void Clear()
139:        {
140:            _tickets.Clear();
141:            HasTicket = false;
142:            TicketCount = 0;
143:            CurrentTicketIndex = 0;
144:            WinProbability = 0f;
145:            ScoreText = string.Empty;
146:            ClockText = string.Empty;
147:            MarketSuspended = false;
148:            Revision++;
149:        }
150:
151:        internal void MarkCashedOut()
152:        {
153:            RevealedTicket ticket = CurrentTicket;
154:            if (ticket == null) return;
155:            ticket.State = RevealedTicketState.CashedOut;
156:            Revision++;
157:        }
