162:        private static RevealedTicket CopyTicket(Ticket source, int index)
163:        {
164:            var legs = new List<RevealedLeg>(source.Legs.Count);
165:            foreach (Leg leg in source.Legs)
166:            {
167:                (uint home, uint away) = TheaterPalette.TeamColors(leg.Matchup.Home.Name, leg.Matchup.Away.Name);
168:                legs.Add(new RevealedLeg
169:                {
170:                    Index = legs.Count,
171:                    TeamName = SweatFlavor.Short(leg.Side == Side.Home ? leg.Matchup.Home.Name : leg.Matchup.Away.Name).ToUpperInvariant(),
172:                    AmericanOdds = OddsFormat.American(leg.OfferedOdds),
173:                    TeamColor = leg.Side == Side.Home ? home : away,
174:                    State = RevealedLegState.Pending
175:                });
176:            }
177:            return new RevealedTicket
178:            {
179:                Index = index,
180:                Stake = source.Stake,
181:                PotentialPayout = source.PotentialPayout,
182:                State = RevealedTicketState.Riding,
183:                Legs = legs
184:            };
185:        }
186:    }
