    /// <summary>
    /// DramaEvent → SceneSpec (F_0.2.0 M-T3): the ORDERED resolver over the actual event
    /// fields — not a flat key tuple. Total by construction over all 40 (Type × dir × Tag)
    /// combos; unreachable combos per generator invariants (BigPlay×Calm, Momentum×Swing,
    /// non-final Decisive) resolve through the same path with no special-casing, and the
    /// default arm falls back to #15 rather than throwing so future enum additions play.
    ///
    ///   1. Type == LegFinal → outcome scene. The UNSUSPENDED path chooses #12/#13 from the
    ///      revealed grade via <see cref="ResolveFinal"/>; <see cref="ResolveBeat"/> keeps the
    ///      resolver total by reading WinProbAfter (1.0 → Won). A SUSPENDED LegFinal's
    ///      continuation is chosen from the FINAL ticket-local grade after resolution —
    ///      never from WinProbAfter (single presentation authority).
    ///   2. Tag == NearMiss → #7 (up, "miracle brewing") / #8 (down, "slipping away").
    ///      Never a goal, regardless of Type.
    ///   3. Base scene by (Type, dir) — Score: #1/#2 · BigPlay: #3/#4 · Momentum: #5/#6
    ///      (Momentum with Tag==Calm uses the #11 calm variant).
    ///   4. Overlays (playback modifiers, never template choice): LeadChange → #9 intro,
    ///      Swing → #10 urgency.
    ///
    /// Pure C# — EditMode pins totality, goal staging, and the duration acceptance criterion.
    /// </summary>
    public sealed class TheaterChoreographer
    {
        private readonly SweatPacer _pacer;

        public TheaterChoreographer(SweatPacer pacer)
        {
            _pacer = pacer ?? new SweatPacer();
        }

        /// <summary>Resolves a beat. <paramref name="up"/> and <paramref name="delta"/> are the
        /// model's direction and signed movement (the one authority — BeatRecord);
        /// <paramref name="ledger"/> decides goal commit vs chalked-off, including the
        /// prob-reconciliation source whose sign gate needs the raw delta (flat ≠ up).</summary>
        public SceneSpec ResolveBeat(DramaEvent evt, bool up, double delta, ScoreLedger ledger)
        {
            int variant = ScenePlaybook.VariantFor(evt.Step);

            // 1. LegFinal — outcome scene (kept total here; the orchestrator's real final path
            //    goes through ResolveFinal with the revealed grade and the correction plan).
            if (evt.Type == DramaEventType.LegFinal)
            {
                SceneTemplate final = evt.WinProbAfter >= 0.5
                    ? SceneTemplate.LegFinalWon
                    : SceneTemplate.LegFinalLost;
                return new SceneSpec(final, variant, false, false,
                    final == SceneTemplate.LegFinalWon, null, _pacer.SceneSeconds(final, false));
            }

            // 2. NearMiss wins over the base table — never a goal, regardless of Type.
            if (evt.Tag == TensionTag.NearMiss)
            {
                SceneTemplate miss = up ? SceneTemplate.NearMissHope : SceneTemplate.NearMissScare;
                return new SceneSpec(miss, variant, false, false, up, null,
                    _pacer.SceneSeconds(miss, false));
            }

            // 3. Base scene by (Type, dir); 4. overlays never change the template.
            bool leadChange = evt.Tag == TensionTag.LeadChange;
            bool urgent = evt.Tag == TensionTag.Swing;
            SceneTemplate template = evt.Type switch
            {
                DramaEventType.Score => up ? SceneTemplate.GoalFor : SceneTemplate.GoalAgainst,
                DramaEventType.BigPlay => up ? SceneTemplate.BreakawayFor : SceneTemplate.BreakawayAgainst,
                DramaEventType.Momentum => evt.Tag == TensionTag.Calm
                    ? SceneTemplate.CalmPossession
                    : up ? SceneTemplate.TerritoryFor : SceneTemplate.TerritoryAgainst,
                _ => SceneTemplate.Fallback, // future enum additions play, never throw
            };

            // The ledger owns BOTH goal sources (type attribution + prob reconciliation,
            // playtest #14). A reconciliation goal on a momentum beat UPGRADES the scene to
            // the goal template — the board only ever moves behind a staged goal, and a goal
            // must look like one.
            ScoreLedger.StagedGoal? goal = ledger.StageBeatGoal(evt.Type, up, delta, evt.WinProbAfter);
            if (goal.HasValue && !ScenePlaybook.ProducesGoal(template))
                template = goal.Value.ForPicked ? SceneTemplate.GoalFor : SceneTemplate.GoalAgainst;

            return new SceneSpec(template, variant, leadChange, urgent, up, goal,
                _pacer.SceneSeconds(template, leadChange));
        }

        /// <summary>The real LegFinal staging: scene #12/#13 from the FINAL ticket-local grade,
        /// with the ledger's correction plan riding along. Works for both the unsuspended final
        /// and a suspended scene's continuation.</summary>
        public SceneSpec ResolveFinal(LegGrade grade, int step)
        {
            SceneTemplate template = grade == LegGrade.Won ? SceneTemplate.LegFinalWon : SceneTemplate.LegFinalLost;
            return new SceneSpec(template, ScenePlaybook.VariantFor(step), false, false,
                grade == LegGrade.Won, null, _pacer.SceneSeconds(template, false));
        }
    }
}

    ///    if the opponent is not already strictly ahead (already −1 ⇒ chalked at the death),
    ///    then correction goal(s) until the opponent is strictly ahead. Voided ⇒ the ledger
    ///    freezes as-is under the VOID treatment — no goals, no corrections.
    ///  - Goal-playback invariant: every increment maps 1:1 to a completed staged goal.
    /// </summary>
    public sealed class ScoreLedger
    {
        /// <summary>The live-lead clamp dial (±goals). 1 = one-goal-game stories.</summary>
        public int MaxLiveLead { get; set; } = 1;

        /// <summary>Committed goals for the picked side, this leg.</summary>
        public int Picked { get; private set; }

        /// <summary>Committed goals for the opponent, this leg.</summary>
        public int Opponent { get; private set; }

        /// <summary>Total committed goal playbacks this leg (the invariant's counter).</summary>
        public int CommittedGoals { get; private set; }

        /// <summary>A goal the choreographer staged: who it's for, and whether it commits
        /// (false = the chalked-off VAR-disallow variant — plays in full, never scores).</summary>
        public readonly struct StagedGoal
        {
            public readonly bool ForPicked;
            public readonly bool Commits;

            public StagedGoal(bool forPicked, bool commits)
            {
                ForPicked = forPicked;
                Commits = commits;
            }
        }

        /// <summary>The final whistle's staging order: the goals scene #12/#13 must play
        /// (killing shot first on a Lost, then corrections), each completed via
        /// <see cref="CompleteGoal"/> as its sub-scene finishes.</summary>
        public readonly struct FinalPlan
        {
            public readonly LegGrade Grade;
            public readonly StagedGoal[] Goals;

            public FinalPlan(LegGrade grade, StagedGoal[] goals)
            {
                Grade = grade;
                Goals = goals;
            }
        }

        /// <summary>Above this live prob the scoreboard must show the picked side ahead —
        /// the score is a lagging quantized rendering of the probability (playtest #14).</summary>
        public double ReconcileHighBand { get; set; } = 0.70;

        /// <summary>Below this live prob the scoreboard must show the opponent ahead.</summary>
        public double ReconcileLowBand { get; set; } = 0.30;

        /// <summary>Attribution + clamp for a non-final beat. Null = this beat stages no goal.
        ///
        /// Two goal sources (playtest #14 amendment — "the bar and the board must agree"):
        ///  1. Type attribution (the original law): Score/BigPlay beats stage a goal for the
        ///     beat's beneficiary.
        ///  2. Prob reconciliation: when the live probability says one side should be AHEAD
        ///     (outside the reconcile bands) and the board disagrees, a beat moving in that
        ///     direction stages the reconciling goal regardless of its type — the mid-leg
        ///     generalization of the final whistle's stoppage-time correction. Without this,
        ///     the board can read 0-0 at 90% or "leading" at 25%, which plays as fake.
        ///
        /// Near-miss exemption and the live-lead clamp are enforced by the caller/clamp as
        /// before; reconciliation targets ±1 so it can never violate the clamp.</summary>
        public StagedGoal? StageBeatGoal(DramaEventType type, bool up, double delta, double probAfter)
        {
            bool typeGoal = type == DramaEventType.Score || type == DramaEventType.BigPlay;
            if (typeGoal)
            {
                // Type goals keep the original direction rule (ties up — EventText's law);
                // their |delta| ≥ 0.07 means they are never actually flat.
                int typeLeadAfter = up ? Picked + 1 - Opponent : Opponent + 1 - Picked;
                return new StagedGoal(forPicked: up, commits: typeLeadAfter <= MaxLiveLead);
            }

            // The board the probability implies: +1 (picked ahead), -1 (opponent ahead), or
            // 0 (mid-band — any scoreline within the clamp is a fine story, including 1-0
            // either way; reconciliation never drags a natural lead back to level).
            //
            // Direction gate (Sol, M-T4.1): SIGN-COMPATIBILITY, not the tie-broken bool. A
            // flat beat (delta 0 — real inputs: paths riding the generator's 0.03/0.97
            // clamp) supports EITHER side's band; contrary motion never reconciles. Strict
            // inequality would leave a ceiling-riding 97% path unreconciled forever — the
            // exact dissonance this amendment exists to kill. The staged goal's direction
            // comes from the BAND, never from the tie-break.
            int impliedLead = probAfter >= ReconcileHighBand ? 1
                : probAfter <= ReconcileLowBand ? -1 : 0;
            int lead = Picked - Opponent;
            bool reconcileUp = impliedLead > 0 && lead < impliedLead && delta >= 0.0;
            bool reconcileDown = impliedLead < 0 && lead > impliedLead && delta <= 0.0;
            if (!reconcileUp && !reconcileDown) return null;

            bool forPicked = reconcileUp;
            int leadAfter = forPicked ? Picked + 1 - Opponent : Opponent + 1 - Picked;
            return new StagedGoal(forPicked, commits: leadAfter <= MaxLiveLead);
        }

        /// <summary>The ONLY score mutator — called when a staged goal's playback completes.
        /// A chalked-off goal (Commits false) completes without moving anything.</summary>
        public void CompleteGoal(StagedGoal goal)
        {
            if (!goal.Commits) return;
            if (goal.ForPicked) Picked++;
            else Opponent++;
            CommittedGoals++;
        }

        /// <summary>The stoppage-time staging order for a LegFinal, from the FINAL ticket-local
        /// grade (single presentation authority — a suspended scene's ending is never chosen
        /// from WinProbAfter). Pure planning: nothing commits until playback completes.</summary>
        public FinalPlan PlanFinal(LegGrade grade)
        {
            var goals = new System.Collections.Generic.List<StagedGoal>(3);
            int p = Picked, o = Opponent;
            switch (grade)
            {
                case LegGrade.Won:
                    while (p <= o) { goals.Add(new StagedGoal(true, true)); p++; }
                    break;
                case LegGrade.Lost:
                    // The killing shot commits only if the opponent is not already strictly
                    // ahead; otherwise it stages chalked-off — disallowed at the death, the
                    // whistle still confirms Lost. MaxLiveLead is never violated.
                    bool killingCommits = o <= p;
                    goals.Add(new StagedGoal(false, killingCommits));
                    if (killingCommits) o++;
                    while (o <= p) { goals.Add(new StagedGoal(false, true)); o++; }
                    break;
                case LegGrade.Voided:
                default:
                    break; // the scoreline freezes as-is under the cyan VOID treatment
            }
            return new FinalPlan(grade, goals.ToArray());
        }

        /// <summary>New leg, new match: the scoreline resets.</summary>
        public void ResetForLeg()
        {
            Picked = 0;
            Opponent = 0;
            CommittedGoals = 0;
        }
    }

    /// <summary>
    /// The theater's team-color law (F_0.2.0): colors come from a fixed pool that excludes
    /// every reserved signal color — phosphor green (money-good), hot red (money-bad),
    /// gold (cash-out), cyan (VOID). Assignment is deterministic from the team NAME
    /// (FNV-1a, presentation-local — a team keeps its color across rounds and replays,
    /// no engine RNG involved); the away team takes the next distinct pool entry.
    /// </summary>
    public static class TheaterPalette
    {
        /// <summary>0xRRGGBB. Electric blue, magenta, orange, violet, broadcast white.</summary>
        public static readonly uint[] TeamPool = { 0x3D7BFF, 0xE84DD0, 0xFF8A2B, 0x9B5CF6, 0xF0F3F6 };

        public static (uint Home, uint Away) TeamColors(string homeName, string awayName)
        {
            int home = (int)(Fnv1a(homeName ?? string.Empty) % (uint)TeamPool.Length);
            int away = (int)(Fnv1a(awayName ?? string.Empty) % (uint)TeamPool.Length);
            if (away == home) away = (away + 1) % TeamPool.Length;
            return (TeamPool[home], TeamPool[away]);
        }

        private static uint Fnv1a(string s)
        {
            unchecked
            {
                uint h = 2166136261;
                for (int i = 0; i < s.Length; i++)
                {
                    h ^= s[i];
                    h *= 16777619;
                }
                return h;
            }
        }
    }
}

using System;
using UnityEngine;

namespace SBR.Game
{
    /// <summary>
    /// Procedural, diegetic audio for the TV sweat. The director owns its sources and clips so the
    /// graybox room needs no audio assets. It is presentation-only: it never changes the engine
    /// cursor or waits for a sound to finish.
    /// </summary>
    public sealed class TvAudioDirector : MonoBehaviour
    {
        public float masterVolume = 0.5f;
        public float crowdVolume = 0.6f;
        public float stingVolume = 0.8f;

        private const int SampleRate = 44100;
        private const float CrowdSeconds = 6f;
        private const float RiserSeconds = 8f;

        private AudioSource _crowdSource;
        private AudioSource _stingSource;
        private AudioSource _riserSource;
        private AudioLowPassFilter _crowdFilter;

        private AudioClip _crowdClip;
        private AudioClip _goalClip;
        private AudioClip _chalkedGoalClip;
        private AudioClip _riserClip;
        private AudioClip _whistleClip;
        private AudioClip _slamWonClip;
        private AudioClip _slamLostClip;
        private AudioClip _cashOutClip;

        private bool _shown;
        private float _crowdTarget;
        private float _crowdCurrent;
        private float _cutoffTarget = 650f;
        private float _cutoffCurrent = 650f;
        private float _duckTarget = 1f;
        private float _duckCurrent = 1f;
        private float _duckSeconds = 0.8f;
        private float _crowdDeflation = 1f;

        /// <summary>Creates the director and places all sources on the TV anchor.</summary>
        public static TvAudioDirector Build(Transform tvAnchor)
        {
            if (tvAnchor == null) return null;

            var go = new GameObject("TvAudioDirector", typeof(TvAudioDirector));
            go.transform.SetParent(tvAnchor, false);
            var director = go.GetComponent<TvAudioDirector>();

            // The crowd lives on its OWN child object: Unity audio filter components process
            // every AudioSource on their GameObject, and the 400-900Hz crowd low-pass would
            // otherwise mud the 1850Hz whistle and every sting (Fable review, M-T5).
            var crowdGo = new GameObject("CrowdBed");
            crowdGo.transform.SetParent(go.transform, false);
            director._crowdSource = ConfigureSource(crowdGo.AddComponent<AudioSource>());
            director._crowdFilter = crowdGo.AddComponent<AudioLowPassFilter>();
            director._crowdFilter.cutoffFrequency = director._cutoffCurrent;
            director._crowdFilter.lowpassResonanceQ = 1f;

            director._stingSource = ConfigureSource(go.AddComponent<AudioSource>());
            director._riserSource = ConfigureSource(go.AddComponent<AudioSource>());

            director._crowdClip = BuildCrowdBed();
            director._goalClip = BuildGoalClip(true);
            director._chalkedGoalClip = BuildGoalClip(false);
            director._riserClip = BuildRiserClip();
            director._whistleClip = BuildWhistleClip();
            director._slamWonClip = BuildSlamWonClip();
            director._slamLostClip = BuildSlamLostClip();
            director._cashOutClip = BuildCashOutClip();

            director._crowdSource.clip = director._crowdClip;
            director._crowdSource.loop = true;
            director._riserSource.clip = director._riserClip;
            director.ApplySourceVolumes();
            return director;
        }

        private static AudioSource ConfigureSource(AudioSource source)
        {
            source.playOnAwake = false;
            source.spatialBlend = 0.8f;
            source.dopplerLevel = 0f;
            source.rolloffMode = AudioRolloffMode.Linear;
            source.minDistance = 0.4f;
            source.maxDistance = 18f;
            return source;
        }

        /// <summary>
        /// Tracks live danger and scene urgency. Parameter motion is smoothed here so the crowd
        /// swells rather than stepping with the probability bar.
        /// </summary>
        public void SetTension(float danger01, float urgency01)
        {
            danger01 = Mathf.Clamp01(danger01);
            urgency01 = Mathf.Clamp01(urgency01);
            float tension = Mathf.Clamp01(Mathf.Max(danger01, urgency01 * 0.85f));
            _crowdTarget = Mathf.Clamp01(crowdVolume) * (0.16f + tension * 0.84f);
            _cutoffTarget = Mathf.Lerp(400f, 900f, tension);

            float dt = Time.unscaledDeltaTime;
            float blend = dt <= 0f ? 0f : 1f - Mathf.Exp(-dt / 0.5f);
            _crowdCurrent = Mathf.Lerp(_crowdCurrent, _crowdTarget, blend);
            _cutoffCurrent = Mathf.Lerp(_cutoffCurrent, _cutoffTarget, blend);
            _crowdDeflation = Mathf.MoveTowards(_crowdDeflation, 1f, dt / 0.9f);
            if (_crowdFilter != null) _crowdFilter.cutoffFrequency = _cutoffCurrent;
            ApplySourceVolumes();
        }

        /// <summary>Applies the fast duck / slow recover dread floor.</summary>
        public void Duck(bool ducked, float seconds)
        {
            _duckTarget = ducked ? 0.025f : 1f;
            _duckSeconds = Mathf.Max(0.01f, seconds);
            float dt = Time.unscaledDeltaTime;
            if (dt > 0f)
                _duckCurrent = Mathf.MoveTowards(_duckCurrent, _duckTarget, dt / _duckSeconds);
            ApplySourceVolumes();
        }

        public void GoalHit(bool commits)
        {
            PlayOneShot(_stingSource, commits ? _goalClip : _chalkedGoalClip);
        }

        public void NearMissRiser(float seconds)
        {
            Stop(_riserSource);
            if (!_shown || _riserClip == null) return;
            _riserSource.pitch = Mathf.Clamp(RiserSeconds / Mathf.Max(0.05f, seconds), 0.05f, 3f);
            Play(_riserSource);
        }

        public void CutRiser()
        {
            Stop(_riserSource);
            if (_riserSource != null) _riserSource.pitch = 1f;
        }

        public void Whistle() => PlayOneShot(_stingSource, _whistleClip);

        public void SlamWon() => PlayOneShot(_stingSource, _slamWonClip);

        public void SlamLost()
        {
            _crowdDeflation = 0.08f;
            PlayOneShot(_stingSource, _slamLostClip);
        }

        public void CashOutKaChunk() => PlayOneShot(_stingSource, _cashOutClip);

        /// <summary>Shows or silences the TV's entire audio stack.</summary>
        public void Show(bool visible)
        {
            _shown = visible;
            if (!visible)
            {
                Stop(_crowdSource);
                Stop(_stingSource);
                Stop(_riserSource);
                if (_riserSource != null) _riserSource.pitch = 1f;
                return;
            }

            _duckTarget = 1f;
            _duckCurrent = 1f;
            _crowdDeflation = 1f;
            if (_crowdSource != null && !_crowdSource.isPlaying)
                Play(_crowdSource);
        }

        private void OnDisable() => Show(false);

        private void ApplySourceVolumes()
        {
            float master = Mathf.Clamp01(masterVolume) * _duckCurrent;
            if (_crowdSource != null)
                _crowdSource.volume = master * _crowdCurrent * _crowdDeflation;
            if (_stingSource != null) _stingSource.volume = master * Mathf.Clamp01(stingVolume);
            if (_riserSource != null) _riserSource.volume = master * Mathf.Clamp01(stingVolume);
        }

        private void Play(AudioSource source)
        {
            if (!_shown || source == null || Application.isBatchMode) return;
            try { source.Play(); } catch (Exception) { }
        }

        private void PlayOneShot(AudioSource source, AudioClip clip)
        {
            if (!_shown || source == null || clip == null || Application.isBatchMode) return;
            try { source.PlayOneShot(clip); } catch (Exception) { }
        }

        private static void Stop(AudioSource source)
        {
            if (source == null || Application.isBatchMode) return;
            try { source.Stop(); } catch (Exception) { }
        }

        private static AudioClip BuildCrowdBed()
        {
            int samples = Mathf.RoundToInt(CrowdSeconds * SampleRate);
            var data = new float[samples];
            var random = new System.Random(0x53425241);
            float filtered = 0f;
            float cutoff = 650f;
            float alpha = 1f - Mathf.Exp(-2f * Mathf.PI * cutoff / SampleRate);
            for (int i = 0; i < samples; i++)
            {
                float white = (float)(random.NextDouble() * 2.0 - 1.0);
                filtered += alpha * (white - filtered);
                float t = (float)i / SampleRate;
                float swell = 0.68f + 0.22f * Mathf.Sin(t * 2f * Mathf.PI * 0.11f)
                    + 0.10f * Mathf.Sin(t * 2f * Mathf.PI * 0.047f + 1.2f);
                data[i] = filtered * swell * 0.48f;
            }

            // A short crossfade keeps the loop boundary from clicking.
            int fade = Mathf.Min(SampleRate / 12, samples / 2);
            float boundary = (data[0] + data[samples - 1]) * 0.5f;
            for (int i = 0; i < fade; i++)
            {
                float t = (float)i / Mathf.Max(1, fade - 1);
                float blend = Mathf.SmoothStep(0f, 1f, t);
                data[i] = Mathf.Lerp(boundary, data[i], blend);
                data[samples - fade + i] = Mathf.Lerp(data[samples - fade + i], boundary, blend);
            }
            return CreateClip("CrowdBed", data);
        }

        private static AudioClip BuildGoalClip(bool commits)
        {
            float seconds = 0.85f;
            int samples = Mathf.RoundToInt(seconds * SampleRate);
            var data = new float[samples];
            var random = new System.Random(commits ? 0x474F414C : 0x4348414C);
            float filtered = 0f;
            for (int i = 0; i < samples; i++)
            {
                float t = (float)i / SampleRate;
                float thumpT = Mathf.Min(1f, t / 0.22f);
                float thumpFreq = commits ? Mathf.Lerp(105f, 48f, thumpT) : Mathf.Lerp(125f, 62f, thumpT);
                float thump = Mathf.Sin(2f * Mathf.PI * thumpFreq * t) * Mathf.Exp(-13f * t) * 0.85f;
                float roarT = Mathf.Clamp01((t - 0.06f) / (commits ? 0.74f : 0.26f));
                float roarEnvelope = roarT * (1f - roarT) * 4f;
                float white = (float)(random.NextDouble() * 2.0 - 1.0);
                filtered += 0.12f * (white - filtered);
                float roar = filtered * roarEnvelope * (commits ? 0.95f : 0.58f);
                float groan = commits ? 0f
                    : Mathf.Sin(2f * Mathf.PI * Mathf.Lerp(190f, 72f, roarT) * t)
                        * roarT * Mathf.Exp(-2.5f * t) * 0.42f;
                data[i] = Mathf.Clamp(thump + roar + groan, -1f, 1f);
            }
            return CreateClip(commits ? "GoalHit" : "ChalkedGoal", data);
        }

        private static AudioClip BuildRiserClip()
        {
            int samples = Mathf.RoundToInt(RiserSeconds * SampleRate);
            var data = new float[samples];
            for (int i = 0; i < samples; i++)
            {
                float t = (float)i / SampleRate;
                float progress = t / RiserSeconds;
                float freq = 170f * Mathf.Pow(5.5f, progress);
                float envelope = 0.06f + 0.42f * progress;
                data[i] = (Mathf.Sin(2f * Mathf.PI * freq * t)
                    + 0.35f * Mathf.Sin(2f * Mathf.PI * freq * 2.01f * t)) * envelope;
            }
            return CreateClip("NearMissRiser", data);
        }

        private static AudioClip BuildWhistleClip()
        {
            float seconds = 0.72f;
            int samples = Mathf.RoundToInt(seconds * SampleRate);
            var data = new float[samples];
            for (int i = 0; i < samples; i++)
            {
                float t = (float)i / SampleRate;
                int peep = Mathf.FloorToInt(t / 0.23f);
                float local = t - peep * 0.23f;
                float envelope = peep < 3 && local < 0.12f
                    ? Mathf.Sin(Mathf.Clamp01(local / 0.012f) * Mathf.PI * 0.5f)
                    * (1f - Mathf.Clamp01((local - 0.08f) / 0.04f)) : 0f;
                data[i] = Mathf.Sign(Mathf.Sin(2f * Mathf.PI * 1850f * t)) * envelope * 0.28f;
            }
            return CreateClip("Whistle", data);
        }

        private static AudioClip BuildSlamWonClip()
        {
            float seconds = 0.9f;
            int samples = Mathf.RoundToInt(seconds * SampleRate);
            var data = new float[samples];
            float[] notes = { 523.25f, 659.25f, 783.99f };
            for (int i = 0; i < samples; i++)
            {
                float t = (float)i / SampleRate;
                float envelope = Mathf.Sin(Mathf.Clamp01(t / seconds) * Mathf.PI) * 0.55f;
                float body = 0f;
                for (int n = 0; n < notes.Length; n++)
                    body += Mathf.Sin(2f * Mathf.PI * notes[n] * t) / notes.Length;
                data[i] = body * envelope;
            }
            return CreateClip("SlamWon", data);
        }

        private static AudioClip BuildSlamLostClip()
        {
            float seconds = 0.8f;
            int samples = Mathf.RoundToInt(seconds * SampleRate);
            var data = new float[samples];
            for (int i = 0; i < samples; i++)
            {
                float t = (float)i / SampleRate;
                float envelope = Mathf.Exp(-5.5f * t);
                data[i] = (Mathf.Sin(2f * Mathf.PI * 74f * t)
                    + 0.28f * Mathf.Sin(2f * Mathf.PI * 39f * t)) * envelope * 0.62f;
            }
            return CreateClip("SlamLost", data);
        }

        private static AudioClip BuildCashOutClip()
        {
            float seconds = 0.46f;
            int samples = Mathf.RoundToInt(seconds * SampleRate);
            var data = new float[samples];
            var random = new System.Random(0x4B414348);
            float filtered = 0f;
            for (int i = 0; i < samples; i++)
            {
                float t = (float)i / SampleRate;
                float click1 = Mathf.Exp(-Mathf.Abs(t - 0.045f) * 420f);
                float click2 = Mathf.Exp(-Mathf.Abs(t - 0.105f) * 420f);
                float white = (float)(random.NextDouble() * 2.0 - 1.0);
                filtered += 0.22f * (white - filtered);
                float clicks = filtered * (click1 + click2) * 0.5f;
                float thunk = Mathf.Sin(2f * Mathf.PI * 82f * Mathf.Max(0f, t - 0.17f))
                    * Mathf.Exp(-10f * Mathf.Max(0f, t - 0.17f));
                data[i] = Mathf.Clamp(clicks + thunk * 0.55f, -1f, 1f);
            }
            return CreateClip("CashOutKaChunk", data);
        }

        private static AudioClip CreateClip(string name, float[] data)
        {
            AudioClip clip = AudioClip.Create(name, data.Length, 1, SampleRate, false);
            clip.SetData(data, 0);
            return clip;
        }
    }
}

using System;

namespace SBR.Game
{
    /// <summary>
    /// The theater's tempo (F_0.2.0 M-T3): resolved-scene-class → seconds. All dials, all
    /// presentation config — the engine never sees these. Serialized on TvSweatScreen so
    /// Allen tunes them at the M-T3 gate; pure C# (no UnityEngine) so EditMode pins the
    /// bands: every beat-scene lands in [3, 8]s, ledger-correction goals are separately
    /// timed sub-scenes (2.5s each, at most 2 by the clamp), so a full final whistle
    /// sequence may run 8–13s — the slowest moment is deliberately the reveal.
    /// </summary>
    [Serializable]
    public sealed class SweatPacer
    {
        public float territorySeconds = 3.0f;
        public float calmSeconds = 3.0f;
        public float goalSeconds = 4.5f;
        public float breakawaySeconds = 5.0f;
        /// <summary>#9 overlay: the steal → transition intro adds this on top of the base scene.</summary>
        public float leadChangeIntroExtra = 0.8f;
        public float nearMissSeconds = 6.5f;
        /// <summary>The dead-air hold after the ball skims wide / hits the bar.</summary>
        public float nearMissHold = 0.5f;
        /// <summary>LegFinal base (pre-reveal hold + decisive sequence + whistle), before corrections.</summary>
        public float legFinalSeconds = 7.5f;
        /// <summary>Each ledger-correction goal, appended to the LegFinal as its own sub-scene.</summary>
        public float correctionGoalSeconds = 2.5f;
        public float fallbackSeconds = 3.0f;
        /// <summary>Structural kickoff/restart (#14) — outside the beat-scene band by classification.</summary>
        public float kickoffSeconds = 1.5f;
        /// <summary>Single presentation tempo dial. Values below 1 make every scene and
        /// correction sub-scene shorter without changing their relative tuning.</summary>
        public float paceMultiplier = 0.75f;

        /// <summary>The BEAT-SCENE duration for a resolved template (+overlays). Near-miss
        /// includes its hold; finals return their base — corrections are added by
        /// <see cref="FinalSceneSeconds"/>.</summary>
        public float SceneSeconds(SceneTemplate template, bool leadChangeIntro)
        {
            float s = template switch
            {
                SceneTemplate.GoalFor => goalSeconds,
                SceneTemplate.GoalAgainst => goalSeconds,
                SceneTemplate.BreakawayFor => breakawaySeconds,
                SceneTemplate.BreakawayAgainst => breakawaySeconds,
                SceneTemplate.TerritoryFor => territorySeconds,
                SceneTemplate.TerritoryAgainst => territorySeconds,
                SceneTemplate.NearMissHope => nearMissSeconds + nearMissHold,
                SceneTemplate.NearMissScare => nearMissSeconds + nearMissHold,
                SceneTemplate.CalmPossession => calmSeconds,
                SceneTemplate.LegFinalWon => legFinalSeconds,
                SceneTemplate.LegFinalLost => legFinalSeconds,
                SceneTemplate.Kickoff => kickoffSeconds,
                _ => fallbackSeconds,
            };
            if (leadChangeIntro) s += leadChangeIntroExtra;
            return s * paceMultiplier;
        }

        /// <summary>The full final whistle sequence: base + one sub-scene per staged correction
        /// goal (the killing shot on a Lost is one of them).</summary>
        public float FinalSceneSeconds(int stagedGoals)
            => (legFinalSeconds + stagedGoals * correctionGoalSeconds) * paceMultiplier;
    }
}

        /// <summary>Freeze mid-motion (stand-up pause). The stage holds its exact frame.</summary>
        public void SetFrozen(bool frozen) => _frozen = frozen;

        public void Show(bool visible)
        {
            if (gameObject.activeSelf != visible) gameObject.SetActive(visible);
            if (!visible)
            {
                _live = false;
                CancelScene();
            }
        }

        // ------------------------------------------------------------------ scene playback (M-T3)

        /// <summary>Plays a resolved beat scene. <paramref name="onGoalPlayed"/> fires when a
        /// staged goal's playback completes (commit AND chalked — the ledger sorts them);
        /// <paramref name="onReveal"/> fires exactly once at the scene's payoff moment (the
        /// goal, the save, or scene end for territory shapes) — the causally honest instant
        /// for the chrome to speak; <paramref name="onComplete"/> when the script exhausts.
        /// Poll <see cref="ScenePlaying"/>.</summary>
        public void PlayScene(SceneSpec spec, Action<ScoreLedger.StagedGoal> onGoalPlayed,
            Action onReveal, Action onComplete)
        {
            StartScript(BuildBeatScript(spec), onGoalPlayed, onReveal, onComplete);
        }

        /// <summary>Plays the final whistle sequence: pre-reveal hold → the plan's staged
        /// goal(s) as separately-timed sub-scenes → celebrate/collapse. The GREEN/DEAD slam
        /// and the final chrome reveal belong to the orchestrator at completion (TvLight sync).</summary>
        public void PlayFinalScene(SceneSpec spec, ScoreLedger.FinalPlan plan,
            Action<ScoreLedger.StagedGoal> onGoalPlayed, Action onComplete)
        {
            StartScript(BuildFinalScript(spec, plan), onGoalPlayed, null, onComplete);
        }

        /// <summary>The pending-loss window's kill scene: opponent buildup → shot launched →
        /// FROZEN at the suspension point, mid-flight. Holds until <see cref="ResumeSuspended"/>.</summary>
        public void SuspendKillShot(int variant)
        {
            StartScript(BuildKillShotScript(variant), null, null, null);
        }

        /// <summary>The suspended scene's continuation, chosen from the FINAL ticket-local grade
        /// (never WinProbAfter): Voided → cyan VOID dissolve, no goals; Won → the frozen shot
        /// resolves as a save, then the counter goal(s) the correction needs; Lost → the flight
        /// completes (chalked if the entry score already satisfied Lost), then corrections.</summary>
        public void ResumeSuspended(ScoreLedger.FinalPlan plan,
            Action<ScoreLedger.StagedGoal> onGoalPlayed, Action onComplete)
        {
            _suspendedAtShot = false;
            StartScript(BuildContinuationScript(plan), onGoalPlayed, null, onComplete);
        }

        /// <summary>Abandons any active scene without completing it (cash-out, leg change).</summary>
        public void CancelScene()
        {
            _script = null;
            _stepIx = 0;
            _stepT = 0f;
            _stepEntered = false;
            _suspendedAtShot = false;
            _onGoalPlayed = null;
            _onReveal = null;
            _revealFired = false;
            _onSceneComplete = null;
        }

        private void StartScript(Step[] script, Action<ScoreLedger.StagedGoal> onGoalPlayed,
            Action onReveal, Action onComplete)
        {
            _script = script;
            _stepIx = 0;
            _stepT = 0f;
            _stepEntered = false;
            _suspendedAtShot = false;
            _onGoalPlayed = onGoalPlayed;
            _onReveal = onReveal;
            _revealFired = false;
            _onSceneComplete = onComplete;
        }

        // ------------------------------------------------------------------ update

        private void Update()
        {
            if (!_live || _frozen) return;
            float dt = Time.deltaTime;
            UpdateFlash(dt);

            if (_script != null) UpdateScene(dt);
            else UpdateIdle(dt);
        }

        private void UpdateScene(float dt)
        {
            if (_suspendedAtShot) return; // the frozen shot — the window's dread

            if (!_stepEntered) EnterStep();
            Step s = _script[_stepIx];

            // Motion (real frame time — cosmetic): formations speak the scene's territory,
            // the ball travels its routed target, tempo scales everything.
            float speed = 1f + s.Tempo * 1.6f;
            _sceneTerr = Mathf.SmoothDamp(_sceneTerr, s.Terr, ref _sceneTerrVel, 0.45f / speed);
            LastTerritoryX = _sceneTerr;
            MoveActors(_sceneTerr, speed, s.Chase, s.AtkPicked, dt);

            Vector2 target = _routeDotIx >= 0 ? DotPos(_routeDotHome, _routeDotIx) : _stepBallLocal;
            _ballPos = Vector2.SmoothDamp(_ballPos, target, ref _ballVel, ballDamp / speed);
            ApplyPositions();

            // Story time (scaled — batch tests fast-forward through here by shrinking the
            // effective duration, exactly like SeatedHold does with TimeScaleOverride).
            _stepT += dt;
            if (_stepT < s.Dur * Mathf.Max(0f, timeScale)) return;

            CompleteStep(s);
            if (_suspendedAtShot) return; // MkSuspend holds ON its step until resumed

            _stepIx++;
            _stepT = 0f;
            _stepEntered = false;
            if (_stepIx >= _script.Length)
            {
                _script = null;
                FireReveal(); // scenes with no explicit payoff reveal at their end
                Action done = _onSceneComplete;
                _onGoalPlayed = null;
                _onReveal = null;
                _onSceneComplete = null;
                done?.Invoke();
            }
        }

        /// <summary>Resolves the step's ball routing against the ACTUAL actors — the move must
        /// read as the attacking team passing it around, never a ball flying to nobody.</summary>
        private void EnterStep()
        {
            _stepEntered = true;
            Step s = _script[_stepIx];
            bool atkHome = s.AtkPicked == _homeAttacksRight;
            _routeDotIx = -1;

            switch (s.Route)
            {
                case RoutePass:
                {
                    Vector2 want = ToLocal(s.Ball);
                    int ix = NearestOutfield(atkHome, want, exclude: BallCarriedBy(atkHome) ? _carrierIx : -1);
                    _routeDotIx = ix;
                    _routeDotHome = atkHome;
                    // Off-ball: teammates near the move make short forward runs, not static jitter.
                    ForwardRuns(atkHome, s.AtkPicked ? 1f : -1f);
                    break;
                }
                case RouteBackLine:
                {
                    Vector2 want = ToLocal(s.Ball);
                    _routeDotIx = NearestBackLine(!atkHome, want);
                    _routeDotHome = !atkHome;
                    break;
                }
                case RouteShot:
                {
                    // Aim at the corner AWAY from the defending keeper — a shot, not a pass.
                    Vector2 authored = s.Ball;
                    bool rightGoal = authored.x > 0.5f;
                    Vector2 keeper = rightGoal
                        ? (_homeAttacksRight ? _akPos : _hkPos)
                        : (_homeAttacksRight ? _hkPos : _akPos);
                    authored.y = keeper.y > 0f ? 0.42f : 0.58f;
                    _stepBallLocal = ToLocal(authored);
                    break;
                }
                case RouteKickoff:
                default:
                    _stepBallLocal = ToLocal(s.Ball);
                    break;
            }
        }

        /// <summary>End-of-step bookkeeping: markers fire, and possession follows the story so
        /// the idle loop resumes from a coherent carrier.</summary>
        private void CompleteStep(Step s)
        {
            switch (s.Marker)
            {
                case MkGoal:
                    FlashGoal(right: s.Ball.x > 0.5f, strong: s.Goal.Commits);
                    _onGoalPlayed?.Invoke(s.Goal);
                    FireReveal(); // the net ripple IS the beat's payoff
                    break;
                case MkSuspend:
                    _suspendedAtShot = true;
                    break;
                case MkSave:
                    KeeperLunge();
                    FireReveal(); // the save IS the near-miss payoff
                    break;
                case MkVoid:
                    ApplyVoidTint();
                    break;
            }

            switch (s.Route)
            {
                case RoutePass:
                case RouteBackLine:
                    if (_routeDotIx >= 0)
                    {
                        _carrierHome = _routeDotHome;
                        _carrierIx = _routeDotIx;
                    }
                    break;
                case RouteKickoff:
                    // The side that just conceded collects at the center spot.
                    _carrierHome = s.AtkPicked != _homeAttacksRight;
                    _carrierIx = 4;
                    break;
            }
        }

        private void FireReveal()
        {
            if (_revealFired) return;
            _revealFired = true;
            _onReveal?.Invoke();
        }

        private void UpdateIdle(float dt)
        {
            _pulse = Mathf.MoveTowards(_pulse, 0f, dt / Mathf.Max(0.01f, pulseDecay));
            _urgency = Mathf.MoveTowards(_urgency, 0f, dt * 0.5f);

            // Territory: the honest prob, plus the decaying beat impulse. The picked side
            // attacks right, so territoryX already speaks the pick's language.
            float terr = PitchLayout.TerritoryX(_prob) + _pulse * _pulseSign * pulseKick;
            terr = Mathf.Clamp(terr, 0.08f, 0.92f);
            _sceneTerr = terr; // scenes resume smoothly from wherever idle left the shape
            LastTerritoryX = terr;

            float speed = 1f + _urgency * 1.4f;
            MoveActors(terr, speed, chase: false, atkPicked: terr >= 0.5f, dt);

            // Sticky possession: the carrier keeps it, passes go to TEAMMATES, and turnovers
            // are visible interceptions. Long-run possession share restates the live prob
            // (allowed: it repeats revealed state) — nothing here ever implies a goal.
            if (Time.time >= _nextPassAt)
            {
                _nextPassAt = Time.time + NextPassDelay() / speed;
                float share = Mathf.Lerp(0.25f, 0.75f, _prob); // picked side's possession target
                bool carrierPicked = _carrierHome == _homeAttacksRight;
                float keep = carrierPicked
                    ? Mathf.Lerp(0.55f, 0.92f, share)
                    : Mathf.Lerp(0.55f, 0.92f, 1f - share);
                if (_rng.NextDouble() < keep) PassToTeammate(terr);
                else TurnoverAtBall();
            }

            _ballPos = Vector2.SmoothDamp(_ballPos, DotPos(_carrierHome, _carrierIx), ref _ballVel, ballDamp / speed);
            ApplyPositions();
        }

        /// <summary>A pass within the team in possession: best of three candidates, preferring
        /// a comfortable pass length and progress toward the territory point.</summary>
        private void PassToTeammate(float terr)
        {
            Vector2 from = DotPos(_carrierHome, _carrierIx);
            float terrX = (terr - 0.5f) * (_w - Pad * 2f);
            int best = -1;
            float bestScore = float.NegativeInfinity;
            for (int tries = 0; tries < 3; tries++)
            {
                int c = _rng.Next(PitchLayout.OutfieldPerTeam);
                if (c == _carrierIx) continue;
                Vector2 p = DotPos(_carrierHome, c);
                float dist = Vector2.Distance(from, p);
                if (dist < 24f) continue; // no toe-pokes to a dot standing on the ball
                float lengthScore = -Mathf.Abs(dist - 120f) * 0.01f;          // comfortable pass
                float progressScore = -Mathf.Abs(p.x - terrX) * 0.008f;       // toward the action
                float score = lengthScore + progressScore;
                if (score > bestScore) { bestScore = score; best = c; }
            }
            if (best >= 0) _carrierIx = best;
        }

        /// <summary>A visible turnover: the nearest opponent steps INTO the ball and takes it —
        /// possession flips because somebody won it, not because the script blinked.</summary>
        private void TurnoverAtBall()
        {
            bool interceptorHome = !_carrierHome;
            int ix = NearestOutfield(interceptorHome, _ballPos, exclude: -1);
            ref Vector2 vel = ref (interceptorHome ? ref _homeVel[ix] : ref _awayVel[ix]);
            Vector2 toBall = _ballPos - DotPos(interceptorHome, ix);
            vel += toBall.normalized * Mathf.Min(toBall.magnitude * 4f, 220f);
            _carrierHome = interceptorHome;
            _carrierIx = ix;
        }

        /// <summary>Formation motion shared by idle and scenes: each dot has its own lagged
        /// territory response and noise clock, while the nearest defenders engage the carrier
        /// goal-side instead of letting the midfield line watch the move from a rigid block.</summary>
        private void MoveActors(float terr, float speed, bool chase, bool atkPicked, float dt)
        {
            float bias = (terr - 0.5f) * 2f; // [-1, 1] toward the right goal (picked frame)

            // Per-team posture: positive = on the front foot, negative = under siege.
            float homeAtk = _homeAttacksRight ? bias : -bias;
            float awayAtk = -homeAtk;
            bool inScene = _script != null;
            bool defendingHome = inScene ? atkPicked != _homeAttacksRight : !_carrierHome;
            int engaged1, engaged2, engaged3;
            FindNearestThree(defendingHome, _ballPos, out engaged1, out engaged2, out engaged3);
            int engagementCount = inScene ? (chase ? 2 : 3) : 1;
            float engagementStrength = inScene ? 1f : 0.45f;

            UpdateNoise(_homeNoise, _homeNoiseTimer, dt);
            UpdateNoise(_awayNoise, _awayNoiseTimer, dt);

            for (int i = 0; i < PitchLayout.OutfieldPerTeam; i++)
            {
                float homeBias = Mathf.SmoothDamp(_homeShapeBias[i], homeAtk,
                    ref _homeShapeBiasVel[i], ShapeDamp(true, i, speed), 4f, dt);
                float awayBias = Mathf.SmoothDamp(_awayShapeBias[i], awayAtk,
                    ref _awayShapeBiasVel[i], ShapeDamp(false, i, speed), 4f, dt);
                _homeShapeBias[i] = homeBias;
                _awayShapeBias[i] = awayBias;

                bool homeEngages = defendingHome && engagementCount > 0
                    && IsEngaged(i, engaged1, engaged2, engaged3, engagementCount);
                bool awayEngages = !defendingHome && engagementCount > 0
                    && IsEngaged(i, engaged1, engaged2, engaged3, engagementCount);
                Vector2 ht = homeEngages
                    ? DefensiveEngagementTarget(true, RankOf(i, engaged1, engaged2, engaged3), engagementStrength)
                    : ToLocal(PitchLayout.FormationSlot(i, _homeAttacksRight, homeBias,
                        Mathf.Clamp01(-homeBias) * 0.8f)) + _homeNoise[i];
                Vector2 at = awayEngages
                    ? DefensiveEngagementTarget(false, RankOf(i, engaged1, engaged2, engaged3), engagementStrength)
                    : ToLocal(PitchLayout.FormationSlot(i, !_homeAttacksRight, awayBias,
                        Mathf.Clamp01(-awayBias) * 0.8f)) + _awayNoise[i];
                _homePos[i] = Vector2.SmoothDamp(_homePos[i], ht, ref _homeVel[i],
                    PositionDamp(true, i, speed), MaxDotSpeed(speed), dt);
                _awayPos[i] = Vector2.SmoothDamp(_awayPos[i], at, ref _awayVel[i],
                    PositionDamp(false, i, speed), MaxDotSpeed(speed), dt);
            }
            _hkPos = Vector2.SmoothDamp(_hkPos, ToLocal(PitchLayout.Keeper(_homeAttacksRight)),
                ref _hkVel, dotDamp / speed, MaxDotSpeed(speed), dt);
            _akPos = Vector2.SmoothDamp(_akPos, ToLocal(PitchLayout.Keeper(!_homeAttacksRight)),
                ref _akVel, dotDamp / speed, MaxDotSpeed(speed), dt);
        }

        private float PositionDamp(bool home, int index, float speed)
            => Mathf.Max(0.01f, dotDamp * ReactionLag(home, index) / speed);

        private float ShapeDamp(bool home, int index, float speed)
        {
            // The back line absorbs shape changes last; midfielders carry the wave and
            // forwards can make the quickest read of a territory shift.
            float lineFactor = PitchLayout.IsBackLine(index) ? 1.15f : index < 6 ? 1f : 0.85f;
            return Mathf.Max(0.01f, dotDamp * ReactionLag(home, index) * lineFactor / speed);
        }

        private float ReactionLag(bool home, int index)
            => home ? _homeReactionLag[index] : _awayReactionLag[index];

        private float MaxDotSpeed(float speed)
            => Mathf.Lerp(300f, 380f, Mathf.Clamp01((speed - 1f) / 1.6f));

        private static bool IsEngaged(int index, int first, int second, int third, int count)
            => index == first || (count > 1 && index == second) || (count > 2 && index == third);

        private static int RankOf(int index, int first, int second, int third)
            => index == first ? 0 : index == second ? 1 : index == third ? 2 : 0;

        private Vector2 DefensiveEngagementTarget(bool defendingHome, int rank, float strength)
        {
            bool attacksRight = defendingHome ? _homeAttacksRight : !_homeAttacksRight;
            float ownGoalX = ToLocal(PitchLayout.Keeper(attacksRight)).x;
            float towardOwnGoal = Mathf.Sign(ownGoalX - _ballPos.x);
            if (Mathf.Abs(towardOwnGoal) < 0.01f) towardOwnGoal = attacksRight ? -1f : 1f;

            float distance = Mathf.Lerp(76f, 60f, strength);
            float laneOffset = rank == 0 ? 0f : (rank == 1 ? 18f : -18f);
            Vector2 target = _ballPos + new Vector2(towardOwnGoal * distance, laneOffset);
            float xLimit = (_w - Pad * 2f) * 0.5f;
            float yLimit = (_h - Pad * 2f) * 0.5f;
            return new Vector2(Mathf.Clamp(target.x, -xLimit, xLimit), Mathf.Clamp(target.y, -yLimit, yLimit));
        }

        private void UpdateNoise(Vector2[] noise, float[] timers, float dt)
        {
            for (int i = 0; i < noise.Length; i++)
            {
                timers[i] -= dt;
                if (timers[i] > 0f) continue;
                RerollNoise(ref noise[i]);
                timers[i] = Rand(0.8f, 2.2f);
            }
        }

        // ------------------------------------------------------------------ scene scripts

        /// <summary>Variant lanes: which flank the move runs down (EventText's variant trick).</summary>
        private static float Lane(int variant) => variant == 0 ? 0.5f : variant == 1 ? 0.32f : 0.68f;

        /// <summary>Absolute (non-fractional) step seconds, honoring the presentation tempo.</summary>
        private float P(float seconds) => seconds * Mathf.Max(0.01f, paceScale);

        private static Step S(float dur, float bx, float by, float terr, float tempo,
            byte marker = MkNone, ScoreLedger.StagedGoal goal = default, byte route = RoutePass,
            bool atkPicked = true, bool chase = false)
            => new Step
            {
                Dur = dur, Ball = new Vector2(bx, by), Terr = terr, Tempo = tempo,
                Marker = marker, Goal = goal, Route = route, AtkPicked = atkPicked, Chase = chase,
            };

        /// <summary>Mirrors a picked-frame script across the halfway line and hands the move to
        /// the OTHER team (for/against pairs share one author).</summary>
        private static Step[] Mirror(Step[] steps)
        {
            var m = new Step[steps.Length];
            for (int i = 0; i < m.Length; i++)
            {
                m[i] = steps[i];
                m[i].Ball = new Vector2(1f - m[i].Ball.x, m[i].Ball.y);
                m[i].Terr = 1f - m[i].Terr;
                m[i].AtkPicked = !m[i].AtkPicked;
            }
            return m;
        }

        private Step[] BuildBeatScript(SceneSpec spec)
        {
            float lane = Lane(spec.Variant);
            float T = spec.Duration;
            float u = spec.Urgent ? 1f : 0f;
            var goal = spec.Goal ?? default;
            bool commits = spec.Goal.HasValue && spec.Goal.Value.Commits;

            // The #9 LeadChange intro composes a steal step in front and squeezes the base.
            float intro = spec.LeadChangeIntro ? Mathf.Min(1.0f, T * 0.18f) : 0f;
            float B = T - intro;

            Step[] core;
            switch (spec.Template)
            {
                case SceneTemplate.GoalFor:
                case SceneTemplate.GoalAgainst:
                    core = new[]
                    {
                        S(B * 0.22f, 0.56f, lane, 0.60f, Mathf.Max(0.55f, u)),
                        S(B * 0.20f, 0.80f, lane, 0.68f, Mathf.Max(0.7f, u)),
                        S(B * 0.12f, 0.90f, lane, 0.72f, 1f),                       // the final pass
                        S(B * 0.12f, 0.985f, 0.5f, 0.72f, 1f, MkGoal, goal, RouteShot),
                        // The long restart tail is deliberate (playtest #15): the reveal fires
                        // at the goal (66% in), so this whole walk-back plays with the market OPEN.
                        commits
                            ? S(B * 0.34f, 0.5f, 0.5f, 0.55f, 0.4f, route: RouteKickoff)
                            : S(B * 0.34f, 0.84f, 0.30f, 0.60f, 0.3f, route: RouteBackLine), // chalked: defenders restart
                    };
                    if (spec.Template == SceneTemplate.GoalAgainst) core = Mirror(core);
                    break;

                case SceneTemplate.BreakawayFor:
                case SceneTemplate.BreakawayAgainst:
                    core = new[]
                    {
                        S(B * 0.18f, 0.30f, 0.5f, 0.42f, 0.5f),                     // won it deep
                        S(B * 0.26f, 0.70f, lane, 0.58f, 1f, chase: true),          // the long carry, hunted
                        S(B * 0.12f, 0.88f, lane, 0.66f, 1f, chase: true),
                        S(B * 0.12f, 0.965f, spec.Variant == 2 ? 0.58f : 0.42f, 0.70f, 1f, MkGoal, goal, RouteShot),
                        commits
                            ? S(B * 0.32f, 0.5f, 0.5f, 0.55f, 0.4f, route: RouteKickoff)
                            : S(B * 0.32f, 0.84f, 0.30f, 0.60f, 0.3f, route: RouteBackLine),
                    };
                    if (spec.Template == SceneTemplate.BreakawayAgainst) core = Mirror(core);
                    break;

                case SceneTemplate.TerritoryFor:
                case SceneTemplate.TerritoryAgainst:
                    core = new[]
                    {
                        S(B * 0.35f, 0.55f, lane, 0.56f, Mathf.Max(0.5f, u)),
                        S(B * 0.35f, 0.62f, 1f - lane, 0.62f, Mathf.Max(0.5f, u)),
                        S(B * 0.30f, 0.60f, 0.5f, 0.62f, 0.4f),
                    };
                    if (spec.Template == SceneTemplate.TerritoryAgainst) core = Mirror(core);
                    break;

                case SceneTemplate.NearMissHope:
                case SceneTemplate.NearMissScare:
                    core = new[]
                    {
                        S(B * 0.26f, 0.62f, lane, 0.62f, 0.7f),
                        S(B * 0.20f, 0.86f, lane, 0.68f, 1f),
                        S(B * 0.12f, 0.99f, 0.47f, 0.72f, 1f, route: RouteShot),     // the shot
                        S(B * 0.10f, 0.94f, 0.82f, 0.70f, 1f, MkSave, route: RouteAuthored), // off the bar
                        S(B * 0.12f, 0.92f, 0.80f, 0.70f, 0f, route: RouteAuthored), // the hold — dead air
                        S(B * 0.20f, 0.60f, 0.35f, 0.58f, 0.3f, route: RouteBackLine), // cleared off the line
                    };
                    if (spec.Template == SceneTemplate.NearMissScare) core = Mirror(core);
                    break;

                case SceneTemplate.CalmPossession:
                {
                    core = new[]
                    {
                        S(B * 0.35f, 0.46f, 0.40f, 0.50f, 0.2f, atkPicked: spec.ForPicked),
                        S(B * 0.35f, 0.54f, 0.60f, 0.50f, 0.2f, atkPicked: spec.ForPicked),
                        S(B * 0.30f, 0.48f, 0.5f, 0.50f, 0.15f, atkPicked: spec.ForPicked),
                    };
                    break;
                }

                case SceneTemplate.Kickoff:
                    core = new[] { S(B, 0.5f, 0.5f, 0.5f, 0.3f, route: RouteKickoff, atkPicked: spec.ForPicked) };
                    break;

                case SceneTemplate.LegFinalWon:
                case SceneTemplate.LegFinalLost:
                    // The orchestrator should route finals through PlayFinalScene; keep the
                    // resolver total anyway with a plan-free final shape.
                    return BuildFinalScript(spec, new ScoreLedger.FinalPlan(
                        spec.Template == SceneTemplate.LegFinalWon ? LegGrade.Won : LegGrade.Lost,
                        Array.Empty<ScoreLedger.StagedGoal>()));

                default: // #15 fallback: a neutral attack fizzles out
                    core = new[]
                    {
                        S(B * 0.40f, 0.60f, lane, 0.55f, 0.5f, atkPicked: spec.ForPicked),
                        S(B * 0.30f, 0.72f, 1f - lane, 0.58f, 0.5f, atkPicked: spec.ForPicked),
                        S(B * 0.30f, 0.50f, 0.5f, 0.52f, 0.3f, atkPicked: spec.ForPicked),
                    };
                    break;
            }

            if (intro <= 0f) return core;

            // Steal → transition: the ball flips flanks at midfield before the move starts.
            var withIntro = new Step[core.Length + 1];
            withIntro[0] = S(intro, 0.42f, 1f - lane, 0.46f, 1f, atkPicked: core[0].AtkPicked);
            Array.Copy(core, 0, withIntro, 1, core.Length);
            return withIntro;
        }

        private Step[] BuildFinalScript(SceneSpec spec, ScoreLedger.FinalPlan plan)
        {
            float lane = Lane(spec.Variant);
            bool won = spec.Template == SceneTemplate.LegFinalWon || plan.Grade == LegGrade.Won;
            float B = spec.Duration; // base seconds; corrections are absolute sub-scenes on top

            var steps = new System.Collections.Generic.List<Step>(4 + plan.Goals.Length * 2);
            if (won)
            {
                steps.Add(S(B * 0.40f, 0.62f, 0.5f, 0.64f, 0.6f));   // the pre-reveal hold
                steps.Add(S(B * 0.27f, 0.78f, lane, 0.70f, 0.85f));
                foreach (ScoreLedger.StagedGoal g in plan.Goals)
                {
                    steps.Add(S(P(1.1f), 0.86f, 1f - lane, 0.72f, 1f)); // the break at the death
                    steps.Add(S(P(1.4f), 0.975f, 0.5f, 0.74f, 1f, MkGoal, g, RouteShot));
                }
                steps.Add(S(B * 0.33f, 0.5f, 0.5f, 0.72f, 1f, route: RouteAuthored)); // whistle — celebrate
            }
            else
            {
                steps.Add(S(B * 0.40f, 0.38f, 0.5f, 0.36f, 0.6f, atkPicked: false));  // the dread hold
                steps.Add(S(B * 0.27f, 0.22f, lane, 0.30f, 0.8f, atkPicked: false));
                foreach (ScoreLedger.StagedGoal g in plan.Goals)
                {
                    steps.Add(S(P(1.0f), 0.13f, lane, 0.28f, 1f, atkPicked: false, chase: true));
                    steps.Add(S(P(1.5f), 0.025f, 0.5f, 0.26f, 1f, MkGoal, g, RouteShot, atkPicked: false));
                }
                steps.Add(S(B * 0.33f, 0.5f, 0.5f, 0.26f, 0.1f, route: RouteAuthored, atkPicked: false)); // collapse
            }
            return steps.ToArray();
        }

        private Step[] BuildKillShotScript(int variant)
        {
            float lane = Lane(variant);
            return new[]
            {
                S(P(0.9f), 0.30f, lane, 0.34f, 0.8f, atkPicked: false),                 // opponent buildup
                S(P(0.6f), 0.14f, lane, 0.30f, 1f, atkPicked: false, chase: true),      // the approach
                S(P(0.35f), 0.10f, 0.5f, 0.28f, 1f, route: RouteShot, atkPicked: false), // shot launched
                S(P(0.20f), 0.05f, 0.5f, 0.28f, 1f, MkSuspend, route: RouteAuthored, atkPicked: false), // FROZEN
            };
        }

        private Step[] BuildContinuationScript(ScoreLedger.FinalPlan plan)
        {
            var steps = new System.Collections.Generic.List<Step>(2 + plan.Goals.Length * 2);
            switch (plan.Grade)
            {
                case LegGrade.Voided:
                    steps.Add(S(P(0.9f), 0.06f, 0.5f, 0.40f, 0.1f, MkVoid, route: RouteAuthored, atkPicked: false));
                    steps.Add(S(P(1.4f), 0.5f, 0.5f, 0.50f, 0.1f, route: RouteAuthored)); // the scene dissolves
                    break;

                case LegGrade.Won:
                    steps.Add(S(P(0.7f), 0.20f, 0.78f, 0.40f, 1f, MkSave, route: RouteAuthored, atkPicked: false));
                    foreach (ScoreLedger.StagedGoal g in plan.Goals)
