                    Ui.WriteLine(ConsoleColor.Yellow, $"  CASHED OUT: {Ui.Money(amt)}");
                    lastBank = run.Bank; // the credit is the CASHED OUT line; don't double-report it
                    return;

                case Input.FastForward:
                    fastForward = true;
                    break;
            }
        }
    }

